export function LookPicker() {
  const { prefs, setPrefs } = useSaved();
  const dayLook = useDayLook();
  const picked = prefs.theme ?? DEFAULT_LOOK;
  const auto = prefs.autoNight !== false;
  // With Follow the day on, the card that's on is the look showing now.
  const showing = lookNow(picked, auto, dayLook);
  const pick = (key: ThemeName) => {
    if (key === showing) return;
    tap();
    if (Platform.OS !== 'web') resumeAt('/look'); // come back here after the redraw
    // Picking a look here means "keep this one": Follow the day turns off.
    setPrefs({ ...prefs, theme: key, autoNight: false });
  };
  return (
    <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 10, marginTop: 8 }}>
      {LOOKS.map((l) => {
        const on = showing === l.key;
        return (
          <Pressable key={l.key} onPress={() => pick(l.key)} accessibilityRole="radio" accessibilityState={{ checked: on }}
            accessibilityLabel={`${l.name} look. ${l.sub}`} style={({ pressed }) => [s.card, on && s.on, pressed && { opacity: 0.85 }]}>
            {/* Tiny preview of the look */}
            <View style={[s.preview, { backgroundColor: l.page }]}>
              <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}>
                <Text style={{ fontFamily: F.logo, fontSize: 8, color: l.ink }}><Text style={{ color: l.gold }}>CAR</Text>vessa</Text>
                {isDarkLook(l.key) ? <Moon color={l.gold} /> : <Sun color={l.gold} />}
              </View>
              <View style={[s.bar, { backgroundColor: l.card, width: '90%' }]} />
              <View style={[s.bar, { backgroundColor: l.card, width: '70%' }]} />
              <View style={[s.bar, { backgroundColor: l.gold, width: '55%', height: 10 }]} />
            </View>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginTop: 8 }}>
              <View style={[s.radio, on && { borderColor: C.yellow }]}>{on && <View style={s.dot} />}</View>
              <Text style={s.name}>{l.name}</Text>
            </View>
            <Text style={s.sub}>{l.sub}</Text>
          </Pressable>
        );
      })}
    </View>
  );
}

