// Follow the day (picture 133, Oct 24, 2026): the four looks take turns by the sun where they are, with today's times.
const DAY_NAMES: Record<string, { name: string; color: string }> = {
  clean: { name: 'Clean', color: '#BFDDF5' }, calm: { name: 'Sunset Calm', color: '#F9C99B' },
  calmNight: { name: 'Sunset Calm night', color: '#2E4A3C' }, cleanNight: { name: 'Clean night', color: '#18233A' },
};
const clock = (ms: number) => new Date(ms).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });

export function FollowDay() {
  const { prefs, setPrefs } = useSaved();
  const { now, spot } = useSunPlace();
  const on = prefs.autoNight !== false;
  const plan = dayPlan(now, spot.lat, spot.lon);
  const showroom = lightDarkOf(prefs.theme, prefs.autoNight) !== null;
  const set = (v: boolean) => {
    tap();
    if (Platform.OS !== 'web') resumeAt('/look');
    // Turning it on with one of the other looks picked starts the day looks from Clean.
    setPrefs({ ...prefs, autoNight: v, ...(v && !followsDay(prefs.theme ?? DEFAULT_LOOK) ? { theme: 'showroom' as ThemeName } : {}) });
  };
  // The showroom looks use Light or dark (above) instead.
  if (showroom) return null;
  return (
    <View>
      <View style={s.auto}>
        <View style={{ flex: 1 }}>
          <Text style={s.name}>Follow the day</Text>
          <Text style={s.sub}>Clean in the morning, Sunset Calm at sunset, Sunset Calm night in the evening, Clean night late at night.</Text>
        </View>
        <Switch value={on} onValueChange={set} trackColor={{ true: C.yellow, false: C.line }} thumbColor="#FFFFFF" {...{ activeThumbColor: '#FFFFFF' }} accessibilityLabel="Follow the day" />
      </View>
      {on && plan && (
        <View style={s.plan}>
          {plan.map((p, i) => (
            <View key={p.look} style={[s.planRow, i === plan.length - 1 && { borderBottomWidth: 0 }]}>
              <View style={[s.swatch, { backgroundColor: DAY_NAMES[p.look].color }]} />
              <Text style={[s.name, { fontSize: 14, flex: 1 }]}>{DAY_NAMES[p.look].name}</Text>
              <Text style={s.sub}>{`${clock(p.from)} – ${clock(p.to)}`}</Text>
            </View>
          ))}
          <Text style={[s.sub, { marginTop: 6 }]}>Times follow the sun where you are and change with the seasons.</Text>
        </View>
      )}
    </View>
  );
}

// Light or dark (Loudjier, Nov 6, 2026: "the option to use light or dark in the settings"): the showroom
// looks as one clear choice. Auto = light in the day, the dark showroom after sunset where they are.
type Mode = 'auto' | 'light' | 'dark';
export const lightDarkOf = (theme: ThemeName | undefined, autoNight: boolean | undefined): Mode | null => {
  const t = theme ?? DEFAULT_LOOK;
  if (autoNight !== false) return 'auto';
  return isDarkLook(t) ? 'dark' : 'light';
};

// Picture 201 C (Loudjier's pick): today's sun path with the times it gets light and dark where they are.
function SunPath({ now, lightAt, darkAt }: { now: number; lightAt: number; darkAt: number }) {
  const dark = now < lightAt || now >= darkAt;
  const t = Math.max(0, Math.min(1, (now - lightAt) / Math.max(1, darkAt - lightAt)));
  // Point on the arc M20 80 Q180 -30 340 80 (a quadratic curve).
  const x = (1 - t) * (1 - t) * 20 + 2 * (1 - t) * t * 180 + t * t * 340;
  const y = (1 - t) * (1 - t) * 80 + 2 * (1 - t) * t * -30 + t * t * 80;
  const night = isDarkLook(look);
  return (
    <View accessible accessibilityLabel={`Today: light at ${clock(lightAt)}, dark at ${clock(darkAt)}. ${dark ? 'It is dark now.' : 'It is light now.'}`}>
      <Svg width="100%" height={110} viewBox="0 0 360 116" preserveAspectRatio="xMidYMid meet">
        <Path d="M20 80 Q180 -30 340 80" fill={night ? '#20263A' : '#E3F1F8'} stroke={night ? '#8F7A4A' : '#E7C27A'} strokeWidth={3} strokeDasharray="6 6" />
        <Rect x={0} y={80} width={360} height={34} rx={8} fill={night ? '#0B1026' : '#1C2550'} />
        {dark ? (<>
          <Circle cx={326} cy={66} r={11} fill="#EDE6CF" /><Circle cx={332} cy={62} r={10} fill={night ? '#20263A' : '#E3F1F8'} />
          <Circle cx={80} cy={58} r={1.8} fill={night ? '#FFFFFF' : '#9AA4B2'} /><Circle cx={140} cy={30} r={1.4} fill={night ? '#FFFFFF' : '#9AA4B2'} /><Circle cx={250} cy={36} r={1.6} fill={night ? '#FFFFFF' : '#9AA4B2'} />
        </>) : <Circle cx={x} cy={y} r={13} fill="#F5B83D" />}
        <SvgText x={14} y={101} fill="#FFFFFF" fontSize={11.5} fontFamily={F.bodyBold}>{`${tr('light')} ${clock(lightAt)}`}</SvgText>
        <SvgText x={346} y={101} fill="#E2C27E" fontSize={11.5} fontFamily={F.bodyBold} textAnchor="end">{`${tr('dark')} ${clock(darkAt)}`}</SvgText>
      </Svg>
    </View>
  );
}

export function LightDark() {
  const { prefs, setPrefs } = useSaved();
  const { now, spot } = useSunPlace();
  const mode = lightDarkOf(prefs.theme, prefs.autoNight);
  const plan = dayPlan(now, spot.lat, spot.lon);
  const darkAt = plan?.find((p) => p.look === 'calmNight')?.from;
  const lightAt = plan?.find((p) => p.look === 'clean')?.from;
  const pick = (m: Mode) => {
    if (m === mode) return;
    tap();
    if (Platform.OS !== 'web') resumeAt('/look');
    const [light, dark] = FAMILY[famOf(prefs.theme ?? DEFAULT_LOOK)];
    setPrefs({ ...prefs, theme: m === 'dark' ? dark : light, autoNight: m === 'auto' });
  };
  const OPTS: { m: Mode; label: string; icon: (c: string) => React.ReactNode }[] = [
    { m: 'auto', label: 'Auto', icon: (c) => <Svg width={20} height={20} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={2} strokeLinecap="round"><Circle cx="12" cy="12" r="8" /><Path d="M12 4a8 8 0 0 1 0 16z" fill={c} /></Svg> },
    { m: 'light', label: 'Light', icon: (c) => <Sun color={c} /> },
    { m: 'dark', label: 'Dark', icon: (c) => <Moon color={c} /> },
  ];
  return (
    <View style={[{ marginTop: 8 }, s.pathCard]}>
      {lightAt && darkAt ? <SunPath now={now.getTime()} lightAt={lightAt} darkAt={darkAt} /> : null}
      <View style={s.seg} accessibilityRole="radiogroup">
        {OPTS.map((o) => {
          const on = mode === o.m;
          return (
            <Pressable key={o.m} onPress={() => pick(o.m)} accessibilityRole="radio" accessibilityState={{ checked: on }} accessibilityLabel={o.label}
              style={[s.segBtn, on && s.segOn]}>
              {o.icon(on ? pickedInk() : C.muted)}
              <Text style={[s.segText, on && { color: pickedInk() }]}>{o.label}</Text>
            </Pressable>
          );
        })}
      </View>
      <Text style={[s.sub, { marginTop: 8 }]}>
        {mode === 'auto' ? 'Light in the day, dark after sunset where you are.' : mode === 'light' ? 'Always light.' : mode === 'dark' ? 'Always dark.' : 'You picked one of the looks below. Tap Auto, Light or Dark to go back to the showroom look.'}
      </Text>
    </View>
  );
}

