// Real car dealers near a ZIP code, from OpenStreetMap (free, © OpenStreetMap contributors, ODbL).
// ZIP → map point comes from Zippopotam.us. Cars for sale with prices need a paid listings
// service (like MarketCheck) and come later.
import snapshot from './dealers-snapshot.json';
import { lastSpot } from '@/lib/location';

export type Dealer = {
  id: string;
  name: string;
  miles: number;
  address?: string;
  phone?: string;
  website?: string;
  lat: number;
  lon: number;
};
export type DealerResult = { place: string; dealers: Dealer[]; saved?: string };

// Brand of each car, as dealers write it on their sign.
export const BRAND: Record<string, string> = {
  trax: 'Chevrolet', encore: 'Buick', kona: 'Hyundai', rav4: 'Toyota', crv: 'Honda', telluride: 'Kia',
  sienna: 'Toyota', maverick: 'Ford', f150: 'Ford', bronco: 'Ford', corolla: 'Toyota', civic: 'Honda',
  versa: 'Nissan', mirage: 'Mitsubishi', elantra: 'Hyundai', k4: 'Kia', equinox: 'Chevrolet', camry: 'Toyota', accord: 'Honda',
  outback: 'Subaru', model3: 'Tesla', modely: 'Tesla', tacoma: 'Toyota', wrangler: 'Jeep', highlander: 'Toyota', odyssey: 'Honda',
  silverado: 'Chevrolet', ram1500: 'Ram', lexusrx: 'Lexus', bmwx5: 'BMW', gle: 'Mercedes-Benz', escalade: 'Cadillac',
  rangerover: 'Land Rover', gclass: 'Mercedes-Benz', p911: 'Porsche',
};

const SNAP = snapshot as unknown as { saved: string; zip: string; place: string; brands: Record<string, Dealer[]> };
// The free map services ask apps to say who they are. (Web browsers ignore this header.)
const UA: Record<string, string> = { Accept: 'application/json', 'User-Agent': 'Carvessa/0.1 (https://carvessa.app)' };

async function getJson(url: string, init?: RequestInit) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 25000);
  try {
    const r = await fetch(url, { ...init, signal: ctrl.signal });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return await r.json();
  } finally {
    clearTimeout(t);
  }
}

export function milesBetween(aLat: number, aLon: number, bLat: number, bLon: number) {
  const R = 3958.8, rad = Math.PI / 180;
  const dLat = (bLat - aLat) * rad, dLon = (bLon - aLon) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(aLat * rad) * Math.cos(bLat * rad) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

export function parseDealers(j: any, lat: number, lon: number): Dealer[] {
  const seen = new Set<string>();
  const out: Dealer[] = [];
  for (const e of j?.elements ?? []) {
    const t = e.tags ?? {};
    const la = e.lat ?? e.center?.lat, lo = e.lon ?? e.center?.lon;
    if (!t.name || la == null || lo == null) continue;
    const key = String(t.name).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    const street = [t['addr:housenumber'], t['addr:street']].filter(Boolean).join(' ');
    const city = [t['addr:city'], t['addr:state']].filter(Boolean).join(', ');
    out.push({
      id: `${e.type}/${e.id}`,
      name: String(t.name),
      miles: Math.round(milesBetween(lat, lon, la, lo) * 10) / 10,
      address: [street, city].filter(Boolean).join(', ') || undefined,
      phone: t.phone ?? t['contact:phone'],
      website: t.website ?? t['contact:website'],
      lat: la,
      lon: lo,
    });
  }
  return out.sort((a, b) => a.miles - b.miles);
}

// Backup source (OpenStreetMap's search service) used when the main map server is busy.
export function parseNominatim(list: any[], brand: string, lat: number, lon: number, radiusMiles: number): Dealer[] {
  const seen = new Set<string>();
  const out: Dealer[] = [];
  for (const x of list ?? []) {
    if (x.category !== 'shop' || x.type !== 'car') continue;
    const la = Number(x.lat), lo = Number(x.lon);
    const miles = Math.round(milesBetween(lat, lon, la, lo) * 10) / 10;
    if (miles > radiusMiles) continue;
    const raw = String(x.name || brand);
    const name = raw.toLowerCase() === brand.toLowerCase() ? `${brand} dealer` : raw;
    const a = x.address ?? {};
    const street = [a.house_number, a.road].filter(Boolean).join(' ');
    const city = [a.city ?? a.town ?? a.village ?? a.suburb, a.state].filter(Boolean).join(', ');
    const key = `${name}|${street}`.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    const t = x.extratags ?? {};
    out.push({ id: `${x.osm_type}/${x.osm_id}`, name, miles, address: [street, city].filter(Boolean).join(', ') || undefined,
      phone: t.phone ?? t['contact:phone'], website: t.website ?? t['contact:website'], lat: la, lon: lo });
  }
  return out.sort((p, q) => p.miles - q.miles);
}

async function nominatim(brand: string, lat: number, lon: number, radiusMiles: number) {
  const dLat = radiusMiles / 69, dLon = radiusMiles / (69 * Math.cos((lat * Math.PI) / 180));
  const box = [lon - dLon, lat + dLat, lon + dLon, lat - dLat].map((n) => n.toFixed(4)).join(',');
  const j = await getJson(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(brand)}&format=jsonv2&viewbox=${box}&bounded=1&limit=40&extratags=1&addressdetails=1`, { headers: UA });
  return parseNominatim(j, brand, lat, lon, radiusMiles);
}

export async function zipToPlace(zip: string) {
  const j = await getJson(`https://api.zippopotam.us/us/${encodeURIComponent(zip)}`);
  const p = j?.places?.[0];
  if (!p) throw new Error('ZIP not found');
  return { lat: Number(p.latitude), lon: Number(p.longitude), place: `${p['place name']}, ${p['state abbreviation']}` };
}

export async function findDealers(brand: string, zip: string, radiusMiles = 30): Promise<DealerResult> {
  try {
    const town = await zipToPlace(zip);
    // "Use my location" (picture 125): measure from where they really are when that spot is in this ZIP.
    const spot = lastSpot();
    const { lat, lon } = spot && spot.zip === zip ? spot : town;
    const place = town.place;
    const m = Math.round(radiusMiles * 1609);
    const re = brand.replace(/[^A-Za-z ]/g, '');
    const q = `[out:json][timeout:25];(nwr["shop"="car"]["brand"~"${re}",i](around:${m},${lat},${lon});nwr["shop"="car"]["name"~"${re}",i](around:${m},${lat},${lon}););out center tags 60;`;
    const ask = () => getJson('https://overpass-api.de/api/interpreter', {
      method: 'POST',
      headers: { ...UA, 'Content-Type': 'application/x-www-form-urlencoded' },
      body: `data=${encodeURIComponent(q)}`,
    });
    // The free map server is sometimes busy; wait a moment and try once more.
    try {
      const j = await ask().catch(() => new Promise((r) => setTimeout(r, 2500)).then(ask));
      return { place, dealers: parseDealers(j, lat, lon) };
    } catch {
      return { place, dealers: await nominatim(brand, lat, lon, radiusMiles) };
    }
  } catch (e) {
    // No internet: use the saved list if it is for the same ZIP.
    if (zip === SNAP.zip && SNAP.brands[brand]) return { place: SNAP.place, dealers: SNAP.brands[brand], saved: SNAP.saved };
    throw e;
  }
}
