// Writing in the help chat (picture 114, Loudjier Oct 19, 2026: "top: B, bottom: 1 and 3"). No AI:
// (3) safety words always come first with our own red step, (1) words we know open our checked steps, and an
// answer to the current question is matched to its chip. English and Spanish words.
import { tr } from '@/i18n';
import type { HelpAct } from '@/data/light-help';

export type Target = { kind: 'light' | 'weird'; id: string };
export type SafetyHit = { text: string; acts: HelpAct[]; call911?: boolean };

const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();

// (3) Safety words. Checked before anything else, always our own words.
const SAFETY: { re: RegExp; hit: SafetyHit }[] = [
  { re: /\b(fire|flames?|on fire|fuego|llamas?|incendio)\b/, hit: { text: 'Pull over, turn the car off and get everyone out. Stay away from the car and call 911.', acts: ['tow'], call911: true } },
  { re: /\b(smoke|smoking|humo)\b/, hit: { text: 'Pull over, turn the car off and get everyone out. Stay away from the car. If you see flames, call 911.', acts: ['tow'], call911: true } },
  { re: /\b(smell(s)? (like )?gas|gas smell|gasoline smell|leaking gas|gas leak|huele a gasolina|olor a gasolina|fuga de gasolina)\b/, hit: { text: 'A gas smell or gas leak is a fire risk. Don’t drive and don’t smoke. Stay away from the car and call for help.', acts: ['tow'] } },
  { re: /\b(no brakes?|brakes? (are |feel |went )?(soft|spongy|gone|not working|failed|went out)|pedal (goes|went) to the floor|sin frenos|frenos? (suaves?|no sirven|fallaron))\b/, hit: { text: 'Soft or weak brakes: stop driving and call for help.', acts: ['tow'] } },
  { re: /\b(steam|steaming|boiling|vapor)\b/, hit: { text: 'Stay back from the hood until the steam stops. Don’t open the hood or the radiator cap while it’s hot. Turn the engine off.', acts: ['tow'] } },
];
// "no", "not", "isn't"… just before a word turns it around ("the tire is not flat", "no smoke").
const NOT = new Set(['no', 'not', 'never', 'isn', 'isnt', 'doesn', 'doesnt', 'don', 'dont', 'wasn', 'wasnt', 'aren', 'arent', 'without', 'nunca', 'sin', 'ni']);
const UNSURE = /\b(not sure|unsure|idk|i dont know|i don t know|dont know|don t know|no idea|no se|no estoy segur[oa])\b/;
const negated = (before: string) => before.split(' ').filter((w) => w && w !== 't').slice(-2).some((w) => NOT.has(w));
export function safetyHit(text: string): SafetyHit | null {
  const t = norm(text);
  for (const s of SAFETY) {
    const re = new RegExp(s.re.source, 'g');
    for (const m of t.matchAll(re)) {
      // "no brakes" carries its own "no"; any other safety word right after "no" is ruled out ("no smoke").
      if (/^(no|sin) /.test(m[0]) || !negated(t.slice(0, m.index))) return s.hit;
    }
  }
  return null;
}

// (1) Words that point to one of our chats. Order matters: the first match wins.
const TOPICS: { re: RegExp; to: Target }[] = [
  { re: /\b(gas cap|fuel cap|gas door|fuel door|filler (cap|door)|check (gas|fuel) cap|(gas|fuel) tank (is )?open|(gas|fuel) (door|cap) (is )?open|tapa de (la )?gasolina|tanque (de gasolina )?abierto|puerta de (la )?gasolina)\b/, to: { kind: 'weird', id: 'gascap' } },
  { re: /\b(grind|grinding|scrap(e|ing)|metal on metal|raspa|rechina el metal)\b/, to: { kind: 'weird', id: 'grind' } },
  { re: /\b(squeak|squeal|squeaking|squealing|chill(a|ido))\b/, to: { kind: 'weird', id: 'squeak' } },
  { re: /\b(shak(e|es|ing)|vibrat(e|es|ing|ion)|wobbl(e|es|ing)|tiembla|vibra)\b.*\b(brak(e|es|ing)|stop(ping)?|fren(o|ar|ando))\b|\b(brak(e|es|ing)|fren(o|ar))\b.*\b(shak(e|es|ing)|vibrat|tiembla)\b/, to: { kind: 'weird', id: 'shake-brake' } },
  { re: /\b(shak(e|es|ing)|vibrat(e|es|ing|ion)|wobbl(e|es|ing)|tiembla|vibra)\b/, to: { kind: 'weird', id: 'shake-speed' } },
  { re: /\b(pulls?|pulling|drifts?|jala|se va de lado)\b/, to: { kind: 'weird', id: 'pull' } },
  { re: /\b(won ?t start|wont start|doesn ?t start|no start|not starting|hard to start|clicking when i start|no prende|no arranca)\b/, to: { kind: 'weird', id: 'wont-start' } },
  { re: /\b(sweet|syrup|maple|dulce|jarabe)\b/, to: { kind: 'weird', id: 'sweet' } },
  { re: /\b(burn(ing|t)?|quemad[oa]|huele a quemado)\b/, to: { kind: 'weird', id: 'burning' } },
  { re: /\b(leak(s|ing)?|drip(s|ping)?|puddle|fuga|gotea|charco)\b/, to: { kind: 'weird', id: 'leak' } },
  { re: /\b(clunk(s|ing)?|knock(s|ing)? over bumps|bumps?|golpe(a|s)?|baches?)\b/, to: { kind: 'weird', id: 'clunk' } },
  { re: /\b(click(s|ing)?|clic)\b.*\b(turn(s|ing)?|vuelta)\b|\b(turn(s|ing)?)\b.*\b(click(s|ing)?)\b/, to: { kind: 'weird', id: 'noise-turn' } },
  { re: /\b(overheat(s|ing|ed)?|too hot|running hot|temperature|temp gauge|se calienta|calentando|temperatura)\b/, to: { kind: 'light', id: 'temp' } },
  { re: /\b(oil (light|pressure)|aceite)\b/, to: { kind: 'light', id: 'oil' } },
  { re: /\b(check engine|engine light|motor (light|luz)|luz del motor)\b/, to: { kind: 'light', id: 'engine' } },
  { re: /\b(tire|tyre|tpms|flat|nail|llanta|ponchad[ao]|clavo)\b/, to: { kind: 'light', id: 'tire' } },
  { re: /\b(battery|alternator|charging|bateria|alternador)\b/, to: { kind: 'light', id: 'battery' } },
  { re: /\babs\b/, to: { kind: 'light', id: 'abs' } },
  { re: /\b(air ?bag|bolsa de aire)\b/, to: { kind: 'light', id: 'airbag' } },
  { re: /\b(traction|stability|slip|patina|traccion)\b/, to: { kind: 'light', id: 'traction' } },
  { re: /\b(brake light|parking brake|freno de mano|luz de freno)\b/, to: { kind: 'light', id: 'brake' } },
  { re: /\b(service|maintenance|oil change|mantenimiento|cambio de aceite)\b/, to: { kind: 'light', id: 'service' } },
  { re: /\b(low fuel|gas light|out of gas|poca gasolina|sin gasolina)\b/, to: { kind: 'light', id: 'fuel' } },
  { re: /\b(washer|wiper fluid|limpiaparabrisas)\b/, to: { kind: 'light', id: 'washer' } },
];
export function topicFor(text: string): Target | null {
  const t = norm(text);
  return TOPICS.find((x) => x.re.test(t))?.to ?? null;
}

// An answer to the question on screen: pick the chip whose words match best (English or Spanish chip text).
const SKIP = new Set(['i', 'it', 'the', 'a', 'an', 'is', 'its', 'to', 'of', 'or', 'and', 'my', 'me', 'on', 'in', 'el', 'la', 'los', 'las', 'es', 'de', 'y', 'o', 'mi', 'un', 'una', 'en']);
const stem = (w: string) => w.length > 4 ? w.replace(/(ing|ed|es|s)$/, '') : w;
const words = (s: string) => norm(s).split(' ').filter((w) => w && !SKIP.has(w));
export function optionFor(text: string, labels: string[]): number {
  const all = norm(text).split(' ').filter(Boolean);
  const said = new Set(words(text));
  if (!said.size) return -1;
  // Words they turned around ("not flat"). A chip built on one of them can't be their answer.
  const turned = new Set(all.filter((w, i) => !NOT.has(w) && negated(all.slice(0, i).join(' '))).map(stem));
  const unsure = (l: string) => UNSURE.test(norm(l));
  // "I don't know" / "no idea" answers a "Not sure" chip.
  if (UNSURE.test(norm(text))) {
    const i = labels.findIndex((l) => unsure(l) || unsure(tr(l)));
    if (i >= 0) return i;
  }
  const out = new Set<number>();
  let best = -1;
  let bestScore = 0;
  labels.forEach((label, i) => {
    for (const l of [label, tr(label)]) {
      const w = words(l);
      if (!w.length) continue;
      if (!w.some((x) => NOT.has(x)) && w.some((x) => turned.has(stem(x)))) { out.add(i); continue; }
      const hit = w.filter((x) => said.has(x)).length;
      // "yes"/"no"/"si" alone answer a yes/no chip.
      const yn = (said.has('yes') || said.has('si') || said.has('yeah') || said.has('yep') || said.has('yup')) && /^(yes|si)\b/.test(norm(l)) ? 1 : (said.has('no') || said.has('nope') || said.has('nah')) && /^no\b/.test(norm(l)) ? 1 : 0;
      const score = hit / w.length + yn;
      if (score > bestScore) { bestScore = score; best = i; }
    }
  });
  if (bestScore >= 0.5) return best;
  // They ruled a chip out ("I'm not driving", "no nail"): if one clear answer is left, that's theirs.
  if (out.size) {
    const left = labels.map((l, i) => i).filter((i) => !out.has(i) && !unsure(labels[i]));
    if (left.length === 1) return left[0];
    const neg = left.filter((i) => words(labels[i]).some((x) => NOT.has(x)));
    if (neg.length === 1) return neg[0];
  }
  return -1;
}

// A flow's own shortcuts: words that answer the whole talk at once ("air is at 35 psi but the light stays on").
export function shortcutFor(text: string, shortcuts: { re: RegExp; next: string }[] | undefined): string | null {
  const t = norm(text);
  return shortcuts?.find((x) => x.re.test(t))?.next ?? null;
}
