// Guests can save up to 3 cars; more needs a free account (Loudjier's free-account plan, Oct 18, 2026).
import { useAuth } from '@/state/auth';
import { useSaved } from '@/state/saved';

export const GUEST_SAVES = 3;

export function useSaveToggle() {
  const { session, askAccount } = useAuth();
  const { saved, isSaved, toggleSaved } = useSaved();
  return (id: string, year: number) => {
    if (!session && !isSaved(id, year) && saved.length >= GUEST_SAVES) {
      askAccount('Save more than 3 cars', 'A free account keeps all your saved cars, on any phone. No spam, never sold.');
      return false;
    }
    toggleSaved(id, year);
    return true;
  };
}
