// Pick your car: year, then brand, then model (Upgrade A, picked Oct 10, 2026).
// Models come free from NHTSA. If that fails, we show the models we know and the box to type.
import { useEffect, useState } from 'react';
import { ActivityIndicator, ScrollView, StyleSheet, View } from 'react-native';

import { Btn, tap } from '@/components/ui';
import { CARS } from '@/data/cars';
import { modelsFor } from '@/data/gov';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';
import { thisYear } from '@/data/year';

// The phone's year + 1 (next year's models go on sale in the fall), 20 years back.
const YEARS = Array.from({ length: 20 }, (_, i) => thisYear() + 1 - i);
export const BRANDS = ['Chevrolet', 'Toyota', 'Honda', 'Ford', 'Nissan', 'Hyundai', 'Kia', 'Jeep', 'GMC', 'Dodge', 'Ram', 'Subaru', 'Mazda', 'Volkswagen', 'Tesla', 'Buick', 'Lexus', 'BMW', 'Mercedes-Benz', 'Audi', 'Chrysler', 'Mitsubishi', 'Acura', 'Infiniti', 'Cadillac'];
// Our car data says "Chevy"; NHTSA says "Chevrolet".
const short = (b: string) => (b === 'Chevrolet' ? 'Chevy' : b);

function Pill({ label, on, onPress }: { label: string; on: boolean; onPress: () => void }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" accessibilityState={{ selected: on }}
      style={[s.pill, on && { backgroundColor: C.fill, borderColor: C.fill }]}>
      <Text style={[s.pillText, on && { color: C.onAccent }]}>{label}</Text>
    </Pressable>
  );
}

export function CarPicker({ onDone }: { onDone: (car: string) => void }) {
  const [year, setYear] = useState<number | null>(null);
  const [brand, setBrand] = useState<string | null>(null);
  const [model, setModel] = useState<string | null>(null);
  const [loaded, setLoaded] = useState<{ key: string; list: string[] } | null>(null);
  const key = `${brand}|${year}`;
  const loading = !!year && !!brand && loaded?.key !== key;
  const models = loaded?.key === key ? loaded.list : null;

  useEffect(() => {
    if (!year || !brand) return;
    let on = true;
    const known = CARS.filter((c) => c.make === short(brand)).map((c) => c.model);
    modelsFor(brand, year).then((m) => (m.length ? m : known)).catch(() => known)
      .then((list) => { if (on) setLoaded({ key: `${brand}|${year}`, list }); });
    return () => { on = false; };
  }, [year, brand]);

  return (
    <View style={{ gap: 8, marginBottom: 8 }}>
      <Text style={s.label}>{year ? `Year · ${year}` : '1 · Year'}</Text>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6 }} keyboardShouldPersistTaps="handled">
        {YEARS.map((y) => <Pill key={y} label={String(y)} on={year === y} onPress={() => { setYear(y); setModel(null); }} />)}
      </ScrollView>
      {!!year && (
        <>
          <Text style={s.label}>{brand ? `Brand · ${brand}` : '2 · Brand'}</Text>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6 }} keyboardShouldPersistTaps="handled">
            {BRANDS.map((b) => <Pill key={b} label={b} on={brand === b} onPress={() => { setBrand(b); setModel(null); }} />)}
          </ScrollView>
        </>
      )}
      {!!year && !!brand && (
        <>
          <Text style={s.label}>{model ? `Model · ${model}` : '3 · Model'}</Text>
          {loading ? <ActivityIndicator color={C.yellow} style={{ alignSelf: 'flex-start' }} /> : (
            <ScrollView style={{ maxHeight: 96 }} contentContainerStyle={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6 }} keyboardShouldPersistTaps="handled">
              {(models ?? []).map((m) => <Pill key={m} label={m} on={model === m} onPress={() => setModel(m)} />)}
              {!models?.length && <Text style={s.hint}>No list for this one. Type it in the box below.</Text>}
            </ScrollView>
          )}
        </>
      )}
      {!!year && !!brand && !!model && <Btn small kind="yellow" label={`That’s my car: ${year} ${model}`} onPress={() => onDone(`${year} ${short(brand)} ${model}`)} />}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  label: { fontFamily: F.head, fontSize: 12, letterSpacing: 1.6, textTransform: 'uppercase', color: C.muted },
  pill: { borderRadius: 12, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, paddingHorizontal: 12, paddingVertical: 8 },
  pillText: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  hint: { fontFamily: F.body, fontSize: 13, color: C.muted },
}));
