// "You drive now" (pictures 205–207, 209–210): the car they're upgrading from, centered on a soft floor.
// Which picture, in order: 1 their own photo (kept only on the phone), 2 our cut-out of their model and year look,
// 3 a photo of a year that looks the same outside (with a small note), 4 a clean outline + "Photo coming for your car".
// Never a different car.
import { Image as ExpoImage } from 'expo-image';
import { LinearGradient } from 'expo-linear-gradient';
import { useState } from 'react';
import { StyleSheet, useWindowDimensions, View } from 'react-native';
import Svg, { Circle, Path } from 'react-native-svg';

import { CarCutout } from '@/components/car-photo';
import { PhotoSheet } from '@/components/scan-photo';
import { Pressable, Text } from '@/components/t';
import { notify } from '@/components/notify';
import { tap } from '@/components/ui';
import { carForMine } from '@/data/cars';
import { lookFor } from '@/data/own-looks';
import { myCarParts } from '@/data/step-up';
import { canPhoto } from '@/lib/photo';
import { carKey, sameCar, setCarPhoto, useCarPhoto } from '@/state/car-photos';
import type { Answers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { C, F, themed } from '@/theme';

function Outline({ color }: { color: string }) {
  return (
    <Svg width={150} height={70} viewBox="0 0 120 56" accessibilityElementsHidden>
      <Path d="M8 42v-9l9-14h52l16 14h22l5 9" fill="none" stroke={color} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" />
      <Path d="M8 42h104" stroke={color} strokeWidth={3} strokeLinecap="round" />
      <Circle cx={30} cy={44} r={7} fill={C.card} stroke={color} strokeWidth={3} />
      <Circle cx={90} cy={44} r={7} fill={C.card} stroke={color} strokeWidth={3} />
    </Svg>
  );
}

export function YourCar({ answers }: { answers: Answers }) {
  const width = useWindowDimensions().width;
  const { myCars } = useSaved();
  const [sheet, setSheet] = useState(false);
  const parts = myCarParts(answers);
  const garage = parts?.year ? myCars.find((c) => sameCar(c, { year: parts.year!, make: parts.make, model: parts.model })) : undefined;
  const key = parts?.year ? carKey({ year: parts.year, make: parts.make, model: parts.model }) : null;
  const own = useCarPhoto(key);
  if (!parts) return null;
  const name = `${parts.year ?? ''} ${parts.make} ${parts.model}`.trim();
  const ours = carForMine(parts.make, parts.model);
  const look = !ours ? lookFor(parts.make, parts.model, parts.year) : undefined;
  const miles = answers.myCarMiles ?? garage?.miles;
  const sub = [miles ? `${miles.toLocaleString('en-US')} miles` : '', garage ? 'from My car' : ''].filter(Boolean).join(' · ');
  const h = width < 360 ? 74 : 92;
  const keep = (uri: string) => {
    if (key && !setCarPhoto([key], uri)) notify('That photo is too big', 'Try again a little farther away, or pick a smaller photo.');
    setSheet(false);
  };
  return (
    <View style={s.box}>
      <Text style={s.kicker}>YOU DRIVE NOW</Text>
      <Text style={s.name}>{name}</Text>
      {sub ? <Text style={s.sub}>{sub}</Text> : null}
      {own ? (
        <View style={s.own} accessible accessibilityLabel={`${name}, your photo`}>
          <ExpoImage source={{ uri: own }} style={{ width: '100%', height: '100%' }} contentFit="cover" />
          <View style={s.ownTag}><Text style={s.ownTagT}>Your photo</Text></View>
        </View>
      ) : (
        <LinearGradient colors={[C.card, C.hero, C.card]} locations={[0, 0.8, 1]} style={s.floor}>
          {ours ? <CarCutout id={ours.id} year={parts.year} paint={garage?.color} height={h} label={name} style={{ width: '62%' }} />
            : look ? <ExpoImage source={look.src} style={{ width: '62%', height: h }} contentFit="contain" accessibilityLabel={name} />
            : <Outline color={C.muted} />}
        </LinearGradient>
      )}
      {!own && look && look.year !== parts.year ? <Text style={s.note}>{`Photo: a ${look.year}, same look outside as your ${parts.year}`}</Text> : null}
      {!own && !ours && !look ? <Text style={s.note}>Photo coming for your car</Text> : null}
      {!own && look ? <Text style={s.credit}>{look.credit}</Text> : null}
      {canPhoto && key && (
        <Pressable onPress={() => { tap(); setSheet(true); }} accessibilityRole="button" style={s.photoBtn}>
          <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.onAccent} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
            <Path d="M3 8h4l2-3h6l2 3h4v11H3z" /><Circle cx="12" cy="13" r="3.5" />
          </Svg>
          <Text style={s.photoBtnT}>{own ? 'Change photo' : 'Use a photo of my car'}</Text>
        </Pressable>
      )}
      {own && key ? (
        <Pressable onPress={() => { tap(); setCarPhoto([key], null); }} accessibilityRole="button" hitSlop={8} style={{ marginTop: 6, minHeight: 32, justifyContent: 'center' }}>
          <Text style={[s.note, { color: C.red, fontFamily: F.bodyBold }]}>Remove my photo</Text>
        </Pressable>
      ) : null}
      {sheet && <PhotoSheet onClose={() => setSheet(false)} onPhoto={keep} />}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  box: { alignItems: 'center', paddingTop: 14 },
  kicker: { fontFamily: F.bodyBold, fontSize: 10.5, letterSpacing: 1.6, color: C.yellow },
  name: { fontFamily: F.head, fontSize: 21, color: C.ink, marginTop: 2, textAlign: 'center' },
  sub: { fontFamily: F.bodySemi, fontSize: 12.5, color: C.muted, marginTop: 1 },
  floor: { alignSelf: 'stretch', height: 128, marginTop: 4, alignItems: 'center', justifyContent: 'center' },
  own: { alignSelf: 'stretch', height: 170, marginTop: 10, borderRadius: 20, overflow: 'hidden', borderWidth: 3, borderColor: '#C9A45E' },
  ownTag: { position: 'absolute', left: 10, top: 10, backgroundColor: '#C9A45E', borderRadius: 10, paddingHorizontal: 9, paddingVertical: 3 },
  ownTagT: { fontFamily: F.bodyBold, fontSize: 11, color: '#FFFFFF' },
  note: { fontFamily: F.bodySemi, fontSize: 11.5, color: C.muted, marginTop: 2, textAlign: 'center' },
  credit: { fontFamily: F.body, fontSize: 9.5, color: C.muted, marginTop: 1, textAlign: 'center' },
  photoBtn: { flexDirection: 'row', alignItems: 'center', gap: 7, marginTop: 8, borderWidth: 1.5, borderStyle: 'dashed', borderColor: '#C9A45E',
    backgroundColor: C.fill, borderRadius: 14, paddingHorizontal: 13, paddingVertical: 8, minHeight: 44 },
  photoBtnT: { fontFamily: F.bodyBold, fontSize: 13, color: C.onAccent },
}));
