// App driver day (picture 191 Y): a simple trip log for app drivers. Miles you add stay on this phone;
// the write-off is an estimate at the IRS standard mileage rate, not tax advice.
import { router } from 'expo-router';
import { useEffect, useState } from 'react';
import { ScrollView, StyleSheet, TextInput, View } from 'react-native';

import { AccountTop, BigBtn, Card, Sec } from '@/components/account-ui';
import { Pressable, Text } from '@/components/t';
import { Body, tap } from '@/components/ui';
import { tr } from '@/i18n';
import { C, F, PAD, themed } from '@/theme';
import { readSnap } from '@/widgets/data';
import { IRS_RATE, milesThisMonth, milesToday, readTrips, writeOff, writeTrips, type Trip } from '@/widgets/more';
import { redrawWidgets } from '@/widgets/sync';

const APPS = ['Uber', 'Lyft', 'DoorDash', 'Instacart', 'Other'];

export default function Trips() {
  const [trips, setTrips] = useState<Trip[]>([]);
  const [miles, setMiles] = useState('');
  const [app, setApp] = useState('Uber');
  const [now] = useState(() => Date.now());
  useEffect(() => { readTrips().then(setTrips); }, []);
  const save = async (next: Trip[]) => { setTrips(next); await writeTrips(next); readSnap().then(redrawWidgets).catch(() => {}); };
  const add = () => {
    const m = Number(miles.replace(',', '.'));
    if (!(m > 0 && m < 1000)) return;
    tap(); setMiles('');
    save([...trips, { at: Date.now(), miles: Math.round(m * 10) / 10, app }]);
  };
  const today = milesToday(trips, now), month = milesThisMonth(trips, now);
  const todays = trips.filter((t) => new Date(t.at).toDateString() === new Date(now).toDateString()).reverse();
  const back = () => (router.canGoBack() ? router.back() : router.navigate('/garage'));
  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="Trip log" back={back} />
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 40 }} keyboardShouldPersistTaps="handled">
        <View style={s.tiles}>
          <View style={s.tile}><Text style={s.big}>{today.toLocaleString('en-US')} mi</Text><Body style={{ color: C.muted }}>today</Body></View>
          <View style={s.tile}><Text style={s.big}>${writeOff(today).toLocaleString('en-US')}</Text><Body style={{ color: C.muted }}>write-off today, est.</Body></View>
        </View>
        <Body style={{ color: C.muted, marginTop: 8 }}>{tr('This month: {m} mi · about ${d} write-off (estimate)').replace('{m}', month.toLocaleString('en-US')).replace('{d}', writeOff(month).toLocaleString('en-US'))}</Body>

        <Sec>Add a trip</Sec>
        <Card style={{ padding: 14, gap: 10 }}>
          <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>
            {APPS.map((a) => (
              <Pressable key={a} onPress={() => { tap(); setApp(a); }} accessibilityRole="radio" accessibilityState={{ selected: app === a }} style={[s.chip, app === a && s.chipOn]}>
                <Text style={[s.chipT, app === a && { color: C.onAccent }]}>{tr(a)}</Text>
              </Pressable>
            ))}
          </View>
          <TextInput value={miles} onChangeText={setMiles} keyboardType="decimal-pad" placeholder={tr('Miles driven')} placeholderTextColor={C.muted} style={s.input} accessibilityLabel={tr('Miles driven')} onSubmitEditing={add} />
          <BigBtn label="Add trip" onPress={add} />
        </Card>

        {todays.length ? <Sec>Today</Sec> : null}
        {todays.map((t) => (
          <View key={t.at} style={s.trip}>
            <Body bold style={{ flex: 1 }}>{`${tr(t.app ?? 'Trip')} · ${t.miles} mi`}</Body>
            <Pressable onPress={() => { tap(); save(trips.filter((x) => x.at !== t.at)); }} accessibilityRole="button" accessibilityLabel={tr('Delete this trip')}>
              <Text style={s.del}>{tr('Delete')}</Text>
            </Pressable>
          </View>
        ))}
        <Body style={{ color: C.muted, fontSize: 12.5, marginTop: 14 }}>
          {tr('Estimate at the {y} IRS standard mileage rate ({c}¢ a mile). Not tax advice: check this year’s rate on irs.gov and keep your own records.').replace('{y}', String(IRS_RATE.year)).replace('{c}', String(Math.round(IRS_RATE.perMile * 100)))}
        </Body>
      </ScrollView>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  tiles: { flexDirection: 'row', gap: 10, marginTop: 14 },
  tile: { flex: 1, backgroundColor: C.card, borderRadius: 18, padding: 14 },
  big: { fontFamily: F.bodyBold, fontSize: 26, color: C.ink },
  input: { borderWidth: 1, borderColor: C.line, borderRadius: 14, paddingHorizontal: 12, paddingVertical: 10, fontFamily: F.body, fontSize: 16, color: C.ink, backgroundColor: C.bg },
  chip: { borderWidth: 1, borderColor: C.line, borderRadius: 999, paddingHorizontal: 14, paddingVertical: 8 },
  chipOn: { backgroundColor: C.fill, borderColor: C.fill },
  chipT: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  trip: { flexDirection: 'row', alignItems: 'center', backgroundColor: C.card, borderRadius: 14, padding: 12, marginTop: 8 },
  del: { fontFamily: F.bodyBold, fontSize: 14, color: '#B3412F' },
}));
