// For you: swipe cars like a dating app.
// Swipe right (or tap the heart) if you like it, then Save it or see details.
// Swipe left (or tap X) to skip. The buttons do the same, for people who don't swipe.
import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { Animated, Modal, PanResponder, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Circle, Path } from 'react-native-svg';

import { CarCutout, CarPhoto } from '@/components/car-photo';
import { HeartIcon } from '@/components/icons';
import { Body, Btn, H, Label, Logo, tap } from '@/components/ui';
import { CARS, type Car, carName, yearsOf } from '@/data/cars';
import { money, priceFor, priceLine } from '@/data/prices';
import { useFacts } from '@/data/use-facts';
import { paymentFor, useAnswers, type Answers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { useSaveToggle } from '@/state/save-gate';
import { calm, C, F, isDarkLook, look, PAD, skyLook, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';

const SWIPE = 100;

function chips(c: Car) {
  return [`${c.seats} seats`, c.body, c.green === 'hybrid' ? 'Hybrid choice' : c.green === 'ev' ? 'Electric' : null].filter(Boolean) as string[];
}

// Clean look (picture 98 A): the car floats on a soft blue band, then soft tags with the payment estimate.
const soft = () => calm && !skyLook;
const night = () => isDarkLook(look);

function SoftFace({ car, answers, n, total }: { car: Car; answers: Answers; n: number; total: number }) {
  const year = yearsOf(car)[0];
  const p = priceFor(car, year);
  const { facts } = useFacts(car.id, year);
  const tags = [
    p ? `≈ ${money(paymentFor(answers, p.amount, p.isNew))}/mo est.` : null,
    facts?.mpg ? `${facts.mpg.combined} MPG` : null,
    facts?.stars ? `${facts.stars}★ safety` : null,
    `Fits ${car.seats}`,
  ].filter(Boolean) as string[];
  return (
    <>
      <View style={s.band}>
        <CarCutout id={car.id} year={year} height={200} label={carName(car, year)} style={{ width: '100%' }} />
        <View style={[s.tag, s.softTag]}><Text style={s.softTagT}>{car.tag}</Text></View>
        <View style={s.count}><Text style={s.countT}>{`${n} of ${total}`}</Text></View>
      </View>
      <View style={{ padding: 16, gap: 8 }}>
        <View style={{ flexDirection: 'row', alignItems: 'baseline', justifyContent: 'space-between', gap: 8 }}>
          <H size={23} style={{ flex: 1 }}>{carName(car, year)}</H>
          {p && <Text style={s.price}>{money(p.amount)}</Text>}
        </View>
        <Body style={{ color: C.muted, marginTop: -4 }}>{[p?.isNew ? 'New' : 'Used', car.body, car.green === 'hybrid' ? 'Hybrid choice' : car.green === 'ev' ? 'Electric' : null].filter(Boolean).join(' · ')}</Body>
        <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6 }}>
          {tags.map((x) => <View key={x} style={s.pill}><Text style={s.pillT}>{x}</Text></View>)}
        </View>
        <Body numberOfLines={3}>{car.why}</Body>
      </View>
    </>
  );
}

export default function ForYou() {
  const { answers } = useAnswers();
  const { isSaved } = useSaved();
  const saveToggle = useSaveToggle();
  const { width } = useWindowDimensions();
  // Cars that fit the user's goal come first, then best-sellers, then the rest.
  const deck = useMemo(() => {
    const goal = answers.goal;
    const score = (c: Car) => (goal && c.goals.includes(goal as Car['goals'][number]) ? 2 : 0) + (c.popular ? 1 : 0);
    return [...CARS].sort((a, b) => score(b) - score(a));
  }, [answers.goal]);
  const [idx, setIdx] = useState(0);
  const [liked, setLiked] = useState<Car | null>(null);
  const [pan] = useState(() => new Animated.ValueXY());

  const car = deck[idx];
  const next = deck[idx + 1];

  const fly = (dir: 1 | -1) => {
    const c = deck[idx];
    if (!c) return;
    tap();
    Animated.timing(pan, { toValue: { x: dir * width * 1.3, y: 0 }, duration: 220, useNativeDriver: true }).start(() => {
      pan.setValue({ x: 0, y: 0 });
      setIdx((i) => i + 1);
      if (dir > 0) setLiked(c);
    });
  };
  const responder = useMemo(() => PanResponder.create({
    onStartShouldSetPanResponder: () => true,
    onMoveShouldSetPanResponder: (_, g) => Math.abs(g.dx) > 8 && Math.abs(g.dx) > Math.abs(g.dy),
    onPanResponderMove: (_, g) => pan.setValue({ x: g.dx, y: 0 }),
    onPanResponderRelease: (_, g) => {
      if (g.dx > SWIPE) fly(1);
      else if (g.dx < -SWIPE) fly(-1);
      else Animated.spring(pan, { toValue: { x: 0, y: 0 }, useNativeDriver: true }).start();
    },
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [pan, idx, deck, width]);

  const rotate = pan.x.interpolate({ inputRange: [-200, 0, 200], outputRange: ['-12deg', '0deg', '12deg'] });
  const likeOp = pan.x.interpolate({ inputRange: [0, SWIPE], outputRange: [0, 1], extrapolate: 'clamp' });
  const skipOp = pan.x.interpolate({ inputRange: [-SWIPE, 0], outputRange: [1, 0], extrapolate: 'clamp' });

  const likedYear = liked ? yearsOf(liked)[0] : 0;

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm && <SkyHeader title="For you" sub="Swipe right if you like it. Left to skip." />}
      <View style={calm ? sheet.page : { flex: 1 }}>
      {!calm && <>
      <View style={s.top}>
        <Logo />
        <Label style={{ color: C.muted }}>{car ? `${idx + 1} of ${deck.length}` : 'Done'}</Label>
      </View>
      <View style={{ paddingHorizontal: PAD, marginTop: 8 }}>
        <H size={32}>For you</H>
        <Body style={{ color: C.muted }}>Swipe right if you like it. Left to skip.</Body>
      </View>
      </>}

      <View style={s.deck}>
        {next && (
          <View style={[s.card, s.under, soft() && s.softCard]}>
            {soft() ? <View style={[s.band, { opacity: 0.6 }]}><CarCutout id={next.id} height={200} label="" style={{ width: '100%' }} /></View>
              : <CarPhoto id={next.id} label="" style={{ flex: 1, opacity: 0.6 }} />}
          </View>
        )}
        {car ? (
          <Animated.View {...responder.panHandlers} pointerEvents="box-only" style={[s.card, soft() && s.softCard, { transform: [{ translateX: pan.x }, { rotate }] }]}
            accessible accessibilityLabel={`${carName(car, yearsOf(car)[0])}. Swipe right to like, left to skip, or use the buttons below.`}>
            {soft() ? <SoftFace car={car} answers={answers} n={idx + 1} total={deck.length} /> : <>
            <View style={{ flex: 1, minHeight: 180 }}>
              <CarPhoto id={car.id} label={carName(car, yearsOf(car)[0])} style={{ flex: 1 }} />
              <View style={s.tag}><Label style={{ fontSize: 12, color: C.onAccent }}>{car.tag}</Label></View>
              <Animated.View style={[s.stamp, { borderColor: C.green, opacity: likeOp, transform: [{ rotate: '12deg' }] }]}><Label style={{ color: C.green, fontSize: 24 }}>Like</Label></Animated.View>
              <Animated.View style={[s.stamp, { borderColor: C.red, opacity: skipOp, transform: [{ rotate: '-12deg' }] }]}><Label style={{ color: C.red, fontSize: 24 }}>Skip</Label></Animated.View>
            </View>
            <View style={{ padding: 14, gap: 8 }}>
              <H size={26}>{carName(car, yearsOf(car)[0])}</H>
              <Body bold>{priceLine(priceFor(car, yearsOf(car)[0]))}</Body>
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6 }}>
                {chips(car).map((x) => <View key={x} style={s.chip}><Body bold style={{ fontSize: 13 }}>{x}</Body></View>)}
              </View>
              <Body><Body bold>Why for you: </Body>{car.why}</Body>
            </View>
            </>}
            {soft() && <>
              <Animated.View style={[s.stamp, s.softStamp, { borderColor: C.green, opacity: likeOp, transform: [{ rotate: '12deg' }] }]}><Label style={{ color: C.green, fontSize: 22 }}>Like</Label></Animated.View>
              <Animated.View style={[s.stamp, s.softStamp, { borderColor: C.red, opacity: skipOp, transform: [{ rotate: '-12deg' }] }]}><Label style={{ color: C.red, fontSize: 22 }}>Skip</Label></Animated.View>
            </>}
          </Animated.View>
        ) : (
          <View style={[s.card, s.done, soft() && s.softCard]}>
            <H size={26}>That’s all for now</H>
            <Body style={{ textAlign: 'center' }}>The cars you liked and saved are in your Garage.</Body>
            <Btn small kind="yellow" label="Start again" onPress={() => setIdx(0)} />
          </View>
        )}
      </View>

      {car && (
        <View style={[s.buttons, soft() && { paddingBottom: 30 }]}>
          <Pressable onPress={() => fly(-1)} accessibilityRole="button" accessibilityLabel="Skip this car" style={[s.round, { borderColor: C.red }, soft() && s.softSkip]}>
            <Svg width={26} height={26} viewBox="0 0 24 24" fill="none" stroke={soft() ? (night() ? '#F2A39A' : '#B3412F') : C.red} strokeWidth={3} strokeLinecap="round"><Path d="M6 6l12 12M18 6L6 18" /></Svg>
          </Pressable>
          <Pressable onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: car.id, year: String(yearsOf(car)[0]) } }); }}
            accessibilityRole="button" accessibilityLabel="More about this car" style={[s.round, s.small, soft() && s.softInfo]}>
            <Svg width={20} height={20} viewBox="0 0 24 24" fill="none" stroke={C.ink} strokeWidth={2.4} strokeLinecap="round"><Circle cx="12" cy="12" r="9" /><Path d="M12 11v6M12 7.5v.5" /></Svg>
          </Pressable>
          <Pressable onPress={() => fly(1)} accessibilityRole="button" accessibilityLabel="Like this car" style={[s.round, { backgroundColor: C.green, borderColor: C.green }, soft() && s.softLike]}>
            <HeartIcon size={28} color={soft() ? C.yellow : '#FFFFFF'} />
          </Pressable>
        </View>
      )}

      <Modal transparent animationType="slide" visible={!!liked} onRequestClose={() => setLiked(null)}>
        <Pressable style={s.sheetBack} onPress={() => setLiked(null)} accessibilityLabel="Close" />
        {liked && (
          <View style={s.sheet}>
            <View style={{ flexDirection: 'row', gap: 12, alignItems: 'center' }}>
              <CarPhoto id={liked.id} label="" style={{ width: 96, height: 64 }} />
              <View style={{ flex: 1 }}>
                <Label style={{ color: C.green }}>You like it</Label>
                <H size={22}>{carName(liked, likedYear)}</H>
              </View>
            </View>
            <Btn kind="yellow" label={isSaved(liked.id, likedYear) ? 'Saved in my Garage' : 'Save to my Garage'} icon={<HeartIcon size={20} color={C.onAccent} />}
              onPress={() => { if (!isSaved(liked.id, likedYear)) saveToggle(liked.id, likedYear); setLiked(null); }} />
            <Btn kind="outline" label="See details and prices" onPress={() => { const c = liked; setLiked(null); router.push({ pathname: '/car/[id]', params: { id: c.id, year: String(likedYear) } }); }} />
            <Pressable onPress={() => setLiked(null)} accessibilityRole="button" style={{ alignItems: 'center', paddingVertical: 10 }}>
              <Body bold style={{ textDecorationLine: 'underline' }}>Keep swiping</Body>
            </Pressable>
          </View>
        )}
      </Modal>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10 },
  deck: { flex: 1, marginHorizontal: PAD, marginTop: 14, marginBottom: 8 },
  card: { position: 'absolute', left: 0, right: 0, top: 0, bottom: 0, backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 12, overflow: 'hidden' },
  under: { transform: [{ scale: 0.95 }, { translateY: 12 }] },
  done: { alignItems: 'center', justifyContent: 'center', gap: 12, padding: 20, borderStyle: 'dashed' },
  tag: { position: 'absolute', left: 12, top: 12, backgroundColor: C.fill, paddingHorizontal: 8, paddingVertical: 3 },
  stamp: { position: 'absolute', right: 14, top: 14, borderWidth: 4, paddingHorizontal: 10, backgroundColor: 'rgba(255,255,255,0.9)' },
  chip: { backgroundColor: C.grey, paddingHorizontal: 8, paddingVertical: 4 },
  buttons: { flexDirection: 'row', justifyContent: 'center', alignItems: 'center', gap: 22, paddingBottom: 14 },
  round: { width: 64, height: 64, borderRadius: 32, borderWidth: 3, alignItems: 'center', justifyContent: 'center', backgroundColor: C.card },
  small: { width: 50, height: 50, borderRadius: 25, borderWidth: 1.5, borderColor: C.ink },
  softCard: { borderRadius: 26, borderColor: C.line, shadowColor: '#0B2A5B', shadowOpacity: 0.08, shadowRadius: 18, shadowOffset: { width: 0, height: 6 }, elevation: 3 },
  band: { backgroundColor: C.hero, paddingTop: 34, paddingHorizontal: 16, paddingBottom: 10 },
  softTag: { borderRadius: 999, paddingHorizontal: 10, paddingVertical: 4, backgroundColor: C.card },
  softTagT: { fontFamily: F.bodyBold, fontSize: 12, color: C.ink },
  count: { position: 'absolute', right: 12, top: 12, borderRadius: 999, paddingHorizontal: 10, paddingVertical: 4, backgroundColor: night() ? 'rgba(0,0,0,0.3)' : 'rgba(255,255,255,0.7)' },
  countT: { fontFamily: F.bodyBold, fontSize: 12, color: C.muted },
  price: { fontFamily: F.bodyBold, fontSize: 20, color: C.yellow },
  pill: { backgroundColor: C.fill, borderRadius: 999, paddingHorizontal: 10, paddingVertical: 5 },
  pillT: { fontFamily: F.bodyBold, fontSize: 13, color: C.onAccent },
  softStamp: { borderRadius: 12, borderWidth: 3, top: 50 },
  softSkip: { backgroundColor: night() ? '#3A2328' : '#FBE6E3', borderWidth: 0 },
  softInfo: { backgroundColor: C.card, borderColor: C.line, borderWidth: 1, shadowColor: '#000', shadowOpacity: 0.08, shadowRadius: 8, shadowOffset: { width: 0, height: 3 }, elevation: 2 },
  softLike: { backgroundColor: C.fill, borderColor: C.fill, borderWidth: 0 },
  sheetBack: { flex: 1, backgroundColor: 'rgba(0,0,0,0.55)' },
  sheet: { backgroundColor: C.card, padding: 20, paddingBottom: 34, gap: 12 },
}));
