// Problems owners report (picture 152, Oct 26, 2026, Loudjier: his 2018 Trax had transmission trouble right after he bought
// it; 'i want to know if it was fixed or is it going to be a problem. think about the ford Pinto'). Owner complaints from
// NHTSA (free, no key), grouped into plain part names, biggest first, with the recalls on the same part. Owners wrote these
// and nobody checked them, so we never say a car will break: we show where to look and how to check THIS car.
import { GOV_NAMES, type Recall } from '@/data/gov';
import { onPullClear } from '@/lib/refresh';

const NHTSA = 'https://api.nhtsa.gov';
const MAKE_ALIAS: Record<string, string> = { chevy: 'CHEVROLET', vw: 'VOLKSWAGEN', mercedes: 'MERCEDES-BENZ', benz: 'MERCEDES-BENZ', 'land rover': 'LAND ROVER', landrover: 'LAND ROVER' };

export type Part = 'transmission' | 'engine' | 'electrical' | 'suspension' | 'steering' | 'brakes' | 'airbags' | 'fuel' | 'hybrid'
  | 'body' | 'wheels' | 'seats' | 'lights' | 'visibility' | 'locks' | 'safetytech' | 'other';
// NHTSA's part groups → our plain names. First match wins (the group is the text before the first ':').
const GROUPS: [RegExp, Part][] = [
  [/^POWER TRAIN/, 'transmission'], [/^ENGINE/, 'engine'], [/^ELECTRICAL/, 'electrical'], [/^SUSPENSION/, 'suspension'],
  [/^STEERING/, 'steering'], [/BRAKE/, 'brakes'], [/^AIR ?BAGS/, 'airbags'], [/^FUEL/, 'fuel'], [/^HYBRID|^ELECTRIC(?:AL)? PROPULSION/, 'hybrid'],
  [/^STRUCTURE/, 'body'], [/^WHEELS|^TIRES/, 'wheels'], [/^SEAT/, 'seats'], [/LIGHTING/, 'lights'], [/^VISIBILITY/, 'visibility'],
  [/^LATCHES|LOCKS/, 'locks'], [/COLLISION|LANE|BACK ?OVER|STABILITY|VEHICLE SPEED/, 'safetytech'],
];
export const PART_NAME: Record<Part, string> = {
  transmission: 'Transmission & drive', engine: 'Engine', electrical: 'Electrical', suspension: 'Suspension', steering: 'Steering',
  brakes: 'Brakes', airbags: 'Air bags', fuel: 'Fuel system', hybrid: 'Hybrid or electric system', body: 'Body & frame', wheels: 'Wheels & tires',
  seats: 'Seats & seat belts', lights: 'Lights', visibility: 'Wipers & windows', locks: 'Doors & locks', safetytech: 'Safety tech & cruise', other: 'Other',
};
export function partOf(component: string): Part {
  const g = component.toUpperCase().split(':')[0].trim();
  return GROUPS.find(([re]) => re.test(g))?.[1] ?? 'other';
}

export type PartReport = { part: Part; count: number; crashes: number; fires: number; recalls: Recall[] };
export type Problems = { total: number; crashes: number; fires: number; deaths: number; parts: PartReport[] };
type Complaint = { components?: string; crash?: boolean; fire?: boolean; numberOfDeaths?: number };

/** Plain math (tested): one complaint counts once per part even when it names that part twice. */
export function summarize(complaints: Complaint[], recalls: Recall[] = []): Problems {
  const by = new Map<Part, PartReport>();
  const get = (p: Part) => { if (!by.has(p)) by.set(p, { part: p, count: 0, crashes: 0, fires: 0, recalls: [] }); return by.get(p)!; };
  let crashes = 0, fires = 0, deaths = 0;
  for (const c of complaints) {
    if (c.crash) crashes++;
    if (c.fire) fires++;
    deaths += Number(c.numberOfDeaths) || 0;
    const parts = new Set((c.components ?? '').split(',').map((x) => x.trim()).filter(Boolean).map(partOf));
    if (!parts.size) parts.add('other');
    for (const p of parts) { const r = get(p); r.count++; if (c.crash) r.crashes++; if (c.fire) r.fires++; }
  }
  for (const r of recalls) get(partOf(r.part)).recalls.push(r);
  // Biggest first; "Other" last because it tells people little.
  const parts = [...by.values()].sort((a, b) => (a.part === 'other' ? 1 : 0) - (b.part === 'other' ? 1 : 0) || b.count - a.count || b.recalls.length - a.recalls.length);
  return { total: complaints.length, crashes, fires, deaths, parts };
}

// The names NHTSA uses: our 35 cars have their list; any other car uses its brand and model in capitals.
export function govNames(c: { carId?: string; make: string; model: string }): { make: string; models: string[] } {
  const n = c.carId ? GOV_NAMES[c.carId] : undefined;
  if (n) return { make: n.make, models: n.recall };
  return { make: MAKE_ALIAS[c.make.trim().toLowerCase()] ?? c.make.trim().toUpperCase(), models: [c.model.trim().toUpperCase()] };
}

const cache = new Map<string, Promise<Complaint[] | null>>();
onPullClear(() => cache.clear());
/** Owner complaints for a model year (null = couldn't reach NHTSA). */
export function complaintsFor(make: string, models: string[], year: number): Promise<Complaint[] | null> {
  const key = `${make}|${models.join(',')}|${year}`;
  if (!cache.has(key)) {
    cache.set(key, Promise.all(models.map(async (m) => {
      const r = await fetch(`${NHTSA}/complaints/complaintsByVehicle?make=${encodeURIComponent(make)}&model=${encodeURIComponent(m)}&modelYear=${year}`);
      if (!r.ok) throw new Error(String(r.status));
      const j = await r.json();
      return (Array.isArray(j?.results) ? j.results : []) as (Complaint & { odiNumber?: number })[];
    })).then((lists) => {
      const seen = new Set<number>();
      return lists.flat().filter((c) => { const id = (c as { odiNumber?: number }).odiNumber; if (id == null) return true; if (seen.has(id)) return false; seen.add(id); return true; });
    }).catch(() => { cache.delete(key); return null; }));
  }
  return cache.get(key)!;
}

// The "Ford Pinto" case: a recall whose risk is a fire or a crash goes red at the top of the page.
export type Danger = 'fire' | 'crash';
export function dangerOf(r: Recall): Danger | null {
  const t = `${r.risk} ${r.summary}`.toLowerCase();
  if (/\bfire\b|burn/.test(t)) return 'fire';
  if (/crash|loss of (vehicle )?control|injury/.test(t)) return 'crash';
  return null;
}
export function worstDanger(recalls: Recall[] | null | undefined): { kind: Danger; recalls: Recall[] } | null {
  const list = recalls ?? [];
  const fire = list.filter((r) => dangerOf(r) === 'fire');
  if (fire.length) return { kind: 'fire', recalls: fire };
  const crash = list.filter((r) => dangerOf(r) === 'crash');
  return crash.length ? { kind: 'crash', recalls: crash } : null;
}

