// Picture 268 steps 1 + 2 (Nov 18, 2026, Loudjier: 'Build 1 and 2'). My Garage, big photo you swipe:
// 1) your own photos of this car first (up to 6, kept on this phone), then
// 2) free, credited photos of the SAME LOOK only: same make + model + the years that share your car's body
//    (data/gallery.ts). A 2018 Trax shows 2017–2022 Trax, never the 2024+ redesign.
// Tap a photo to see it full screen. "+ Add photos" adds more of your own.
import { Image } from 'expo-image';
import { useState } from 'react';
import { Modal, ScrollView, StyleSheet, useWindowDimensions, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { CarCutout, lookKey, PhotoCredit, ShotCredit } from '@/components/car-photo';
import { notify } from '@/components/notify';
import { PhotoSheet } from '@/components/scan-photo';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { galleryFor, shotUrl, type Shot } from '@/data/gallery';
import { canPhoto } from '@/lib/photo';
import { addCarPhoto, MAX_PER_CAR, removeCarPhoto } from '@/state/car-photos';
import { C, F, themed } from '@/theme';

type Slide = { kind: 'own'; uri: string; n: number } | { kind: 'cut'; key: string } | { kind: 'shot'; shot: Shot };

/** The years that look like this car, for the words ("2017–2022"). Null when we don't know. */
export function lookYears(id: string | undefined, year: number) {
  if (!id) return null;
  const b = galleryFor(id, year, lookKey(id, year)).badge; // "2017–2022 look" or "2024 and newer look"
  if (!b) return null;
  const m = b.match(/^(\d{4})–(\d{4}) look$/);
  if (m) return `${m[1]}–${m[2]}`;
  const n = b.match(/^(\d{4}) and newer look$/);
  return n ? `${n[1]} and newer` : null;
}

export function GaragePhotos({ photoKey, own, carId, year, model, label, height = 290 }: {
  photoKey: string; own: string[]; carId?: string; year: number; model: string; label: string; height?: number;
}) {
  const [w, setW] = useState(0);
  const [i, setI] = useState(0);
  const [bad, setBad] = useState<string[]>([]);
  const [adding, setAdding] = useState(false);
  const [full, setFull] = useState(false);
  const win = useWindowDimensions();
  const insets = useSafeAreaInsets();

  const same = carId ? galleryFor(carId, year, lookKey(carId, year)).slides : [];
  const slides: Slide[] = [
    ...own.map((uri, n) => ({ kind: 'own' as const, uri, n })),
    ...same.filter((sl) => sl.kind === 'cut' || !bad.includes(sl.shot.file)),
  ];
  const at = Math.min(i, slides.length - 1);
  const cur = slides[at];
  const years = lookYears(carId, year);
  const lastOwn = cur?.kind === 'own' && cur.n === own.length - 1 && slides.length > own.length;

  const keep = (uri: string) => {
    setAdding(false);
    const r = addCarPhoto(photoKey, uri);
    if (r === 'big') notify('That photo is too big', 'Try again a little farther away, or pick a smaller photo.');
    if (r === 'full') notify(`You have ${MAX_PER_CAR} photos`, 'Remove one to add another.');
  };

  const draw = (sl: Slide, fit: 'cover' | 'contain', h: number) =>
    sl.kind === 'own' ? <Image source={{ uri: sl.uri }} style={{ width: '100%', height: '100%' }} contentFit={fit} />
      : sl.kind === 'cut' ? <View style={{ flex: 1, justifyContent: 'flex-end', alignItems: 'center', paddingBottom: 10 }}><CarCutout id={carId!} year={year} label={label} height={h - 40} style={{ width: '92%' }} /></View>
      : <Image source={{ uri: shotUrl(sl.shot) }} style={{ width: '100%', height: '100%' }} contentFit={fit} transition={150}
          onError={() => setBad((b) => (b.includes(sl.shot.file) ? b : [...b, sl.shot.file]))} />;

  return (
    <View>
      <View onLayout={(e) => setW(e.nativeEvent.layout.width)} style={[s.frame, { height }]}>
        {w > 0 && (
          <ScrollView horizontal pagingEnabled showsHorizontalScrollIndicator={false} scrollEventThrottle={32}
            onScroll={(e) => setI(Math.round(e.nativeEvent.contentOffset.x / Math.max(1, w)))}>
            {slides.map((sl, n) => (
              <Pressable key={sl.kind === 'own' ? `own${sl.n}` : sl.kind === 'cut' ? 'cut' : sl.shot.file} onPress={() => { tap(); setFull(true); }}
                accessibilityRole="imagebutton"
                accessibilityLabel={`${sl.kind === 'own' ? `${label}, your photo` : `${label}, same look as yours`}, ${n + 1} / ${slides.length}. Tap to see it bigger`}
                style={{ width: w, height, backgroundColor: sl.kind === 'cut' ? C.hero : '#000' }}>
                {draw(sl, 'cover', height)}
              </Pressable>
            ))}
          </ScrollView>
        )}
        {cur && (
          <View pointerEvents="none" style={[s.tag, cur.kind === 'own' ? s.tagMine : s.tagSame]}>
            <Text style={[s.tagT, { color: cur.kind === 'own' ? '#14110A' : '#10151B' }]}>
              {cur.kind === 'own' ? 'Your photo' : years ? `Same look · ${years}` : 'Same look as yours'}
            </Text>
          </View>
        )}
        {slides.length > 1 && <View pointerEvents="none" style={s.count}><Text style={s.countT}>{`${at + 1} / ${slides.length}`}</Text></View>}
        {canPhoto && own.length < MAX_PER_CAR && (
          <Pressable onPress={() => { tap(); setAdding(true); }} accessibilityRole="button" style={s.add} hitSlop={6}>
            <Text style={s.addT}>+ Add photos</Text>
          </Pressable>
        )}
        {slides.length > 1 && (
          <View pointerEvents="none" style={s.dots}>
            {slides.map((sl, n) => (
              <View key={n} style={[s.dot, sl.kind === 'own' && s.dotMine, n === at && s.dotOn, n === own.length && own.length > 0 && { marginLeft: 8 }]} />
            ))}
          </View>
        )}
      </View>

      {/* Under the photo: where your photos end, credits for the same-look photos, remove your photo. */}
      {lastOwn && (
        <Text style={s.endMine}>{`That's all your photos. Keep swiping for more ${years ? `${years} ` : ''}${model} with the same look as yours ›`}</Text>
      )}
      {cur?.kind === 'cut' && <PhotoCredit id={carId!} year={year} cut />}
      {cur?.kind === 'shot' && <ShotCredit shot={cur.shot} />}
      {cur?.kind === 'own' && (
        <Pressable onPress={() => { tap(); removeCarPhoto(photoKey, cur.n); setI((x) => Math.max(0, Math.min(x, slides.length - 2))); }}
          accessibilityRole="button" hitSlop={8} style={{ alignSelf: 'flex-start', minHeight: 32, justifyContent: 'center' }}>
          <Text style={s.remove}>Remove this photo</Text>
        </Pressable>
      )}

      {adding && <PhotoSheet onClose={() => setAdding(false)} onPhoto={keep} />}
      {full && cur && (
        <Modal visible transparent={false} animationType="fade" onRequestClose={() => setFull(false)}>
          <View style={{ flex: 1, backgroundColor: '#000', paddingTop: insets.top, paddingBottom: insets.bottom }}>
            <View style={{ flex: 1 }}>{draw(cur, 'contain', win.height * 0.7)}</View>
            <Pressable onPress={() => setFull(false)} accessibilityRole="button" accessibilityLabel="Close" style={[s.close, { top: insets.top + 12 }]}>
              <Text style={s.closeT}>✕</Text>
            </Pressable>
          </View>
        </Modal>
      )}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  frame: { borderRadius: 24, overflow: 'hidden', backgroundColor: '#000' },
  tag: { position: 'absolute', top: 10, left: 10, borderRadius: 999, paddingHorizontal: 10, paddingVertical: 4 },
  tagMine: { backgroundColor: '#CDB38B' },
  tagSame: { backgroundColor: 'rgba(255,255,255,0.92)' },
  tagT: { fontFamily: F.bodyBold, fontSize: 12 },
  count: { position: 'absolute', top: 10, right: 10, backgroundColor: 'rgba(0,0,0,0.6)', borderRadius: 999, paddingHorizontal: 10, paddingVertical: 4 },
  countT: { fontFamily: F.bodyBold, fontSize: 12, color: '#fff' },
  add: { position: 'absolute', right: 10, bottom: 26, backgroundColor: 'rgba(255,255,255,0.94)', borderRadius: 999, paddingHorizontal: 13, paddingVertical: 8, minHeight: 36, justifyContent: 'center' },
  addT: { fontFamily: F.bodyBold, fontSize: 13.5, color: '#10151B' },
  dots: { position: 'absolute', bottom: 9, left: 0, right: 0, flexDirection: 'row', justifyContent: 'center', gap: 5 },
  dot: { width: 7, height: 7, borderRadius: 4, backgroundColor: 'rgba(255,255,255,0.45)' },
  dotMine: { backgroundColor: 'rgba(205,179,139,0.75)' },
  dotOn: { width: 18, backgroundColor: '#fff' },
  endMine: { fontFamily: F.bodySemi, fontSize: 13, color: C.ink, marginTop: 8, lineHeight: 18 },
  remove: { fontFamily: F.bodyBold, fontSize: 12.5, color: C.red, marginTop: 4 },
  close: { position: 'absolute', right: 16, width: 44, height: 44, borderRadius: 22, backgroundColor: 'rgba(255,255,255,0.18)', alignItems: 'center', justifyContent: 'center' },
  closeT: { color: '#fff', fontSize: 20, fontFamily: F.bodyBold },
}));
