// Car pass (picture 190 Q): your VIN as a barcode a shop, parts store or DMV can scan, plus the details
// people ask for. Everything comes from My Garage on this phone.
import { router } from 'expo-router';
import { useState } from 'react';
import { ScrollView, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SvgXml } from 'react-native-svg';

import { AccountTop, BigBtn, Card } from '@/components/account-ui';
import { Text } from '@/components/t';
import { Body } from '@/components/ui';
import { estMiles } from '@/data/car-plan';
import { carName } from '@/data/my-cars';
import { tr } from '@/i18n';
import { useSaved } from '@/state/saved';
import { C, F, PAD, themed } from '@/theme';
import { code39Svg } from '@/widgets/more';

export default function CarPass() {
  const { myCar } = useSaved();
  const { width } = useWindowDimensions();
  const back = () => (router.canGoBack() ? router.back() : router.navigate('/garage'));
  const vin = myCar?.vin?.toUpperCase();
  const bars = vin ? code39Svg(vin, 90) : null;
  const [now] = useState(() => Date.now());
  const miles = myCar ? estMiles(myCar, now) : null;
  const row = (label: string, value?: string | null) => (
    <View style={s.row}><Body style={{ color: C.muted }}>{tr(label)}</Body><Body bold>{value || tr('Not added')}</Body></View>
  );
  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="Car pass" back={back} />
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 40, gap: 12 }}>
        {!myCar ? <Body style={{ marginTop: 16 }}>Add your car in My Garage first.</Body> : (
          <>
            <Text style={s.name}>{carName(myCar)}</Text>
            {bars ? (
              <View style={s.code}>
                <SvgXml xml={bars} width={width - 2 * (PAD - 6) - 24} height={90} />
                <Text style={s.vin} selectable>{vin}</Text>
              </View>
            ) : (
              <Card style={{ padding: 14, gap: 10 }}>
                <Body>Add your VIN to show it as a barcode the shop can scan. It’s on your insurance card, your registration, or the windshield on the driver’s side.</Body>
                <BigBtn kind="soft" label="Add it in My car" onPress={() => router.navigate('/my-car')} />
              </Card>
            )}
            <Card style={{ padding: 14 }}>
              {row('Tag due', myCar.regDue)}
              {row('Insurance', myCar.insurer)}
              {row('Miles', miles ? `~${miles.toLocaleString('en-US')}` : null)}
            </Card>
            <Body style={{ color: C.muted, fontSize: 12.5 }}>Turn your screen brightness up if the scanner has trouble reading it.</Body>
          </>
        )}
      </ScrollView>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  name: { fontFamily: F.bodyBold, fontSize: 22, color: C.ink, marginTop: 14 },
  code: { backgroundColor: '#FFFFFF', borderRadius: 18, padding: 12, alignItems: 'center', gap: 8 },
  vin: { fontFamily: F.bodyBold, fontSize: 20, letterSpacing: 2, color: '#0F1A2A' },
  row: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 8 },
}));
