// "Join Carvessa. It's free." sheet (picture 10, picked Oct 10, 2026). Opens from the top-right
// buttons, from Me, or when a guest tries something that needs an account (like writing a review).
import { router } from 'expo-router';
import { useState } from 'react';
import { ActivityIndicator, Modal, Platform, StyleSheet, View } from 'react-native';

import { notify } from '@/components/notify';
import { ConfirmCode } from '@/components/confirm-code';
import { ResetPassword } from '@/components/reset-password';
import { Body, Btn, H, tap } from '@/components/ui';
import { supabase } from '@/lib/supabase';
import { NEED_CODE, useAuth } from '@/state/auth';
import { C, F, themed } from '@/theme';
import { KeyboardSheet } from '@/components/keyboard-sheet';
import { Pressable, Text, TextInput } from '@/components/t';

export function SignInSheet({ why, startMode, onClose }: { why?: string; startMode: 'join' | 'login'; onClose: () => void }) {
  const { signUp, signIn, signInWithGoogle } = useAuth();
  const [mode, setMode] = useState<'join' | 'login' | 'reset' | 'code'>(startMode);
  const [codeFrom, setCodeFrom] = useState<'join' | 'login'>('join');
  const [useEmail, setUseEmail] = useState(startMode === 'login');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const join = mode === 'join';

  const submit = async () => {
    setError(null);
    if (join && !name.trim()) return setError('Type your first name. Others see it next to your reviews.');
    if (!/^\S+@\S+\.\S+$/.test(email.trim())) return setError('Type your email.');
    if (password.length < 8) return setError('Use a password with at least 8 characters.');
    setBusy(true);
    const err = join ? await signUp(name, email, password) : await signIn(email, password);
    setBusy(false);
    if (err === NEED_CODE) { setCodeFrom(join ? 'join' : 'login'); setMode('code'); return; }
    if (err) return setError(err);
    notify(join ? 'Welcome to Carvessa!' : 'Welcome back!', join ? `Your account is ready, ${name.trim()}.` : 'You’re logged in.');
    onClose();
  };

  const openLegal = (tab: 'terms' | 'privacy') => { tap(); onClose(); router.push({ pathname: '/legal', params: { tab } }); };
  const google = async () => {
    setError(null);
    setBusy(true);
    const err = await signInWithGoogle();
    setBusy(false);
    if (err) return setError(err);
    const { data } = await supabase.auth.getSession();
    if (data.session) { notify('Welcome!', 'You’re logged in with Google.'); onClose(); }
  };

  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <KeyboardSheet onClose={onClose} backStyle={s.back} sheetStyle={s.sheet}>
          <View style={s.grab} />
          {mode === 'reset' ? <ResetPassword startEmail={email} onDone={onClose} onBack={() => { setMode('login'); setError(null); }} />
          : mode === 'code' ? (
            <ConfirmCode email={email} fromLogin={codeFrom === 'login'} onBack={() => { setMode(codeFrom); setError(null); }}
              onDone={() => { notify('Welcome to Carvessa!', codeFrom === 'join' && name.trim() ? `Your account is ready, ${name.trim()}.` : 'Your account is ready.'); onClose(); }} />
          ) : (<>
          <H size={28}>{join ? 'Join Carvessa. It’s free.' : 'Welcome back'}</H>
          <Body style={{ color: C.muted, fontSize: 14 }}>
            {why ?? (join ? 'Save cars on every device, write reviews, and get recall alerts.' : 'Log in to see your saved cars and reviews.')}
          </Body>

          {!useEmail ? (
            <>
              <Btn kind="yellow" label="Continue with email" onPress={() => setUseEmail(true)} />
              {Platform.OS !== 'web' && (<>
                {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="outline" label="Continue with Google" onPress={google} />}
                <Btn kind="outline" label="Continue with Apple" onPress={() => notify('Coming soon', 'Apple sign-in comes when we launch in the App Store. Use email for now.')} />
              </>)}
              {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
            </>
          ) : (
            <>
              {join && <TextInput value={name} onChangeText={setName} placeholder="First name" placeholderTextColor={C.muted} style={s.input}
                autoComplete="given-name" textContentType="givenName" accessibilityLabel="First name" maxLength={40} />}
              <TextInput value={email} onChangeText={setEmail} placeholder="Email" placeholderTextColor={C.muted} style={s.input}
                autoCapitalize="none" autoComplete="email" keyboardType="email-address" textContentType="emailAddress" accessibilityLabel="Email" />
              <TextInput value={password} onChangeText={setPassword} placeholder={join ? 'Make a password (8+ characters)' : 'Password'} placeholderTextColor={C.muted}
                style={s.input} secureTextEntry autoComplete={join ? 'new-password' : 'current-password'} textContentType={join ? 'newPassword' : 'password'}
                accessibilityLabel="Password" onSubmitEditing={submit} returnKeyType="go" />
              {!join && (
                <Pressable onPress={() => { tap(); setMode('reset'); setError(null); }} accessibilityRole="button" hitSlop={8} style={{ alignSelf: 'flex-end' }}>
                  <Text style={s.legal}>Forgot password?</Text>
                </Pressable>
              )}
              {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
              {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="yellow" label={join ? 'Create my account' : 'Log in'} onPress={submit} />}
            </>
          )}

          <Pressable onPress={() => { tap(); setMode(join ? 'login' : 'join'); setUseEmail(true); setError(null); }} accessibilityRole="button" hitSlop={8} style={{ alignSelf: 'center' }}>
            <Body style={{ fontSize: 13.5, color: C.muted }}>
              {join ? 'Already a member? ' : 'New here? '}<Body bold style={{ fontSize: 13.5, color: C.yellow, textDecorationLine: 'underline' }}>{join ? 'Log in' : 'Join free'}</Body>
            </Body>
          </Pressable>
          <Body style={{ fontSize: 11.5, color: C.muted, textAlign: 'center' }}>
            By joining you agree to our <Text style={s.legal} onPress={() => openLegal('terms')} accessibilityRole="link">Terms</Text> and <Text style={s.legal} onPress={() => openLegal('privacy')} accessibilityRole="link">Privacy Policy</Text>. We never sell your info.
          </Body>
          </>)}
        </KeyboardSheet>
    </Modal>
  );
}

const s = themed(() => StyleSheet.create({
  back: { flex: 1, backgroundColor: 'rgba(0,0,0,0.6)' },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 22, borderTopRightRadius: 22, borderTopWidth: 1, borderColor: C.line, padding: 20, paddingBottom: 30, gap: 10 },
  grab: { width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, alignSelf: 'center', marginBottom: 4 },
  input: { height: 52, borderRadius: 12, borderWidth: 1, borderColor: C.line, backgroundColor: C.bg, paddingHorizontal: 14, fontFamily: F.body, fontSize: 16, color: C.ink },
  error: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.red },
  legal: { fontFamily: F.bodyBold, color: C.yellow, textDecorationLine: 'underline' },
}));
