// VIN scanning needs the camera built into the phone app. Test apps made before Oct 14, 2026
// don't have it, and the web test site can't scan, so the scan buttons only show when it works.
import { requireOptionalNativeModule } from 'expo';
import { Platform } from 'react-native';

export const canScan = Platform.OS !== 'web' && !!requireOptionalNativeModule('ExpoCamera');

// "Read the letters" (picture 150 · 2, Oct 26, 2026): the phone's own free text reader (Google ML Kit on Android,
// Apple Vision on iPhone) reads the printed VIN, like apps read credit card numbers. Needs the app build of
// Oct 26, 2026 or later; older apps and the web hide the button.
export const canReadText = Platform.OS !== 'web' && !!requireOptionalNativeModule('ExpoTextExtractor');
export async function readText(uri: string): Promise<string[]> {
  if (!canReadText) return [];
  // Loaded only when the app has the text reader, so older apps never crash on it.
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { extractTextFromImage } = require('expo-text-extractor') as typeof import('expo-text-extractor');
  return extractTextFromImage(uri);
}
