// Plug-in and hybrid questions (picture 151 panel 5, Oct 26, 2026). For electric, plug-in hybrid and hybrid cars (from
// the VIN): is the big battery's warranty likely over, and what to ask the seller. No made-up numbers for one car:
// carmakers' battery warranties are usually about 8 years from new, so we only say "likely ended" or "ask for the date".
import { StyleSheet, View } from 'react-native';

import type { Power } from '@/data/check';
import { C, F, themed } from '@/theme';
import { Text } from '@/components/t';

const AMBER = '#B7791F';
const NAME: Record<Power, string> = { electric: 'electric car', plugin: 'plug-in hybrid', hybrid: 'hybrid' };
export const POWER_QUESTIONS: Record<Power, string[]> = {
  electric: ['Can I see a battery health report?', 'How far does it go on a full charge today?', 'Does the charging cable come with it?', 'Any battery or charging repairs in the records?'],
  plugin: ['Can I see a battery health report?', 'How far does it go on electric power today?', 'Does the charging cable come with it?', 'Any battery or charging repairs in the records?'],
  hybrid: ['Has the hybrid battery ever been repaired or replaced?', 'Any hybrid system warning lights or messages?', 'Can I see the service records?'],
};
// Carmakers usually cover the big battery about 8 years from new (often 100,000 miles; some states require longer).
export const BATTERY_YEARS = 8;
export const batteryLikelyEnded = (year: number, now = new Date().getFullYear()) => now - year >= BATTERY_YEARS;

export function PowerQuestions({ power, year }: { power: Power; year: number }) {
  const ended = batteryLikelyEnded(year);
  return (
    <View style={s.box}>
      <Text style={s.kicker}>{`About this ${NAME[power]}`}</Text>
      <Text style={s.title}>{`Before you buy a used ${NAME[power]}`}</Text>
      <View style={s.row}>
        <View style={{ flex: 1 }}>
          <Text style={s.label}>Big battery warranty</Text>
          <Text style={s.small}>Usually about 8 years from new (often 100,000 miles). Some states require longer.</Text>
        </View>
        <Text style={[s.value, { color: ended ? AMBER : C.green }]}>{ended ? 'Likely ended' : 'Ask the end date'}</Text>
      </View>
      <Text style={[s.kicker, { marginTop: 10 }]}>Ask the seller</Text>
      {POWER_QUESTIONS[power].map((q) => <View key={q} style={{ flexDirection: 'row', gap: 8 }}><Text style={s.q}>•</Text><Text style={[s.q, { flex: 1 }]}>{q}</Text></View>)}
      <Text style={[s.small, { marginTop: 6 }]}>A battery check at a dealer or EV shop is worth it before you buy.</Text>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  box: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 16, padding: 14, marginTop: 10 },
  kicker: { fontFamily: F.bodyBold, fontSize: 11, letterSpacing: 1.3, color: C.yellow, textTransform: 'uppercase' },
  title: { fontFamily: F.bodyBold, fontSize: 16, color: C.ink, marginTop: 2 },
  row: { flexDirection: 'row', alignItems: 'center', gap: 10, marginTop: 8, paddingVertical: 6, borderBottomWidth: 1, borderColor: C.line },
  label: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  value: { fontFamily: F.bodyBold, fontSize: 13.5 },
  small: { fontFamily: F.body, fontSize: 12, lineHeight: 17, color: C.muted, marginTop: 2 },
  q: { fontFamily: F.body, fontSize: 14, lineHeight: 20, color: C.ink, marginTop: 5 },
}));
