// "About this car · from its VIN" on the car-for-sale page (picture 149 A, Oct 26, 2026). Every car reads its OWN
// VIN, so a car tapped from "Same car at other dealers" gets its own trim, recalls, accidents and miles. Our take
// on top is written by rules in data/about-car.ts from these facts only (no AI).
import * as WebBrowser from 'expo-web-browser';
import { useEffect, useState } from 'react';
import { StyleSheet, View } from 'react-native';

import { PowerQuestions } from '@/components/power-questions';
import { OwnerProblems, RecallCard } from '@/components/owner-problems';
import { Body, Label, tap } from '@/components/ui';
import { normalMiles, milesFeel, ourTake, vinFacts, type VinFacts } from '@/data/about-car';
import { carForListing, listingTag } from '@/data/fair-price';
import { getFacts, recallsForMyCar, type Recall } from '@/data/gov';
import type { Listing } from '@/data/listings';
import { lastMiles, milesWentDown, shortDate, type MilesReport } from '@/data/vin-miles';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';
import { AlertIcon, ArrowIcon, CheckIcon, ClockIcon, InfoIcon, WrenchIcon } from '@/components/icons';
import { useRefreshTick } from '@/lib/refresh';

type Year = { stars?: number | null; mpg?: number | null; recalls: Recall[] | null };

export function AboutCar({ car }: { car: Listing }) {
  const [vin, setVin] = useState<{ key: string; facts: VinFacts | null } | null>(null);
  const [year, setYear] = useState<{ key: string; facts: Year } | null>(null);
  const [open, setOpen] = useState(false);
  const [report, setReport] = useState<{ key: string; r: MilesReport | null } | null>(null);
  const tick = useRefreshTick();
  useEffect(() => {
    let on = true;
    vinFacts(car.vin).then((f) => on && setVin({ key: car.vin, facts: f })).catch(() => on && setVin({ key: car.vin, facts: null }));
    const ours = carForListing(car);
    const load: Promise<Year> = ours
      ? getFacts(ours.id, car.year).then((f) => ({ stars: f.stars, mpg: f.mpg?.combined ?? null, recalls: f.recalls ?? null }))
      : recallsForMyCar(car.make, car.model, car.year).then((r) => ({ recalls: r }));
    load.then((f) => on && setYear({ key: car.vin, facts: f })).catch(() => on && setYear({ key: car.vin, facts: { recalls: null } }));
    lastMiles(car.vin).then((r) => on && setReport({ key: car.vin, r })).catch(() => {});
    return () => { on = false; };
  }, [car, tick]);
  const v = vin?.key === car.vin ? vin.facts : undefined;
  const y = year?.key === car.vin ? year.facts : undefined;
  const recalls = y?.recalls;
  const rep = report?.key === car.vin ? report.r : null;

  const take = ourTake({ tag: listingTag(car)?.tag, miles: car.miles, year: car.year, accidents: car.accidents, recalls: recalls ? recalls.length : y ? null : undefined });
  const cells: [string, string][] = ([
    ['Trim', v?.trim ?? car.trim],
    ['Engine', v?.engine],
    ['Drive', v?.drive],
    ['Gas', y?.mpg ? `${y.mpg} MPG` : undefined],
    ['Safety', y?.stars ? `${y.stars}★ overall` : undefined],
    ['Built in', v?.builtIn],
  ] as [string, string | undefined][]).filter((c): c is [string, string] => !!c[1]);
  const feel = car.miles != null ? milesFeel(car.miles, car.year) : null;

  return (
    <>
      <RecallCard recalls={recalls} vin={car.vin} make={car.make} />
      {take.length > 0 && (
        <View style={s.take} accessibilityLabel={`Our take. ${take.join(' ')}`}>
          <Label style={{ color: C.yellow }}>Our take</Label>
          <Text style={s.takeText}>{take.flatMap((t, i) => (i ? [' ', t] : [t]))}</Text>
        </View>
      )}
      <View style={s.box}>
        <Label style={{ color: C.yellow }}>About this car · from its VIN</Label>
        {!v && vin === null && !y ? <Body style={s.small}>Reading this car’s VIN…</Body> : null}
        {cells.length > 0 && (
          <View style={s.grid}>
            {cells.map(([k, val]) => (
              <View key={k} style={s.cell}><Text style={s.cellLabel}>{k}</Text><Text style={s.cellValue} numberOfLines={1}>{val}</Text></View>
            ))}
          </View>
        )}
        {recalls === null ? (
          <Row tone="muted" icon="info" title="Couldn’t check recalls" sub="Try again later, or check nhtsa.gov/recalls." />
        ) : recalls?.length ? (
          <Pressable onPress={() => { if (recalls.length) { tap(); setOpen(!open); } }} accessibilityRole={recalls.length ? 'button' : undefined}>
            <Row tone={recalls.length ? 'amber' : 'green'} icon={recalls.length ? 'wrench' : 'check'}
              title={recalls.length ? `${recalls.length} recall${recalls.length > 1 ? 's' : ''} for this year` : 'No recalls for this year'}
              sub={recalls.length ? 'Ask the dealer to show it was fixed. Fixes are free.' : 'From NHTSA'} more={recalls.length > 0} />
          </Pressable>
        ) : recalls ? null : <Body style={s.small}>Checking recalls…</Body>}
        {open && recalls?.map((r) => <View key={r.id} style={s.recall}><Text style={s.rowTitle}>{r.part.split(':')[0]}</Text><Text style={s.small}>{r.summary}</Text></View>)}
        {car.accidents != null && (
          <Row tone={car.accidents ? 'amber' : 'green'} icon={car.accidents ? 'alert' : 'check'}
            title={car.accidents ? `${car.accidents} accident${car.accidents > 1 ? 's' : ''} reported` : 'No accidents reported'}
            sub={car.accidents ? 'Ask for the history report, and have a mechanic look at it.' : 'From the dealer’s listing'} />
        )}
        {feel && (
          <Row tone={feel === 'high' ? 'amber' : 'green'} icon={feel === 'high' ? 'up' : 'check'}
            title={feel === 'low' ? 'Fewer miles than usual' : feel === 'high' ? 'More miles than usual' : 'About normal miles'}
            sub={`About ${normalMiles(car.year).toLocaleString('en-US')} is normal for a ${car.year}.`} />
        )}
        {rep && (milesWentDown(car.miles, rep) ? (
          <Row tone="amber" icon="alert" title="Heads up: miles went down"
            sub={`${rep.maxMiles.toLocaleString('en-US')} mi was reported on ${shortDate(rep.maxAt)}. Ask the dealer about it, and check the history report.`} />
        ) : (
          <Row tone="muted" icon="clock" title={`Last mileage reported: ${rep.lastMiles.toLocaleString('en-US')} mi`} sub={`${shortDate(rep.lastAt)} · by a Carvessa user · not checked by us`} />
        ))}
        <Pressable onPress={() => { tap(); WebBrowser.openBrowserAsync(`https://www.nhtsa.gov/recalls?vin=${car.vin}`).catch(() => {}); }} accessibilityRole="link" style={{ paddingTop: 10 }}>
          <Text style={s.link}>Check open recalls for this exact car on nhtsa.gov ↗</Text>
        </Pressable>
        <Text style={s.vin} selectable>{`VIN ${car.vin} · NHTSA, EPA, dealer listing`}</Text>
      </View>
      <OwnerProblems make={car.make} model={car.model} year={car.year} carId={carForListing(car)?.id} recalls={recalls} vin={car.vin} />
      {v?.power ? <PowerQuestions power={v.power} year={car.year} /> : null}
    </>
  );
}

// Our own line icons, never emoji (Loudjier's rule; Nov 4, 2026 fix).
const ROW_ICON = { info: InfoIcon, wrench: WrenchIcon, check: CheckIcon, alert: AlertIcon, up: ArrowIcon, clock: ClockIcon };
function Row({ tone, icon, title, sub, more }: { tone: 'red' | 'green' | 'amber' | 'muted'; icon: keyof typeof ROW_ICON; title: string; sub: string; more?: boolean }) {
  const Icon = ROW_ICON[icon];
  const color = tone === 'red' ? C.red : tone === 'green' ? C.green : tone === 'amber' ? '#B7791F' : C.muted;
  return (
    <View style={s.row}>
      <View style={[s.icon, { backgroundColor: color + '22' }]}><View style={icon === 'up' ? { transform: [{ rotate: '-90deg' }] } : undefined}><Icon size={16} color={color} /></View></View>
      <View style={{ flex: 1 }}><Text style={s.rowTitle}>{title}</Text><Text style={s.small}>{sub}</Text></View>
      {more ? <Text style={[s.rowTitle, { color: C.yellow }]}>›</Text> : null}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  take: { backgroundColor: C.fill, borderRadius: 16, padding: 14, borderWidth: 1.5, borderColor: C.yellow },
  takeText: { fontFamily: F.body, fontSize: 15, lineHeight: 22, color: C.ink, marginTop: 4 },
  box: { backgroundColor: C.card, borderRadius: 16, padding: 14, borderWidth: 1, borderColor: C.line },
  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginTop: 10 },
  cell: { width: '48%', flexGrow: 1, backgroundColor: C.bg, borderRadius: 12, padding: 10 },
  cellLabel: { fontFamily: F.body, fontSize: 11.5, color: C.muted },
  cellValue: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink, marginTop: 2 },
  row: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingTop: 10 },
  icon: { width: 30, height: 30, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },
  iconText: { fontFamily: F.bodyBold, fontSize: 14 },
  rowTitle: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.ink },
  small: { fontFamily: F.body, fontSize: 12.5, lineHeight: 17, color: C.muted, marginTop: 2 },
  recall: { marginLeft: 40, paddingVertical: 6, borderTopWidth: 1, borderColor: C.line },
  link: { fontFamily: F.bodyBold, fontSize: 13, color: C.yellow },
  vin: { fontFamily: F.body, fontSize: 11, color: C.muted, marginTop: 8 },
}));
