import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { HeartIcon } from '@/components/icons';
import { carName } from '@/data/cars';
import type { Pick } from '@/data/home-rows';
import { priceFor } from '@/data/prices';
import { loanOf } from '@/data/search-budget';
import { paymentFor, useAnswers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { useSaveToggle } from '@/state/save-gate';
import { tr } from '@/i18n';
import { C, F, isDarkLook, look, themed } from '@/theme';

const GAP = 12;
const money = (n: number) => `$${Math.round(n).toLocaleString('en-US')}`;

/** What the ring on the seam shows for a row's tag (match %, 5★, seats, MPG…). */
export function ringOf(tag?: string): { top: string; small?: string; part: number; kind: 'good' | 'gold' | 'warn' } | null {
  if (!tag) return null;
  let m = tag.match(/^(\d+)% match$/);
  if (m) return { top: `${m[1]}%`, part: Number(m[1]) / 100, kind: 'good' };
  if (tag === '5★ safety') return { top: '5★', part: 1, kind: 'gold' };
  m = tag.match(/^Fits (\d+)$/);
  if (m) return { top: m[1], small: 'seats', part: 1, kind: 'gold' };
  m = tag.match(/^(\d+) MPG$/);
  if (m) return { top: m[1], small: 'MPG', part: 1, kind: 'good' };
  if (tag === 'Electric') return { top: 'EV', part: 1, kind: 'good' };
  if (tag === 'Saves gas') return { top: 'MPG', part: 1, kind: 'good' };
  if (tag === 'Fits your plan') return { top: '✓', part: 1, kind: 'good' };
  if (tag === 'Over your plan') return { top: 'Over', part: 1, kind: 'warn' };
  return null;
}

function Ring({ tag }: { tag?: string }) {
  const r = ringOf(tag);
  if (!r) return null;
  const night = isDarkLook(look);
  const col = r.kind === 'gold' ? (night ? '#E8CFA4' : '#86652B') : r.kind === 'warn' ? (night ? '#F2C46D' : '#9A5B00') : (night ? '#9FE0BC' : '#1F6E4E');
  const R = 17;
  const len = 2 * Math.PI * R;
  return (
    <View style={[s.ring, { backgroundColor: C.card }]} pointerEvents="none">
      <Svg width={40} height={40} style={StyleSheet.absoluteFill}>
        <Circle cx={20} cy={20} r={R} stroke={night ? '#2C3036' : '#ECEFEA'} strokeWidth={3.5} fill="none" />
        <Circle cx={20} cy={20} r={R} stroke={col} strokeWidth={3.5} fill="none" strokeLinecap="round"
          strokeDasharray={`${len * r.part} ${len}`} transform="rotate(-90 20 20)" />
      </Svg>
      <Text style={[s.ringT, { color: col, fontSize: r.top.length > 3 ? 9.5 : 11.5 }]}>{r.top}</Text>
      {!!r.small && <Text style={[s.ringS, { color: col }]}>{r.small}</Text>}
    </View>
  );
}

function VMark() {
  const night = isDarkLook(look);
  const fill = night ? '#E8CFA4' : '#E3CFA2';
  const op = night ? 0.22 : 0.6;
  return (
    <Svg viewBox="0 0 100 92" style={s.v} pointerEvents="none">
      <Polygon fill={fill} opacity={op} points="0,0 27,0 52,70 40,92" />
      <Polygon fill={fill} opacity={op} points="100,0 73,0 48,70 60,92" />
    </Svg>
  );
}

function Heart({ id, year }: { id: string; year: number }) {
  const { isSaved } = useSaved();
  const toggle = useSaveToggle();
  const on = isSaved(id, year);
  const night = isDarkLook(look);
  return (
    <Pressable onPress={() => { tap(); toggle(id, year); }} hitSlop={8} accessibilityRole="button" accessibilityState={{ selected: on }}
      accessibilityLabel={on ? 'Remove from saved cars' : 'Save this car'}
      style={[s.heart, { backgroundColor: on ? (night ? '#3A3224' : '#F3E7D0') : C.card }]}>
      <HeartIcon size={14} color={night ? '#E8CFA4' : '#86652B'} />
    </Pressable>
  );
}

export function VCard({ p, width }: { p: Pick; width: number }) {
  const { answers } = useAnswers();
  const name = carName(p.car, p.year);
  const short = name.replace(/^\d{4} /, '');
  const pr = priceFor(p.car, p.year);
  const pay = pr ? paymentFor(loanOf(answers), pr.amount, pr.isNew) : undefined;
  const kind = pr ? (pr.isNew ? 'new' : 'used · est.') : '';
  const stage = Math.round(width * 0.68);
  return (
    <Pressable onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: p.car.id, year: String(p.year) } }); }}
      accessibilityRole="button"
      accessibilityLabel={[name, pr && `${money(pr.amount)} ${kind}`, pay && `${tr(`≈ ${money(pay)}/mo est.`)}`, p.tag].filter(Boolean).join(', ')}
      style={[s.card, { width }]}>
      <View style={[s.stage, { height: stage }]}>
        <VMark />
        <Text style={s.yr}>{String(p.year)}</Text>
        <Heart id={p.car.id} year={p.year} />
        <View style={{ position: 'absolute', left: 0, right: 0, bottom: 6, alignItems: 'center' }}>
          <CarCutout id={p.car.id} year={p.year} label={name} height={stage - 30} style={{ width: '92%' }} flat />
        </View>
      </View>
      <View style={[s.ringAt, { top: stage - 22 }]}><Ring tag={p.tag} /></View>
      <View style={s.info}>
        <Text style={s.nm} numberOfLines={2}>{short}</Text>
        {pr && (
          <Text style={s.pr} numberOfLines={1}>{money(pr.amount)}<Text style={s.kind}>{` ${kind}`}</Text></Text>
        )}
        {pay != null && <View style={s.mo}><Text style={s.moT} numberOfLines={1}>{`≈ ${money(pay)}/mo est.`}</Text></View>}
      </View>
    </Pressable>
  );
}

/** A swipe row: two cards per screen, each swipe moves two, with paging dots. `end` = an extra last tile. */
export function VRow({ picks, end }: { picks: Pick[]; end?: React.ReactNode }) {
  const { width: W, fontScale } = useWindowDimensions();
  const pad = 22;
  const per = fontScale >= 1.3 ? 1 : 2;
  const card = Math.floor((W - pad * 2 - GAP * (per - 1)) / per);
  const step = (card + GAP) * per;
  const count = picks.length + (end ? 1 : 0);
  const pages = Math.max(1, Math.ceil(count / per));
  const [page, setPage] = useState(0);
  return (
    <View>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} snapToInterval={step} decelerationRate="fast" disableIntervalMomentum
        contentContainerStyle={{ paddingHorizontal: pad, gap: GAP, paddingBottom: 8, paddingTop: 2 }} scrollEventThrottle={32}
        onScroll={(e) => setPage(Math.min(pages - 1, Math.max(0, Math.round(e.nativeEvent.contentOffset.x / step))))}>
        {picks.map((p) => <VCard key={`${p.car.id}-${p.year}`} p={p} width={card} />)}
        {end ? <View style={{ width: card }}>{end}</View> : null}
      </ScrollView>
      {pages > 1 && (
        <View style={s.dots} accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
          {Array.from({ length: pages }, (_, i) => <View key={i} style={[s.dot, i === page && s.dotOn]} />)}
        </View>
      )}
    </View>
  );
}

/** "See all" pages: the same card, two per line (one with big text). */
export function VGrid({ picks }: { picks: Pick[] }) {
  const { width: W, fontScale } = useWindowDimensions();
  const per = fontScale >= 1.3 ? 1 : 2;
  const card = Math.floor((W - 22 * 2 - GAP * (per - 1)) / per);
  return (
    <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: GAP }}>
      {picks.map((p) => <VCard key={`${p.car.id}-${p.year}`} p={p} width={card} />)}
    </View>
  );
}

