// Where did I park? (picture 192, Loudjier Nov 6, 2026: 'Yes'). The widget opens this screen. Save your spot
// (location only when you tap, kept on this phone), add a note, a photo and a meter timer, then
// "Take me to my car" opens your map app with directions. Walking first: most people walk back to the car.
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Notifications from 'expo-notifications';
import { Image } from 'expo-image';
import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import { Linking, Modal, Platform, ScrollView, Share, StyleSheet, TextInput, useWindowDimensions, View } from 'react-native';
import Svg, { Circle, Path, Text as SvgText } from 'react-native-svg';

import { AccountTop, BigBtn, Card, Sec } from '@/components/account-ui';
import { Pressable, Text } from '@/components/t';
import { TileMap } from '@/components/tile-map';
import { Body, tap } from '@/components/ui';
import { tr } from '@/i18n';
import { locateExact } from '@/lib/location';
import { canPhoto, pickPhoto } from '@/lib/photo';
import { canRemind, CHANNEL } from '@/lib/reminders';
import { C, F, PAD, themed } from '@/theme';
import { readSnap } from '@/widgets/data';
import { agoText, directionsUrl, meterText, milesBetween, readPark, WEAK_GPS, walkMinutes, writePark, type MapApp, type ParkSpot, type Travel } from '@/widgets/more';
import { redrawWidgets } from '@/widgets/sync';

const PREF_KEY = 'carvessa:park-app:v1';
const METER_ID = 'park-meter';
const METER_CHOICES = [15, 30, 60, 120];
const APPS: { id: MapApp; label: string; sub: string; drive?: boolean }[] = [
  { id: 'google', label: 'Google Maps', sub: 'Walking, driving or transit' },
  ...(Platform.OS === 'ios' ? [{ id: 'apple' as MapApp, label: 'Apple Maps', sub: 'Walking, driving or transit' }] : []),
  { id: 'waze', label: 'Waze', sub: 'Driving only', drive: true },
  ...(Platform.OS === 'android' ? [{ id: 'other' as MapApp, label: 'Another map app', sub: 'Your phone asks which one' }] : []),
];

const refreshWidgets = async () => { try { await redrawWidgets(await readSnap()); } catch { /* no widgets */ } };

async function setMeterAlarm(end: number | undefined) {
  if (Platform.OS === 'web') return;
  try {
    await Notifications.cancelScheduledNotificationAsync(METER_ID).catch(() => {});
    if (!end) return;
    const at = end - 10 * 60000;
    if (at <= Date.now() || !(await canRemind(true))) return;
    await Notifications.scheduleNotificationAsync({
      identifier: METER_ID,
      content: { title: tr('Parking meter: 10 minutes left'), body: tr('Tap to see your spot and walk back to your car.'), data: { screen: 'parking' } },
      trigger: { type: Notifications.SchedulableTriggerInputTypes.DATE, date: new Date(at), channelId: CHANNEL },
    });
  } catch { /* an older app file without alerts */ }
}

export default function Parking() {
  const { save } = useLocalSearchParams<{ save?: string }>();
  const { width } = useWindowDimensions();
  const [spot, setSpot] = useState<ParkSpot | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [me, setMe] = useState<{ lat: number; lon: number } | null>(null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState('');
  const [note, setNote] = useState('');
  const [sheet, setSheet] = useState(false);
  const [travel, setTravel] = useState<Travel>('walk');
  const [app, setApp] = useState<MapApp>('google');
  const [remember, setRemember] = useState(true);
  const [now, setNow] = useState(() => Date.now());
  const autoSaved = useRef(false);

  useEffect(() => {
    let on = true;
    (async () => {
      const p = await readPark();
      if (!on) return;
      setSpot(p); setNote(p?.note ?? ''); setLoaded(true);
      try {
        const pref = JSON.parse((await AsyncStorage.getItem(PREF_KEY)) ?? 'null');
        if (pref && on) { setApp(pref.app); setTravel(pref.travel); }
      } catch { /* first time */ }
      // With a spot saved, find them once so we can say how far it is.
      if (p) { const r = await locateExact(); if (on && r.ok) setMe({ lat: r.lat, lon: r.lon }); }
    })();
    const t = setInterval(() => setNow(Date.now()), 30000);
    return () => { on = false; clearInterval(t); };
  }, []);

  async function saveHere() {
    setBusy(true); setMsg('');
    const r = await locateExact();
    setBusy(false);
    if (!r.ok) {
      setMsg(r.why === 'denied' ? 'Allow location for Carvessa in your phone settings to save your spot.' : r.why === 'off' ? 'Turn on location in your phone settings, then try again.' : 'We couldn’t find where you are. Try again in a moment.');
      return;
    }
    const p: ParkSpot = { lat: r.lat, lon: r.lon, at: Date.now(), acc: Math.round(r.acc), note: note.trim() || undefined };
    setSpot(p); setMe({ lat: r.lat, lon: r.lon });
    await writePark(p);
    if (r.acc > WEAK_GPS) setMsg('Weak signal here (garages do that). Add a note like “Level 3, row C” so you can find it.');
    refreshWidgets();
  }
  // The widget's "Tap when you park" opens this screen with ?save=1: save right away, once.
  useEffect(() => {
    if (save === '1' && loaded && !spot && !autoSaved.current) { autoSaved.current = true; saveHere(); }
  }, [save, loaded, spot]); // eslint-disable-line react-hooks/exhaustive-deps

  async function update(next: ParkSpot | null) {
    setSpot(next);
    await writePark(next);
    refreshWidgets();
  }
  function go(a: MapApp, t: Travel) {
    if (!spot) return;
    const travelNow = APPS.find((x) => x.id === a)?.drive ? 'drive' : t;
    if (remember) AsyncStorage.setItem(PREF_KEY, JSON.stringify({ app: a, travel: travelNow })).catch(() => {});
    setSheet(false);
    Linking.openURL(directionsUrl(a, travelNow, spot)).catch(() => Linking.openURL(directionsUrl('google', travelNow, spot)).catch(() => {}));
  }
  async function takeMe() {
    tap();
    try {
      const pref = JSON.parse((await AsyncStorage.getItem(PREF_KEY)) ?? 'null');
      if (pref?.app) { go(pref.app, pref.travel ?? 'walk'); return; }
    } catch { /* ask */ }
    setSheet(true);
  }

  const mapH = Math.round(Math.min(360, width * 0.85));
  const dist = spot && me ? milesBetween(me, spot) : null;
  const meter = meterText(spot, now);
  const back = () => (router.canGoBack() ? router.back() : router.navigate('/garage'));

  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="My parking spot" back={back} />
      <ScrollView contentContainerStyle={{ paddingBottom: 40 }} keyboardShouldPersistTaps="handled">
        {spot ? (
          <TileMap width={width} height={mapH} center={{ lat: spot.lat, lon: spot.lon }} zoom={16} controlsTop={12}>
            {(proj) => {
              const c = proj(spot.lat, spot.lon);
              const m = me ? proj(me.lat, me.lon) : null;
              return (
                <Svg width={width} height={mapH} style={StyleSheet.absoluteFill} pointerEvents="none">
                  {m ? <Path d={`M${m.x} ${m.y} L${c.x} ${c.y}`} stroke="#1F5FBF" strokeWidth={4} strokeDasharray="2 9" strokeLinecap="round" /> : null}
                  {m ? <Circle cx={m.x} cy={m.y} r={9} fill="#1A73E8" stroke="#fff" strokeWidth={3} /> : null}
                  <Path d={`M${c.x} ${c.y} c-12 -14 -18 -22 -18 -30 a18 18 0 0 1 36 0 c0 8 -6 16 -18 30z`} fill="#1F5FBF" />
                  <Circle cx={c.x} cy={c.y - 30} r={9} fill="#fff" />
                  <SvgText x={c.x} y={c.y - 25.5} fontSize={12} fontWeight="bold" fill="#1F5FBF" textAnchor="middle">P</SvgText>
                </Svg>
              );
            }}
          </TileMap>
        ) : null}

        <View style={{ paddingHorizontal: PAD - 6 }}>
          {!loaded ? null : !spot ? (
            <>
              <Sec>Save where you parked</Sec>
              <Card style={{ padding: 16, gap: 10 }}>
                <Body>We save this spot on your phone only, so you can walk back to it later. We check your location only when you tap.</Body>
                <TextInput value={note} onChangeText={setNote} placeholder={tr('Note (optional): Level 3, row C')} placeholderTextColor={C.muted}
                  style={s.input} accessibilityLabel={tr('Note about your spot')} />
                <BigBtn label={busy ? 'Finding your spot…' : 'I parked here'} onPress={() => { if (!busy) saveHere(); }} />
              </Card>
            </>
          ) : (
            <>
              <View style={{ marginTop: 14, gap: 4 }}>
                <Text style={s.kick}>{tr('Your car is here')}</Text>
                <Text style={s.big}>{dist !== null ? tr('About {d} mi · {m} min walk').replace('{d}', dist < 0.1 ? '0.1' : dist.toFixed(1)).replace('{m}', String(walkMinutes(dist))) : tr('Parked {t}').replace('{t}', tr(agoText(spot.at, now)).toLowerCase())}</Text>
                <Body style={{ color: C.muted }}>{tr('Saved {t}').replace('{t}', new Date(spot.at).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }))}{spot.acc && spot.acc > WEAK_GPS ? ` · ${tr('weak signal')}` : ''}</Body>
              </View>
              <BigBtn label="Take me to my car" onPress={takeMe} />
              <Pressable onPress={() => { tap(); setSheet(true); }} accessibilityRole="button" style={{ alignSelf: 'center', padding: 8 }}>
                <Text style={s.softT}>{tr('Change map app')}</Text>
              </Pressable>
              <Sec>Your note</Sec>
              <Card style={{ padding: 12 }}>
                <TextInput value={note} onChangeText={setNote} onEndEditing={() => update({ ...spot, note: note.trim() || undefined })}
                  placeholder={tr('Level 3, row C')} placeholderTextColor={C.muted} style={s.input} accessibilityLabel={tr('Note about your spot')} />
                {canPhoto ? (
                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, marginTop: 10 }}>
                    {spot.photo ? <Image source={{ uri: spot.photo }} style={{ width: 84, height: 64, borderRadius: 12 }} contentFit="cover" accessibilityLabel={tr('Photo of your spot')} /> : null}
                    <Pressable onPress={async () => { tap(); const ph = await pickPhoto('camera'); if (ph) update({ ...spot, photo: ph.uri }); }} accessibilityRole="button" style={s.soft}>
                      <Text style={s.softT}>{spot.photo ? tr('New photo') : tr('Add a photo of the spot')}</Text>
                    </Pressable>
                  </View>
                ) : null}
              </Card>
              <Sec>Parking meter</Sec>
              <Card style={{ padding: 12, gap: 10 }}>
                {meter ? <Body bold style={{ color: '#B3412F' }}>{tr(meter)}</Body> : <Body style={{ color: C.muted }}>No meter? Skip this. We remind you 10 minutes before it runs out.</Body>}
                <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>
                  {METER_CHOICES.map((m) => (
                    <Pressable key={m} onPress={() => { tap(); const end = Date.now() + m * 60000; update({ ...spot, meterEnd: end }); setMeterAlarm(end); }} accessibilityRole="button" style={s.chip}>
                      <Text style={s.chipT}>{m < 60 ? tr('{n} min').replace('{n}', String(m)) : tr('{n} h').replace('{n}', String(m / 60))}</Text>
                    </Pressable>
                  ))}
                  {spot.meterEnd ? (
                    <Pressable onPress={() => { tap(); update({ ...spot, meterEnd: undefined }); setMeterAlarm(undefined); }} accessibilityRole="button" style={s.chip}>
                      <Text style={s.chipT}>{tr('No meter')}</Text>
                    </Pressable>
                  ) : null}
                </View>
              </Card>
              <View style={{ flexDirection: 'row', gap: 10, marginTop: 14 }}>
                <View style={{ flex: 1 }}><BigBtn kind="soft" label="Share spot" onPress={() => Share.share({ message: `${tr('My car is parked here:')} https://www.google.com/maps/search/?api=1&query=${spot.lat.toFixed(6)},${spot.lon.toFixed(6)}${spot.note ? ` (${spot.note})` : ''}` }).catch(() => {})} /></View>
                <View style={{ flex: 1 }}><BigBtn kind="soft" label="I got my car ✓" onPress={() => { update(null); setMeterAlarm(undefined); setNote(''); setMe(null); }} /></View>
              </View>
            </>
          )}
          {msg ? <Body style={{ marginTop: 12, color: C.ink }}>{tr(msg)}</Body> : null}
        </View>
      </ScrollView>

      <Modal visible={sheet} transparent animationType="slide" onRequestClose={() => setSheet(false)}>
        <Pressable style={s.dim} onPress={() => setSheet(false)} accessibilityLabel={tr('Close')} />
        <View style={s.sheet}>
          <Text style={s.sheetT}>{tr('Take me to my car')}</Text>
          <Text style={s.kick}>{tr('How are you going?')}</Text>
          <View style={{ flexDirection: 'row', gap: 8 }}>
            {(['walk', 'drive', 'transit'] as Travel[]).map((t) => (
              <Pressable key={t} onPress={() => { tap(); setTravel(t); }} accessibilityRole="radio" accessibilityState={{ selected: travel === t }} style={[s.seg, travel === t && s.segOn]}>
                <Text style={[s.segT, travel === t && { color: C.onAccent }]}>{tr(t === 'walk' ? 'Walk' : t === 'drive' ? 'Drive' : 'Bus · train')}</Text>
              </Pressable>
            ))}
          </View>
          <Text style={[s.kick, { marginTop: 14 }]}>{tr('Open in')}</Text>
          {APPS.map((a) => (
            <Pressable key={a.id} onPress={() => { tap(); setApp(a.id); }} accessibilityRole="radio" accessibilityState={{ selected: app === a.id }} style={[s.opt, app === a.id && s.segOn]}>
              <View style={{ flex: 1 }}><Text style={s.optT}>{a.label}</Text><Text style={s.optS}>{tr(a.sub)}</Text></View>
              <View style={[s.radio, app === a.id && s.radioOn]} />
            </Pressable>
          ))}
          <Pressable onPress={() => { tap(); setRemember(!remember); }} accessibilityRole="switch" accessibilityState={{ checked: remember }} style={s.rem}>
            <Text style={s.optT}>{tr('Remember my choice')}</Text>
            <View style={[s.sw, remember && { backgroundColor: C.yellow }]}><View style={[s.knob, remember && { alignSelf: 'flex-end' }]} /></View>
          </Pressable>
          <BigBtn label={travel === 'walk' && !APPS.find((x) => x.id === app)?.drive && dist !== null ? tr('Go · {m} min walk').replace('{m}', String(walkMinutes(dist))) : 'Go'} onPress={() => go(app, travel)} />
        </View>
      </Modal>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  input: { borderWidth: 1, borderColor: C.line, borderRadius: 14, paddingHorizontal: 12, paddingVertical: 10, fontFamily: F.body, fontSize: 15, color: C.ink, backgroundColor: C.bg },
  kick: { fontFamily: F.bodyBold, fontSize: 12, letterSpacing: 0.8, color: C.onAccent, textTransform: 'uppercase', marginBottom: 6 },
  big: { fontFamily: F.bodyBold, fontSize: 22, color: C.ink },
  soft: { backgroundColor: C.fill, borderRadius: 12, paddingHorizontal: 12, paddingVertical: 10 },
  softT: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
  chip: { backgroundColor: C.fill, borderRadius: 999, paddingHorizontal: 14, paddingVertical: 9 },
  chipT: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
  dim: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)' },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 26, borderTopRightRadius: 26, padding: 18, paddingBottom: 34, gap: 8 },
  sheetT: { fontFamily: F.bodyBold, fontSize: 22, color: C.ink, marginBottom: 8 },
  seg: { flex: 1, borderWidth: 2, borderColor: C.line, borderRadius: 16, paddingVertical: 12, alignItems: 'center' },
  segOn: { borderColor: C.yellow, backgroundColor: C.fill },
  segT: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  opt: { flexDirection: 'row', alignItems: 'center', borderWidth: 2, borderColor: C.line, borderRadius: 16, padding: 12 },
  optT: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  optS: { fontFamily: F.body, fontSize: 12.5, color: C.muted },
  radio: { width: 22, height: 22, borderRadius: 11, borderWidth: 2, borderColor: C.line },
  radioOn: { borderWidth: 7, borderColor: C.yellow },
  rem: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: 8 },
  sw: { width: 46, height: 28, borderRadius: 14, backgroundColor: C.line, padding: 3 },
  knob: { width: 22, height: 22, borderRadius: 11, backgroundColor: '#fff' },
}));
