// Photos in the help chats (picture 117 B, Oct 20, 2026). Needs the photo picker built into the phone app:
// test apps made before Oct 20, 2026 don't have it, so the photo button only shows when it works.
// The web test site picks photos with the browser. Photos stay on the phone; nothing is uploaded.
import { requireOptionalNativeModule } from 'expo';
import { Platform } from 'react-native';

export const canPhoto = Platform.OS === 'web' || !!requireOptionalNativeModule('ExponentImagePicker');

type Picker = typeof import('expo-image-picker');
function picker(): Picker | null {
  if (!canPhoto) return null;
  try {
    return require('expo-image-picker') as Picker; // eslint-disable-line @typescript-eslint/no-require-imports
  } catch {
    return null;
  }
}

export type Photo = { uri: string; base64?: string; mime?: string };

/** Take a photo (camera) or choose one (photos). Returns the photo (and a small copy for the AI look), or null. */
// square: a profile photo (crop to a square, smaller file).
export async function pickPhoto(from: 'camera' | 'library', square = false): Promise<Photo | null> {
  const p = picker();
  if (!p) return null;
  const opts = { mediaTypes: ['images'] as ('images')[], quality: square ? 0.2 : 0.4, base64: true, ...(square ? { allowsEditing: true, aspect: [1, 1] as [number, number] } : {}) };
  try {
    if (from === 'camera') {
      if (Platform.OS !== 'web') {
        const ok = await p.requestCameraPermissionsAsync();
        if (!ok.granted) return null;
      }
      return toPhoto(await p.launchCameraAsync(opts));
    }
    return toPhoto(await p.launchImageLibraryAsync(opts));
  } catch {
    return null;
  }
}

function toPhoto(r: { canceled: boolean; assets: { uri: string; base64?: string | null; mimeType?: string | null }[] | null }): Photo | null {
  const a = r.canceled ? null : r.assets?.[0];
  if (!a?.uri) return null;
  // On the web the picture can come back as a data: address with the base64 inside.
  const fromUri = a.uri.match(/^data:(image\/\w+);base64,(.*)$/);
  return { uri: a.uri, base64: a.base64 ?? fromUri?.[2] ?? undefined, mime: a.mimeType ?? fromUri?.[1] ?? 'image/jpeg' };
}
