// Prices you can trust (picture 72 A): the fair-price box, the Looks low / fair / high tag and the
// out-the-door breakdown. Used on the car page, the for-sale car page and the cars-for-sale list.
import { useState } from 'react';
import { StyleSheet, View } from 'react-native';

import { Body, H, Label, tap } from '@/components/ui';
import { BUDGETS, type Car } from '@/data/cars';
import { fairRange, otdLines, type Verdict } from '@/data/fair-price';
import { bandOf, money, priceFor } from '@/data/prices';
import { Ring } from '@/components/ring';
import { monthlyCap, paymentFor, type Answers } from '@/state/answers';
import { C, calm, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';
import { amber, FairBar } from '@/components/fair-motion';

export const VERDICT: Record<Verdict, { title: string; color: () => string; line: string }> = {
  low: { title: 'Looks low', color: amber, line: 'Cheaper than most like it. Great if it’s real, but ask why: accidents, flood damage or a salvage title can lower the price.' },
  fair: { title: 'Looks fair', color: () => C.green, line: 'The price is close to what cars like this usually sell for.' },
  high: { title: 'Looks high', color: () => C.red, line: 'More than most like it. Ask for a lower price, or show the seller this estimate.' },
};

const isLight = (hex: string) => {
  const m = hex.match(/^#([\da-f]{2})([\da-f]{2})([\da-f]{2})/i);
  if (!m) return false;
  const [r, g, b] = m.slice(1).map((x) => parseInt(x, 16) / 255).map((c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b > 0.2;
};

export function PriceTag({ tag }: { tag: Verdict }) {
  const v = VERDICT[tag];
  const bg = v.color();
  // Oct 24, 2026: in the night looks the tag color is light, so the words were light on light. Pick dark or white words by the color.
  return <View style={[s.tag, { backgroundColor: bg }]}><Text style={[s.tagText, { color: isLight(bg) ? '#10151B' : '#FFFFFF' }]}>{v.title}</Text></View>;
}

// The fair price bar moved to fair-motion.tsx (picture 138, animated).
export { FairBar };

/** "Out the door ≈ $23,270", tap to see how. */
export function OtdLine({ price, open: start }: { price: number; open?: boolean }) {
  const [open, setOpen] = useState(!!start);
  const o = otdLines(price);
  return (
    <Pressable onPress={() => { tap(); setOpen(!open); }} accessibilityRole="button" accessibilityState={{ expanded: open }} style={{ marginTop: 8 }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
        <Body bold style={{ fontSize: 13.5, flex: 1 }}>{o.state ? `Out the door ≈ ${money(o.total)} with ${o.state} tax and fees` : `Out the door ≈ ${money(o.total)} with typical tax and fees`}</Body>
        <Label style={{ color: C.yellow, fontSize: 12 }}>{open ? 'Hide' : 'How?'}</Label>
      </View>
      {open && (
        <View style={s.lines}>
          <Body style={s.line}>{`${money(o.price)} car`}</Body>
          <Body style={s.line}>{o.rate ? `+ ${money(o.tax)} ${o.state ?? 'typical'} ${o.taxName} (${o.rate}%${o.cap ? `, up to ${money(o.cap)}` : ''})` : `+ $0 car sales tax in ${o.state}`}</Body>
          <Body style={s.line}>{`+ about ${money(o.fees)} dealer and title fees`}</Body>
          <Body bold style={s.line}>{`= about ${money(o.total)}`}</Body>
          <Body style={[s.small, { marginTop: 4 }]}>{o.state ? 'Estimate. Ask the dealer for the out-the-door price in writing before you go.' : 'Estimate with typical U.S. numbers. Add your ZIP code in the coach to use your state.'}</Body>
        </View>
      )}
    </Pressable>
  );
}

/** The price box on a car page: typical price, payment, fair range (used) and out-the-door. */
export function PriceBox({ car, year, answers }: { car: Car; year: number; answers: Answers }) {
  const p = priceFor(car, year);
  if (!p) return null;
  const range = p.isNew ? undefined : fairRange(car, year);
  const pay = paymentFor(answers, p.amount, p.isNew);
  const cap = monthlyCap(answers);
  const budget = BUDGETS.indexOf(answers.budget ?? '');
  const fits = budget >= 0 ? bandOf(p.amount) <= budget : null;
  return (
    <View style={[s.box, calm && s.boxCalm]}>
      <Label style={{ color: C.yellow, fontSize: 11 }}>{p.isNew ? 'New, starts at about · estimate' : 'Typical price · estimate'}</Label>
      <View style={s.row}>
        <H size={34}>{money(p.amount)}</H>
        <Body bold style={{ color: C.green, fontSize: 14 }}>{`≈ ${money(pay)}/mo`}</Body>
      </View>
      {/* Sunset Calm: the budget ring shows the payment next to your monthly plan. */}
      {calm && cap ? (
        <View style={s.ringRow}>
          <Ring pct={pay / cap} big={money(pay)} small="a month" over={pay > cap} size={84} />
          <View style={{ flex: 1 }}>
            <Body style={s.small}>Your plan</Body>
            <Body bold>{`$${cap}/mo`}</Body>
            <Body bold style={{ fontSize: 13, color: pay > cap ? C.red : C.green }}>{pay <= cap ? `${money(cap - pay)} a month to spare` : `${money(pay - cap)} over your plan`}</Body>
          </View>
        </View>
      ) : null}
      {range && <FairBar range={range} at={p.amount} />}
      {range && <Body style={[s.small, { marginTop: 2 }]}>Fair price for this car. Real cars for sale get a tag: Looks low, Looks fair or Looks high.</Body>}
      <OtdLine price={p.amount} />
      {fits != null && <Body bold style={{ fontSize: 13, marginTop: 6, color: fits ? C.green : C.red }}>{fits ? `Fits your budget (${answers.budget})` : `Above your budget (${answers.budget})`}</Body>}
    </View>
  );
}

