  boxCalm: { backgroundColor: C.card, borderWidth: 0, borderRadius: 22, shadowColor: '#1F6E4E', shadowOpacity: 0.12, shadowRadius: 16, shadowOffset: { width: 0, height: 8 }, elevation: 3 },
  ringRow: { flexDirection: 'row', alignItems: 'center', gap: 12, marginTop: 8 },
