  bar: { height: 8, borderRadius: 4, overflow: 'hidden', flexDirection: 'row' },
  dot: { position: 'absolute', top: -4, width: 16, height: 16, marginLeft: -8, borderRadius: 8, backgroundColor: C.ink, borderWidth: 2, borderColor: C.card },
  ends: { flexDirection: 'row', justifyContent: 'space-between', marginTop: 4 },
  small: { fontSize: 11.5, color: C.muted },
  lines: { marginTop: 6, paddingLeft: 10, borderLeftWidth: 2, borderLeftColor: C.yellow },
  line: { fontSize: 13.5 },
  tag: { alignSelf: 'flex-start', borderRadius: 5, paddingHorizontal: 6, paddingVertical: 2 },
