// Car log (picture 221 A): what they spent on the car (gas, washes, service, repairs, parking, tolls) with an optional
// receipt photo that stays on the phone (picture 221 receipts option 1). Service entries keep living in
// MyCar.services (the old Service history, so "what's due" still learns from oil changes); everything else is MyCar.log.
// Totals are only what the person typed; real MPG only from their own gas fills (miles + gallons).
import type { Service } from '@/data/car-plan';

export type LogKind = 'gas' | 'wash' | 'service' | 'repair' | 'parking' | 'tolls' | 'other';
export type LogEntry = { id: string; kind: LogKind; what?: string; cost?: number; at: number; miles?: number; place?: string; gallons?: number; receipt?: string };

export const LOG_KINDS: { kind: LogKind; label: string }[] = [
  { kind: 'gas', label: 'Gas' }, { kind: 'wash', label: 'Car wash' }, { kind: 'service', label: 'Service' },
  { kind: 'repair', label: 'Repair' }, { kind: 'parking', label: 'Parking' }, { kind: 'tolls', label: 'Tolls' }, { kind: 'other', label: 'Other' },
];
export const logLabel = (k: LogKind) => LOG_KINDS.find((x) => x.kind === k)!.label;

const serviceId = (s: Service) => `svc-${s.at}-${s.what}`;
/** Everything in one list, newest first. Service history rows come in as 'service' entries. */
export function allEntries(c: { log?: LogEntry[]; services?: (Service & { receipt?: string })[] }): LogEntry[] {
  const svc: LogEntry[] = (c.services ?? []).map((s) => ({ id: serviceId(s), kind: 'service', what: s.what, cost: s.cost, at: s.at, miles: s.miles, place: s.where, receipt: s.receipt }));
  return [...(c.log ?? []), ...svc].sort((a, b) => b.at - a.at);
}
export const isService = (e: LogEntry) => e.id.startsWith('svc-');
export const serviceIdOf = serviceId;

/** This month's totals from what they typed. */
export function monthTotals(list: LogEntry[], now: number) {
  const d = new Date(now);
  const inMonth = list.filter((e) => { const x = new Date(e.at); return x.getFullYear() === d.getFullYear() && x.getMonth() === d.getMonth(); });
  const gas = inMonth.filter((e) => e.kind === 'gas');
  const sum = (l: LogEntry[]) => l.reduce((t, e) => t + (e.cost ?? 0), 0);
  return { total: sum(inMonth), gas: sum(gas), fills: gas.length, rest: sum(inMonth) - sum(gas) };
}

/** Real MPG from their last two gas fills that both have miles, the newer one with gallons. Null if we can't tell. */
export function realMpg(list: LogEntry[]): number | null {
  const fills = list.filter((e) => e.kind === 'gas' && e.miles).sort((a, b) => (a.miles! - b.miles!));
  for (let i = fills.length - 1; i > 0; i--) {
    const a = fills[i - 1], b = fills[i];
    if (!b.gallons) continue;
    const mpg = (b.miles! - a.miles!) / b.gallons;
    if (mpg >= 5 && mpg <= 150) return Math.round(mpg * 10) / 10;
  }
  return null;
}

/** For the free account copy: receipts are phone files, so they stay out of it. */
export function withoutReceipts<T extends { log?: LogEntry[]; services?: (Service & { receipt?: string })[] }>(c: T): T {
  const out = { ...c };
  if (c.log) out.log = c.log.map(({ receipt: _r, ...e }) => e);
  if (c.services) out.services = c.services.map(({ receipt: _r, ...s }) => s);
  return out;
}
