/** Colors we can show this car in (empty when we only have the photo's own color). */
export const paintsFor = (id: string, year?: number) => PAINTS[lookKey(id, year)] ?? [];
const paintSrc = (id: string, year?: number, paint?: string) => (paint ? paintsFor(id, year).find((p) => p.name === paint)?.src : undefined);
export const hasCutout = (id: string) => id in CUTOUTS;
/** The cut-out picture for this car (and paint), for the home screen widgets. */
export const cutoutSrc = (id: string, year?: number, paint?: string): number | undefined => paintSrc(id, year, paint) ?? CUTOUTS[lookKey(id, year)];

// Years that look different from today's car get their own cut-out and credit: [first year, last year, key].
const YEAR_LOOKS: Record<string, [number, number, string][]> = {
  trax: [[2017, 2022, 'trax-2017']],
};
/** The cut-out/credit key for this car and year (the car id when we only have today's look). */
export const lookKey = (id: string, year?: number) => (year && YEAR_LOOKS[id]?.find(([a, b]) => year >= a && year <= b)?.[2]) || id;

/** Design C list thumbnail: the cut-out on a soft mint tile (the photo when there is no cut-out). */
export function CarThumb({ id, year, label, width = 84, height = 58 }: { id: string; year?: number; label?: string; width?: number; height?: number }) {
  const src = CUTOUTS[lookKey(id, year)];
  if (!src) return <CarPhoto id={id} label={label} style={{ width, height, borderRadius: 14 }} />;
  return (
    <View style={{ width, height, borderRadius: 14, backgroundColor: C.hero, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' }}>
      <Image source={src} style={{ width: width - 6, height: height - 6 }} contentFit="contain" accessibilityLabel={label ?? 'Car photo'} />
    </View>
  );
}

/** The car with no background, floating with a soft shadow. Falls back to the photo in a round card. */
export function CarCutout({ id, year, paint, height, label, style, flat }: { id: string; year?: number; paint?: string; height: number; label?: string; style?: StyleProp<ViewStyle>; flat?: boolean }) {
  const src = paintSrc(id, year, paint) ?? CUTOUTS[lookKey(id, year)];
  if (!src) return <CarPhoto id={id} label={label} style={[{ height, borderRadius: 22 }, style]} />;
  return (
    <View style={[{ height, alignItems: 'center', justifyContent: 'flex-end' }, style]}>
      {!flat && <View style={{ position: 'absolute', bottom: 2, width: '62%', height: Math.max(6, height * 0.05), borderRadius: 999, backgroundColor: 'rgba(0,0,0,0.14)' }} />}
      <Image source={src} style={{ width: '100%', height: '100%' }} contentFit="contain" accessibilityLabel={label ?? 'Car photo'} transition={150} />
    </View>
  );
}
export const photoOf = (id: string): number | undefined => PHOTOS[id];

export function CarPhoto({ id, style, label }: { id: string; style?: StyleProp<ViewStyle>; label?: string }) {
  return (
    <View style={[{ backgroundColor: C.grey, overflow: 'hidden' }, style]}>
      {!PHOTOS[id] ? (
        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}><CarArt width={90} fill="#8A8F96" /></View>
      ) : <Image source={PHOTOS[id]} style={{ width: '100%', height: '100%' }} contentFit="cover" accessibilityLabel={label ?? 'Car photo'} transition={150} />}
    </View>
  );
}

// Small line under a big photo: who took it and the license. Tap to see the original.
export function PhotoCredit({ id, year, dark, cut, painted }: { id: string; year?: number; dark?: boolean; cut?: boolean; painted?: boolean }) {
  // The year's own cut-out has its own credit; the full photo (not cut) is always today's car.
  const key = cut ? lookKey(id, year) : id;
  const c = CREDITS[key];
  if (!c) return null;
  // Only a real model year (a file name like "1X7A1957.jpg" once read as 1957).
  const shows = c.photoYear && c.photoYear >= 2000 && c.photoYear < thisYear() ? `Photo shows a ${c.photoYear} model · ` : '';
  return (
    <Pressable onPress={() => Linking.openURL(c.page)} accessibilityRole="link" hitSlop={6}>
      <Text style={{ fontFamily: F.body, fontSize: 10.5, color: dark ? '#999' : C.muted, marginTop: 4 }}>
        {shows}Photo{cut && CUTOUTS[key] ? (painted ? ' (background removed, color changed)' : ' (background removed)') : ''}: {c.artist} · {c.license} · Wikimedia Commons
      </Text>
    </Pressable>
  );
}

/** A scanner-only cut-out (data/scan-looks.ts) floating with the same soft shadow as CarCutout. */
export function ScanCutout({ look, height, label }: { look: string; height: number; label?: string }) {
  const src = SCAN_CUTOUTS[look];
  if (!src) return null;
  return (
    <View style={{ height, alignSelf: 'stretch', alignItems: 'center', justifyContent: 'flex-end' }}>
      <View style={{ position: 'absolute', bottom: 2, width: '62%', height: Math.max(6, height * 0.05), borderRadius: 999, backgroundColor: 'rgba(0,0,0,0.14)' }} />
      <Image source={src} style={{ width: '100%', height: '100%' }} contentFit="contain" accessibilityLabel={label ?? 'Car photo'} transition={150} />
    </View>
  );
}

// Picture 229 A (Nov 13, 2026): swipe through more photos on the car page. The photo follows the year
// (an older body shows that body), with a small 'which years look like this' badge and its own credit.
// Give it key={id + year} so a new year starts on the first photo.
export function CarGallery({ id, year, paint, height, label }: { id: string; year?: number; paint?: string; height: number; label?: string }) {
  const g = galleryFor(id, year, lookKey(id, year));
  const [w, setW] = useState(0);
  const [i, setI] = useState(0);
  const [bad, setBad] = useState<string[]>([]);
  const slides = g.slides.filter((sl) => sl.kind === 'cut' || !bad.includes(sl.shot.file));
  // Nothing loaded (offline, or the photo site is down): today's cut-out, as before.
  if (!slides.length) return <CarCutout id={id} year={year} paint={paint} label={label} height={height} />;
  const at = Math.min(i, slides.length - 1);
  const cur = slides[at];
  return (
    <View>
      <View onLayout={(e) => setW(e.nativeEvent.layout.width)} style={{ height, borderRadius: 24, overflow: 'hidden', backgroundColor: C.hero }}>
        {w > 0 && (
          <ScrollView horizontal pagingEnabled showsHorizontalScrollIndicator={false} scrollEventThrottle={32}
            onScroll={(e) => setI(Math.round(e.nativeEvent.contentOffset.x / Math.max(1, w)))}>
            {slides.map((sl, n) => (
              <View key={sl.kind === 'cut' ? 'cut' : sl.shot.file} style={{ width: w, height, alignItems: 'center', justifyContent: 'flex-end', paddingBottom: sl.kind === 'cut' ? 8 : 0 }}>
                {sl.kind === 'cut'
                  ? <CarCutout id={id} year={year} paint={paint} label={label} height={height - 30} style={{ width: '90%' }} />
                  : <Image source={{ uri: shotUrl(sl.shot) }} style={{ width: '100%', height: '100%' }} contentFit="cover" transition={150}
                      accessibilityLabel={`${label ?? tr('Car photo')}, ${tr(sl.shot.view === 'back' ? 'back' : 'front')}, ${n + 1} / ${slides.length}`}
                      onError={() => setBad((b) => (b.includes(sl.shot.file) ? b : [...b, sl.shot.file]))} />}
              </View>
            ))}
          </ScrollView>
        )}
        {g.badge && <View pointerEvents="none" style={gs.badge}><Text style={gs.badgeText}>{g.badge}</Text></View>}
        {slides.length > 1 && (<>
          <View pointerEvents="none" style={gs.count}><Text style={gs.countText}>{`${at + 1} / ${slides.length}`}</Text></View>
          <View pointerEvents="none" style={gs.dots}>
            {slides.map((_, n) => <View key={n} style={[gs.dot, n === at && gs.dotOn]} />)}
          </View>
        </>)}
      </View>
      {cur.kind === 'cut' ? <PhotoCredit id={id} year={year} cut painted={!!paint} />
        : <ShotCredit shot={cur.shot} />}
      {slides.length > 1 && at === 0 && <Text style={{ fontFamily: F.body, fontSize: 10.5, color: C.muted, marginTop: 1 }}>Swipe for more photos</Text>}
    </View>
  );
}

export function ShotCredit({ shot }: { shot: Shot }) {
  const shows = shot.year && shot.year >= 2000 && shot.year < thisYear() ? `Photo shows a ${shot.year} model · ` : '';
  return (
    <Pressable onPress={() => Linking.openURL(shotPage(shot))} accessibilityRole="link" hitSlop={6}>
      <Text style={{ fontFamily: F.body, fontSize: 10.5, color: C.muted, marginTop: 4 }}>
        {shows}Photo: {shot.artist} · {shot.license} · Wikimedia Commons
      </Text>
    </Pressable>
  );
}

