// Budget ring (design C · Sunset Calm): how much of your monthly plan a car's payment uses.
import Svg, { Circle, Text as SvgText } from 'react-native-svg';

import { tr } from '@/i18n';
import { C, F } from '@/theme';

/** pct 0–1 of the ring filled; big = the number in the middle, small = the line under it. */
export function Ring({ pct, big, small, size = 96, stroke, color = C.yellow, over }: { pct: number; big: string; small?: string; size?: number; stroke?: number; color?: string; over?: boolean }) {
  const w = stroke ?? Math.max(5, Math.round(size / 9.6));
  const r = size / 2 - w / 2 - 2;
  const c = 2 * Math.PI * r;
  const p = Math.max(0, Math.min(1, pct));
  const fill = over ? C.red : color;
  return (
    <Svg width={size} height={size} accessible accessibilityLabel={`${tr(big)} ${small ? tr(small) : ''}`}>
      <Circle cx={size / 2} cy={size / 2} r={r} stroke={C.hero} strokeWidth={w} fill="none" />
      <Circle cx={size / 2} cy={size / 2} r={r} stroke={fill} strokeWidth={w} fill="none" strokeLinecap="round"
        strokeDasharray={`${c * p} ${c}`} transform={`rotate(-90 ${size / 2} ${size / 2})`} />
      <SvgText x={size / 2} y={size / 2 + (small ? size * 0.02 : size * 0.07)} textAnchor="middle" fontFamily={F.head} fontSize={size * (small ? 0.19 : 0.24)} fill={C.ink}>{big}</SvgText>
      {small ? <SvgText x={size / 2} y={size / 2 + size * 0.17} textAnchor="middle" fontFamily={F.bodySemi} fontSize={Math.max(9, size * 0.1)} fill={C.muted}>{tr(small)}</SvgText> : null}
    </Svg>
  );
}
