// "What's new" screen (picture 41, style C "Bell on Home", picked Oct 13, 2026).
// Opens from the bell on Home. Only news about your saved cars and your money, with filters.
// Opening it clears the bell's number; items that were new when you opened it keep a dot.
// Items you've already seen move down to "Earlier" (Oct 17, 2026, Loudjier picked A), so old news never looks like a fresh alert.
import { router, useFocusEffect } from 'expo-router';
import { useCallback, useRef, useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BackIcon } from '@/components/icons';
import { Body, H, Label, SquareBtn, tap } from '@/components/ui';
import { useNews, type NewsItem, type NewsKind } from '@/state/news';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';
import { usePullRefresh } from '@/components/pull-refresh';

const FILTERS: { key: 'all' | NewsKind; label: string }[] = [
  { key: 'all', label: 'All' }, { key: 'recall', label: 'Recalls' }, { key: 'deal', label: 'Deals' }, { key: 'money', label: 'Money' }, { key: 'new', label: 'New' },
];
const ICON: Record<NewsKind, string> = { recall: '!', money: '%', deal: '$', new: '★' };
const color = (k: NewsKind) => (k === 'recall' ? C.red : k === 'money' ? C.green : C.yellow);

export default function News() {
  const pull = usePullRefresh();
  const { items, isNew, markAllSeen } = useNews();
  const [filter, setFilter] = useState<'all' | NewsKind>('all');
  const [fresh, setFresh] = useState<Set<string>>(new Set());

  // Remember what was new when the screen opened (for the dots), then clear the bell.
  // Each new visit starts over, so what you saw last time moves to "Earlier".
  const visitStart = useRef(true);
  useFocusEffect(useCallback(() => () => { visitStart.current = true; }, [])); // runs again only after leaving the screen
  useFocusEffect(useCallback(() => {
    const newIds = items.filter((i) => isNew(i.id)).map((i) => i.id);
    if (visitStart.current) setFresh(new Set(newIds));
    else if (newIds.length) setFresh((old) => new Set([...old, ...newIds]));
    visitStart.current = false;
    markAllSeen();
  }, [items, isNew, markAllSeen]));

  // Only show filters that have something in them (deals and new models come later).
  const filters = FILTERS.filter((f) => f.key === 'all' || items.some((i) => i.kind === f.key));
  const shown = filter === 'all' ? items : items.filter((i) => i.kind === filter);

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="What’s new" back={() => (router.canGoBack() ? router.back() : router.navigate('/home'))} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => (router.canGoBack() ? router.back() : router.navigate('/home'))}><BackIcon /></SquareBtn>
          <Label>What’s new</Label>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView refreshControl={pull} contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40 }}>
        {!calm && <H size={34}>What’s new</H>}
        <Body style={{ color: C.muted, fontSize: 14.5 }}>Only news about your cars and your budget.</Body>

        {filters.length > 2 && (
          <View style={s.filters}>
            {filters.map((f) => {
              const on = filter === f.key;
              return (
                <Pressable key={f.key} onPress={() => { tap(); setFilter(f.key); }} accessibilityRole="button" accessibilityState={{ selected: on }} style={[s.chip, on && s.chipOn]}>
                  <Text style={[s.chipText, on && { color: C.bg }]}>{f.label}</Text>
                </Pressable>
              );
            })}
          </View>
        )}

        {shown.filter((i) => fresh.has(i.id)).map((i) => <Item key={i.id} item={i} fresh />)}
        {shown.some((i) => !fresh.has(i.id)) && (<>
          <Label style={{ marginTop: 22 }}>{shown.some((i) => fresh.has(i.id)) ? 'Earlier' : 'Nothing new since your last visit · Earlier'}</Label>
          {shown.filter((i) => !fresh.has(i.id)).map((i) => <Item key={i.id} item={i} fresh={false} />)}
        </>)}

        {!items.length && (
          <View style={s.empty}>
            <Text style={s.emptyTitle}>No news yet</Text>
            <Body style={{ color: C.muted, fontSize: 14, textAlign: 'center' }}>
              Save a car with the ♡ and we’ll show its recalls here, plus news about car loan rates.
            </Body>
          </View>
        )}
        <Text style={s.fine}>Payment changes are estimates. Recalls come from NHTSA. Rates come from the Federal Reserve.</Text>
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

function Item({ item, fresh }: { item: NewsItem; fresh: boolean }) {
  const col = color(item.kind);
  const open = item.car ? () => { tap(); router.push({ pathname: '/car/[id]', params: { id: item.car!.id, year: String(item.car!.year) } }); } : undefined;
  return (
    <Pressable onPress={open} disabled={!open} accessibilityRole={open ? 'button' : undefined} style={s.item}
      accessibilityLabel={`${fresh ? 'New. ' : ''}${item.tag}. ${item.title}. ${item.sub} ${item.source}${item.sponsored ? '. Sponsored' : ''}`}>
      <View style={[s.icon, { backgroundColor: col + '22' }]}><Text style={[s.iconText, { color: col }]}>{ICON[item.kind]}</Text></View>
      <View style={{ flex: 1 }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
          <Text style={[s.tag, { color: col }]}>{item.tag}</Text>
          {fresh && <View style={s.dot} />}
          {item.sponsored && <Text style={s.sponsored}>Sponsored</Text>}
        </View>
        <Text style={s.title}>{item.title}</Text>
        <Text style={s.sub}>{item.sub}</Text>
        <Text style={s.source}>{item.source}</Text>
      </View>
    </Pressable>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: PAD, paddingVertical: 10 },
  filters: { flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginTop: 14 },
  chip: { borderRadius: 18, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, paddingHorizontal: 14, paddingVertical: 8 },
  chipOn: { backgroundColor: C.ink, borderColor: C.ink },
  chipText: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  item: { flexDirection: 'row', gap: 12, backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 16, padding: 14, marginTop: 10 },
  icon: { width: 38, height: 38, borderRadius: 11, alignItems: 'center', justifyContent: 'center' },
  iconText: { fontFamily: F.bodyBold, fontSize: 18 },
  tag: { fontFamily: F.head, fontSize: 12, letterSpacing: 1.2, textTransform: 'uppercase' },
  dot: { width: 8, height: 8, borderRadius: 4, backgroundColor: C.red },
  sponsored: { marginLeft: 'auto', fontFamily: F.bodyBold, fontSize: 11, color: C.muted, borderWidth: 1, borderColor: C.line, borderRadius: 6, paddingHorizontal: 6, paddingVertical: 1 },
  title: { fontFamily: F.bodyBold, fontSize: 16, color: C.ink, marginTop: 2 },
  sub: { fontFamily: F.body, fontSize: 14, lineHeight: 19, color: C.muted, marginTop: 3 },
  source: { fontFamily: F.body, fontSize: 12, color: C.muted, marginTop: 5 },
  empty: { alignItems: 'center', gap: 6, padding: 24, marginTop: 16, borderRadius: 16, borderWidth: 1, borderColor: C.line, borderStyle: 'dashed' },
  emptyTitle: { fontFamily: F.head, fontSize: 22, textTransform: 'uppercase', color: C.ink },
  fine: { fontFamily: F.body, fontSize: 12, color: C.muted, textAlign: 'center', marginTop: 18 },
}));
