// Bottom menu: 6 tabs. The open one is gold, with a soft gold pill behind its icon.
import type { BottomTabBarProps } from 'expo-router/tabs';
import { useEffect } from 'react';
import { StyleSheet, View } from 'react-native';

import { ProfilePic } from '@/components/profile-pic';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Svg, { Circle, Path } from 'react-native-svg';

import { tap } from '@/components/ui';
import { useAuth } from '@/state/auth';
import { useRecalls } from '@/state/recalls';
import { useSaved } from '@/state/saved';
import { C, calm, F, isDarkLook, look, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

// Icon style C · Bold pill (picture 23, picked Oct 10, 2026): our own icons, bolder lines,
// and the open tab gets a soft gold pill.
const ICONS: Record<string, React.ReactNode> = {
  home: <Path d="M4 10.5L12 4l8 6.5V19a1 1 0 0 1-1 1h-4.5v-5.5h-5V20H5a1 1 0 0 1-1-1z" />,
  search: <><Circle cx="10.8" cy="10.8" r="6.3" /><Path d="M15.6 15.6L20 20" /></>,
  foryou: <Path d="M12 20s-7.5-4.4-7.5-10.2A4.3 4.3 0 0 1 12 7.2a4.3 4.3 0 0 1 7.5 2.6C19.5 15.6 12 20 12 20z" />,
  coach: <><Path d="M4.5 6.5A2.5 2.5 0 0 1 7 4h10a2.5 2.5 0 0 1 2.5 2.5v7A2.5 2.5 0 0 1 17 16h-6l-4.5 4v-4H7a2.5 2.5 0 0 1-2.5-2.5z" /><Path d="M8.5 9h7M8.5 12h4.5" /></>,
  garage: <><Path d="M5 18.5V12l1.6-4.2A2 2 0 0 1 8.5 6.5h7a2 2 0 0 1 1.9 1.3L19 12v6.5" /><Path d="M5 12h14M5 18.5h2.5M16.5 18.5H19" /><Circle cx="8" cy="15" r="1" /><Circle cx="16" cy="15" r="1" /></>,
  saved: <Path d="M12 20s-7.5-4.4-7.5-10.2A4.3 4.3 0 0 1 12 7.2a4.3 4.3 0 0 1 7.5 2.6C19.5 15.6 12 20 12 20z" />,
  me: <><Circle cx="12" cy="8.5" r="3.8" /><Path d="M5 20c.6-3.6 3.4-5.6 7-5.6s6.4 2 7 5.6" /></>,
};
// Design 5 (picture 200, Loudjier Nov 6, 2026: 'Both'): 5 tabs. Coach lives in Home's plan card, For you is a Home row.
export const TABS = [
  { name: 'home', label: 'Home' },
  { name: 'search', label: 'Search' },
  { name: 'saved', label: 'Saved' },
  { name: 'garage', label: 'My car' },
  { name: 'me', label: 'Me' },
];
// Screens that live under a tab without being a tab themselves.
const PARENT: Record<string, string> = { coach: 'home', foryou: 'home', results: 'home', parking: 'garage', sos: 'garage', 'car-pass': 'garage', trips: 'garage', 'light-help': 'garage', 'checks': 'search', 'car/[id]': 'search', 'near/[id]': 'search', 'cost/[id]': 'search', 'my-car': 'garage', hustle: 'home', compare: 'saved', warning: 'garage', weird: 'garage', features: 'home', color: 'home', afford: 'home', alerts: 'me', profile: 'me', account: 'me', join: 'me', look: 'me', about: 'me', legal: 'me', 'row/[key]': 'home', popular: 'home', loan: 'garage', service: 'garage', value: 'garage', insure: 'garage', preapproved: 'search' };

// Picture 129 (Oct 24, 2026, Loudjier picked B): For you is a gold heart in a soft gold pill, with a red dot once a day
// until it's opened ("new cars for you today"). Me shows your first letter in a ring, or your Google photo.
const GOLD = () => (isDarkLook(look) ? { bg: 'rgba(227,194,122,0.18)', fg: '#E3C27A' } : { bg: '#FBF0D9', fg: '#8A6420' });
const today = () => new Date().toISOString().slice(0, 10);

// Picture 131: your profile picture (own photo, one of ours, Google photo or your letter) in a thin ring.
function MeIcon({ on }: { on: boolean }) {
  const { session, name } = useAuth();
  if (!session) return null;
  return <View style={[s.av, { borderColor: on ? C.yellow : C.muted }]}><ProfilePic name={name ?? '?'} size={22} /></View>;
}

export function TabBar({ state, navigation }: BottomTabBarProps) {
  const insets = useSafeAreaInsets();
  const { freshCount } = useRecalls();
  const { session } = useAuth();
  const { prefs, setPrefs, ready } = useSaved();
  const current = state.routes[state.index]?.name;
  const active = PARENT[current] ?? current;
  const day = today();
  const dot = ready && prefs.forYouSeen !== day && active !== 'foryou';
  // Opening For you clears the dot for today.
  useEffect(() => {
    if (ready && active === 'foryou' && prefs.forYouSeen !== day) setPrefs({ ...prefs, forYouSeen: day });
  }, [ready, active, day, prefs, setPrefs]);
  const gold = GOLD();
  return (
    <View style={[s.bar, calm && s.barCalm, { paddingBottom: Math.max(insets.bottom, 8) }]}>
      {TABS.map((t) => {
        const on = active === t.name;
        return (
          <Pressable key={t.name} accessibilityRole="tab" accessibilityState={{ selected: on }} accessibilityLabel={t.label}
            onPress={() => { tap(); navigation.navigate(t.name); }}
            style={s.tab}>
            {t.name === 'foryou' ? (
              <View style={[s.pill, { backgroundColor: gold.bg }]}>
                <Svg width={23} height={23} viewBox="0 0 24 24" fill={on ? gold.fg : 'none'} stroke={gold.fg} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">{ICONS.foryou}</Svg>
                {dot && <View style={s.dot} accessibilityLabel="New cars for you today" />}
              </View>
            ) : t.name === 'me' && session ? (
              <View style={[s.pill, on && { backgroundColor: C.accentSoft }]}><MeIcon on={on} /></View>
            ) : (
              <View style={[s.pill, on && { backgroundColor: C.accentSoft }]}>
                <Svg width={23} height={23} viewBox="0 0 24 24" fill="none" stroke={on ? C.yellow : calm ? C.muted : C.ink} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
                  {ICONS[t.name]}
                </Svg>
              </View>
            )}
            <Text style={[s.label, calm && !on && { color: C.muted }, on && s.labelOn, t.name === 'foryou' && { color: gold.fg, fontFamily: F.bodyBold }]}>{t.label}</Text>
            {t.name === 'garage' && freshCount > 0 && (
              <View style={s.badge} accessibilityLabel={`${freshCount} new recall${freshCount === 1 ? '' : 's'}`}><Text style={s.badgeText}>{freshCount > 9 ? '9+' : freshCount}</Text></View>
            )}
          </Pressable>
        );
      })}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  bar: { flexDirection: 'row', backgroundColor: C.bg, borderTopWidth: 1, borderTopColor: C.line },
  // Sunset Calm: a white bar with round top corners floating over the mint page.
  barCalm: { backgroundColor: C.card, borderTopWidth: 0, borderTopLeftRadius: 22, borderTopRightRadius: 22, marginTop: -22, shadowColor: '#1F6E4E', shadowOpacity: 0.12, shadowRadius: 14, shadowOffset: { width: 0, height: -4 }, elevation: 8 },
  tab: { flex: 1, alignItems: 'center', gap: 2, paddingTop: 7, paddingBottom: 4 },
  pill: { paddingHorizontal: 14, paddingVertical: 3, borderRadius: 14 },
  label: { fontFamily: F.body, fontSize: 11.5, color: C.ink },
  labelOn: { fontFamily: F.bodyBold, color: C.yellow },
  dot: { position: 'absolute', top: 1, right: 9, width: 9, height: 9, borderRadius: 5, backgroundColor: '#E0483A', borderWidth: 1.5, borderColor: C.card },
  av: { width: 26, height: 26, borderRadius: 13, borderWidth: 1.5, alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },
  avT: { fontFamily: F.bodyBold, fontSize: 12 },
  badge: { position: 'absolute', top: 3, left: '56%', minWidth: 17, height: 17, borderRadius: 9, backgroundColor: C.red, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 4 },
  badgeText: { fontFamily: F.bodyBold, fontSize: 10.5, color: '#FFFFFF' },
}));
