import { Pressable, Text } from '@/components/t';

/** Three quick facts we really know: EPA mileage, seats, and NHTSA recalls. */
export function quickFacts(car: Car, year: number): string[] {
  const f = savedFacts(car.id, year);
  const out: string[] = [];
  if (f?.mpg?.combined) out.push(f.mpg.fuel === 'EV' ? `${f.mpg.combined} MPGe` : `${f.mpg.combined} MPG`);
  out.push(`${car.seats} seats`);
  if (f?.recalls) out.push(f.recalls.length ? `${f.recalls.length} recall${f.recalls.length === 1 ? '' : 's'}` : 'No recalls');
  return out;
}

// note: e.g. "SUV · XLE version". pay/over: from Search › Monthly; else we work out the payment estimate here.
export function BigCard({ car, year, note, pay, over }: { car: Car; year: number; note?: string; pay?: number; over?: number }) {
  const { answers } = useAnswers();
  const { comparing, toggleCompare } = useSaved();
  const p = priceFor(car, year);
  const name = carName(car, year);
  const est = pay ?? (p ? paymentFor(loanOf(answers), p.amount, p.isNew) : undefined);
  const cap = monthlyCap(answers);
  // Their own plan decides the tag: a monthly payment from the coach, or the Monthly chip in Search.
  const gap = over ?? (cap && est ? est - cap : undefined);
  // Pre-approved (picture 167 screen 15) and no monthly plan: does it fit what the lender said yes to?
  const pre = gap == null && p ? fitsPre(answers, p.amount) : undefined;
  const amber = tint('amber');
  const on = comparing.some((x) => x.id === car.id);
  const open = () => { tap(); router.push({ pathname: '/car/[id]', params: { id: car.id, year: String(year) } }); };
  return (
    <View style={s.card}>
      <Pressable onPress={open} accessibilityRole="button" accessibilityLabel={name} style={s.band}>
        <CarCutout id={car.id} year={year} label={name} height={128} style={{ width: '82%' }} />
        {gap != null && (
          <View style={[s.tag, gap > 0 ? { backgroundColor: amber.bg } : { backgroundColor: C.goodBg }]}>
            <Text style={[s.tagT, { color: gap > 0 ? amber.fg : C.goodInk }]}>{gap > 0 ? `${money(gap)} over your plan` : '✓ Fits your plan'}</Text>
          </View>
        )}
        {pre != null && (
          <View style={[s.tag, pre ? { backgroundColor: C.goodBg } : { backgroundColor: amber.bg }]}>
            <Text style={[s.tagT, { color: pre ? C.goodInk : amber.fg }]}>{pre ? '✓ Fits your pre-approval' : 'Over your pre-approval'}</Text>
          </View>
        )}
        <View style={s.heart}><SaveHeart id={car.id} year={year} /></View>
      </Pressable>
      <View style={s.body}>
        <Text style={s.kind}>{note ?? `${car.body}${car.green === 'ev' ? ' · Electric' : car.green === 'hybrid' ? ' · Hybrid' : ''}`}</Text>
        <Text style={s.name}>{name}</Text>
        {p && (
          <View style={s.priceRow}>
            <Text style={s.price}>{money(p.amount)}</Text>
            <Text style={s.small}>{p.isNew ? 'new · starting price' : 'used · est.'}</Text>
            {est != null && <Text style={s.pay}>{`≈ ${money(est)}/mo est.`}</Text>}
          </View>
        )}
        <View style={s.facts}>{quickFacts(car, year).map((f) => <View key={f} style={s.fact}><Text style={s.factT}>{f}</Text></View>)}</View>
        <View style={s.btns}>
          <Pressable onPress={open} accessibilityRole="button" style={[s.btn, s.ghost]}><Text style={s.ghostT}>See details</Text></Pressable>
          <Pressable onPress={() => { tap(); router.push({ pathname: '/shop', params: { ids: car.id } }); }} accessibilityRole="button" style={[s.btn, s.soft]}>
            <Text style={s.softT} numberOfLines={1}>For sale near you</Text>
          </Pressable>
        </View>
        <Pressable onPress={() => { tap(); toggleCompare(car.id, year); }} accessibilityRole="checkbox" accessibilityState={{ checked: on }}
          accessibilityLabel={`Compare ${name}`} hitSlop={6} style={s.cmp}>
          <View style={[s.box, on && { backgroundColor: C.yellow, borderColor: C.yellow }]}>{on && <Text style={s.tick}>✓</Text>}</View>
          <Text style={s.cmpT}>{on ? 'Comparing' : 'Compare'}</Text>
        </Pressable>
      </View>
    </View>
  );
}

/** Floating bar once a car is picked to compare: "Compare 2 cars ›" (needs 2), and Clear. */
export function CompareBar({ lift = 0 }: { lift?: number }) {
  const { comparing, clearCompare } = useSaved();
  const insets = useSafeAreaInsets();
  if (!comparing.length) return null;
  const ready = comparing.length >= 2;
  const names = comparing.map((x) => CARS.find((c) => c.id === x.id)?.model).filter(Boolean).join(' · ');
  return (
    <View style={[s.bar, { bottom: 12 + lift + Math.max(insets.bottom - 20, 0) }]}>
      <View style={{ flex: 1 }}>
        <Text style={s.barT}>{ready ? `Compare ${comparing.length} cars` : 'Pick one more to compare'}</Text>
        <Text style={s.barS} numberOfLines={1}>{names}</Text>
      </View>
      <Pressable onPress={() => { tap(); clearCompare(); }} accessibilityRole="button" hitSlop={8}><Text style={s.clear}>Clear</Text></Pressable>
      <Pressable onPress={() => { if (!ready) return; tap(); router.push({ pathname: '/compare', params: { cars: comparing.map((x) => `${x.id}:${x.year}`).join(',') } }); }}
        accessibilityRole="button" accessibilityState={{ disabled: !ready }} style={[s.go, !ready && { opacity: 0.5 }]}>
        <Text style={s.goT}>Compare ›</Text>
      </Pressable>
    </View>
  );
}

