// What to check on this car (picture 152 facts, picture 153 calm look, Oct 26, 2026, Loudjier: 'let's not scare people and
// business we should be doing business with'). Owner reports from NHTSA by part, closed by default, reassurance first, gray
// bars. Tap a part: with a recall, how to check THIS car got the free fix; without one, what to ask and what to feel for.
// RecallCard sits near the top: calm "N recalls · free fix", red only for a fire risk, green when there are none.
import { router } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import { useEffect, useState } from 'react';
import { StyleSheet, View } from 'react-native';

import { tap } from '@/components/ui';
import type { Recall } from '@/data/gov';
import { complaintsFor, govNames, PART_NAME, summarize, WATCH_ANY, WATCH_FOR, worstDanger, type PartReport, type Problems } from '@/data/owner-problems';
import { C, F, isDarkLook, look, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';
import { useRefreshTick } from '@/lib/refresh';

const SHOW = 6;
const FEW = 20; // under this many reports we just say "Few owner reports"
// Calm amber for recalls; darker in the night looks so it doesn't glow.
const amber = () => (isDarkLook(look) ? { bg: '#33291A', line: '#6B5428', title: '#F2C66D', text: '#E8DCC2', link: '#F2C66D' } : { bg: '#FFF7E6', line: '#F0D9A8', title: '#6B4A0E', text: '#5C4A2A', link: '#1F5FBF' });
const GRAY = '#9AA8BC';
type Mode = 'buy' | 'own';
const brandName = (make: string) => (['BMW', 'GMC'].includes(make.toUpperCase()) ? make.toUpperCase() : make.charAt(0).toUpperCase() + make.slice(1).toLowerCase());
const openVin = (vin?: string) => { tap(); WebBrowser.openBrowserAsync(vin ? `https://www.nhtsa.gov/recalls?vin=${vin}` : 'https://www.nhtsa.gov/recalls').catch(() => {}); };
const count = (n: number, one: string, many: string) => (n === 1 ? `1 ${one}` : `${n.toLocaleString('en-US')} ${many}`);

export function OwnerProblems({ make, model, year, carId, recalls, vin, mode = 'buy' }:
  { make: string; model: string; year: number; carId?: string; recalls?: Recall[] | null; vin?: string; mode?: Mode }) {
  const names = govNames({ carId, make, model });
  const key = `${names.make}|${names.models.join(',')}|${year}`;
  const [got, setGot] = useState<{ key: string; list: Awaited<ReturnType<typeof complaintsFor>> } | null>(null);
  const [shown, setShown] = useState(false);
  const [open, setOpen] = useState<string | null>(null);
  const [all, setAll] = useState(false);
  const tick = useRefreshTick();
  useEffect(() => {
    let on = true;
    complaintsFor(names.make, names.models, year).then((list) => on && setGot({ key, list })).catch(() => on && setGot({ key, list: null }));
    return () => { on = false; };
  }, [key, tick]); // eslint-disable-line react-hooks/exhaustive-deps
  const list = got?.key === key ? got.list : undefined;
  const p: Problems | null = list ? summarize(list, recalls ?? []) : null;
  const brand = brandName(make);
  const nRecalls = recalls?.length ?? 0;
  const title = mode === 'buy' ? 'What to check on this car' : 'Keep an eye on';

  if (list === null) return null; // couldn't reach NHTSA: say nothing rather than worry anyone
  return (
    <View style={s.box}>
      <Pressable onPress={() => { if (p) { tap(); setShown(!shown); } }} accessibilityRole="button" accessibilityState={{ expanded: shown }}>
        <View style={s.headRow}>
          <Text style={[s.kicker, { flex: 1 }]}>{title}</Text>
          {p ? <Text style={s.link}>{shown ? 'Hide' : 'Tap to see ›'}</Text> : null}
        </View>
        <Text style={[s.small, { color: C.ink }]}>{mode === 'buy' ? 'Every model gets owner reports. Most cars are fine.' : 'What owners of your car report, and what to watch for.'}</Text>
        {!p ? <Text style={s.small}>Reading owner reports…</Text> : !shown && (
          <View style={s.chips}>
            <Text style={s.chip}>{p.total < FEW ? 'Few owner reports' : count(p.total, 'owner report', 'owner reports')}</Text>
            {nRecalls > 0 && <Text style={s.chip}>{count(nRecalls, 'recall', 'recalls')}</Text>}
          </View>
        )}
      </Pressable>
      {p && shown && (
        <>
          <Text style={s.reassure}>{mode === 'buy' ? 'Most cars of this model are fine. Here’s where to look.' : 'Most cars of this model are fine. If something feels off, here’s what to watch for.'}</Text>
          {p.total ? (
            <>
              <Text style={s.big}>{count(p.total, 'owner report', 'owner reports')}</Text>
              <Text style={s.small}>{`${year} ${model} · to the U.S. government (NHTSA)`}</Text>
            </>
          ) : <Text style={s.small}>No owner reports to the government for this model year yet.</Text>}
          {(p.crashes > 0 || p.fires > 0) && (
            <View style={s.chips}>
              {p.crashes > 0 && <Text style={s.chip}>{count(p.crashes, 'crash report', 'crash reports')}</Text>}
              {p.fires > 0 && <Text style={s.chip}>{count(p.fires, 'fire report', 'fire reports')}</Text>}
            </View>
          )}
          {(all ? p.parts : p.parts.slice(0, SHOW)).map((r) => (
            <PartRow key={r.part} r={r} max={Math.max(1, ...p.parts.map((x) => x.count))} open={open === r.part}
              onPress={() => { tap(); setOpen(open === r.part ? null : r.part); }} mode={mode} brand={brand} vin={vin} />
          ))}
          {!all && p.parts.length > SHOW && (
            <Pressable onPress={() => { tap(); setAll(true); }} accessibilityRole="button" style={{ paddingVertical: 8 }}>
              <Text style={s.link}>{`Show all ${p.parts.length} parts`}</Text>
            </Pressable>
          )}
          <Text style={[s.small, { marginTop: 8 }]}>Owners wrote these reports; nobody checked them. Tap a part to see what to check.</Text>
        </>
      )}
    </View>
  );
}

function PartRow({ r, max, open, onPress, mode, brand, vin }: { r: PartReport; max: number; open: boolean; onPress: () => void; mode: Mode; brand: string; vin?: string }) {
  const name = PART_NAME[r.part];
  const n = r.recalls.length;
  return (
    <View>
      <Pressable onPress={onPress} accessibilityRole="button" accessibilityState={{ expanded: open }} accessibilityLabel={`${name}, ${r.count} reports`} style={s.row}>
        <View style={s.rowTop}>
          <Text style={[s.rowName, open && { color: C.yellow }]}>{name}</Text>
          {n > 0 && <Text style={s.tag}>{n === 1 ? '1 recall · free fix' : `${n} recalls · free fix`}</Text>}
          <View style={{ flex: 1 }} />
          <Text style={s.rowCount}>{String(r.count)}</Text>
          <Text style={[s.rowCount, { color: C.yellow, marginLeft: 6 }]}>{open ? '⌃' : '›'}</Text>
        </View>
        <View style={s.track}><View style={[s.fill, { width: `${Math.max(3, Math.round((r.count / max) * 100))}%` }, open && { backgroundColor: C.yellow }]} /></View>
      </Pressable>
      {open && (
        <View style={s.detail}>
          {n > 0 ? (
            <>
              <Text style={s.small}>{`${n === 1 ? 'A recall covers' : `${n} recalls cover`} this part. The carmaker fixes it for free.`}</Text>
              <Text style={s.stepsTitle}>{mode === 'buy' ? 'Was it fixed on this car?' : 'Is it fixed on your car?'}</Text>
              <Step n={1} title={mode === 'buy' ? 'Check this VIN for open recalls' : 'Check your VIN for open recalls'} sub="nhtsa.gov shows if this car still needs the fix." onPress={() => openVin(vin)} />
              {mode === 'buy' && <Step n={2} title="Ask for the recall repair receipt" sub={`Any ${brand} dealer can look up the VIN’s recall work, too.`} />}
              <Step n={mode === 'buy' ? 3 : 2} title={mode === 'buy' ? 'Still open? Ask the seller to get it fixed first' : 'Still open? Book the free fix'} sub={`The fix is free at any ${brand} dealer.`} />
            </>
          ) : mode === 'buy' ? (
            <>
              <Text style={s.stepsTitle}>Easy ways to check</Text>
              <Step n={1} title="Ask for the service records" sub="“Was this ever repaired? Can I see the receipt?”" />
              <Step n={2} title={`Ask a ${brand} dealer for the warranty history`} sub="Brand dealers can see warranty repairs on the VIN." />
              <Step n={3} title="Get a history report" sub="Carfax or AutoCheck (paid) may list repairs." />
              <Text style={s.stepsTitle}>On the test drive</Text>
              {(WATCH_FOR[r.part] ?? WATCH_ANY).map((w) => <Check key={w} text={w} />)}
              <Text style={[s.small, { marginTop: 6 }]}>Best move: have a mechanic check it before you buy.</Text>
            </>
          ) : (
            <>
              <Text style={s.stepsTitle}>Watch for</Text>
              {(WATCH_FOR[r.part] ?? WATCH_ANY).map((w) => <Check key={w} text={w} />)}
              <Pressable onPress={() => { tap(); router.push({ pathname: '/light-help', params: { kind: 'ask', id: 'start' } }); }} accessibilityRole="button" style={s.btn}>
                <Text style={s.btnText}>Something feels off? Ask about my car ›</Text>
              </Pressable>
            </>
          )}
        </View>
      )}
    </View>
  );
}

function Step({ n, title, sub, onPress }: { n: number; title: string; sub: string; onPress?: () => void }) {
  const body = (
    <View style={s.step}>
      <View style={s.num}><Text style={s.numText}>{String(n)}</Text></View>
      <View style={{ flex: 1 }}><Text style={s.stepTitle}>{title}</Text><Text style={s.small}>{sub}</Text></View>
      {onPress ? <Text style={[s.stepTitle, { color: C.yellow }]}>›</Text> : null}
    </View>
  );
  return onPress ? <Pressable onPress={onPress} accessibilityRole="link">{body}</Pressable> : body;
}
function Check({ text }: { text: string }) {
  return <View style={s.check}><Text style={s.checkBox}>☐</Text><Text style={[s.stepTitle, { flex: 1, fontFamily: F.body }]}>{text}</Text></View>;
}

/** Recalls near the top (picture 153): calm "free fix" card; red only for a fire risk; green when there are none.
 *  recalls: undefined/null = not known yet (shows nothing). good=false hides the green card (a screen that already says so). */
export function RecallCard({ recalls, vin, make, mode = 'buy', good = true }: { recalls?: Recall[] | null; vin?: string; make?: string; mode?: Mode; good?: boolean }) {
  if (!recalls) return null;
  if (!recalls.length) {
    if (!good) return null;
    return (
      <View style={[s.card, s.good]}>
        <Text style={[s.cardTitle, { color: C.green }]}>✓ No recalls for this year</Text>
        <Text style={s.small}>From NHTSA</Text>
      </View>
    );
  }
  const fire = worstDanger(recalls)?.kind === 'fire';
  const n = recalls.length;
  const brand = make ? brandName(make) : '';
  const line = fire
    ? (mode === 'buy' ? 'The carmaker will fix it for free. Make sure this car got it before you buy.' : 'The carmaker will fix it for free. Book it soon.')
    : (mode === 'buy' ? 'Normal for many cars. Make sure this one got the fix.' : brand ? `Book it at any ${brand} dealer. It’s free.` : 'Book it at the dealer. It’s free.');
  return (
    <View style={[s.card, fire ? s.fire : s.amber]}>
      <Text style={[s.cardTitle, !fire && s.amberTitle, fire && { color: C.red }]}>{fire ? 'Safety recall: fire risk · free fix' : n === 1 ? '1 recall · free fix' : `${n} recalls · free fix`}</Text>
      <Text style={[s.cardText, !fire && s.amberText]}>{line}</Text>
      <Pressable onPress={() => openVin(vin)} accessibilityRole="link" style={{ paddingTop: 6 }}>
        <Text style={[s.link, fire ? { color: C.red } : s.amberLink]}>{mode === 'buy' ? 'Check this VIN ›' : 'Check my VIN ›'}</Text>
      </Pressable>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  box: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 16, padding: 14, marginTop: 10 },
  headRow: { flexDirection: 'row', alignItems: 'center', gap: 8 },
  kicker: { fontFamily: F.bodyBold, fontSize: 11, letterSpacing: 1.3, color: C.muted, textTransform: 'uppercase' },
  big: { fontFamily: F.head, fontSize: 18, color: C.ink, marginTop: 8 },
  small: { fontFamily: F.body, fontSize: 12, lineHeight: 17, color: C.muted, marginTop: 2 },
  link: { fontFamily: F.bodyBold, fontSize: 13, color: C.yellow },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 8 },
  chip: { fontFamily: F.bodyBold, fontSize: 11.5, color: C.muted, backgroundColor: C.bg, borderRadius: 999, paddingHorizontal: 9, paddingVertical: 3, overflow: 'hidden' },
  reassure: { fontFamily: F.bodyBold, fontSize: 12.5, lineHeight: 18, color: C.green, backgroundColor: C.green + '1A', borderRadius: 12, padding: 10, marginTop: 10, overflow: 'hidden' },
  row: { paddingTop: 10 },
  rowTop: { flexDirection: 'row', alignItems: 'center', gap: 6 },
  rowName: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  tag: { fontFamily: F.bodyBold, fontSize: 10.5, color: C.muted, backgroundColor: C.bg, borderRadius: 999, paddingHorizontal: 7, paddingVertical: 1, overflow: 'hidden' },
  rowCount: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  track: { height: 6, borderRadius: 4, backgroundColor: C.line, marginTop: 4, overflow: 'hidden' },
  fill: { height: 6, borderRadius: 4, backgroundColor: GRAY },
  detail: { marginTop: 8, padding: 10, borderRadius: 12, backgroundColor: C.bg },
  stepsTitle: { fontFamily: F.bodyBold, fontSize: 11, letterSpacing: 1.2, color: C.muted, textTransform: 'uppercase', marginTop: 10 },
  step: { flexDirection: 'row', alignItems: 'flex-start', gap: 9, paddingVertical: 6 },
  num: { width: 22, height: 22, borderRadius: 11, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  numText: { fontFamily: F.bodyBold, fontSize: 12, color: C.onAccent },
  stepTitle: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.ink },
  check: { flexDirection: 'row', gap: 8, alignItems: 'flex-start', paddingVertical: 4 },
  checkBox: { fontSize: 14, color: C.muted },
  btn: { marginTop: 8, backgroundColor: C.fill, borderRadius: 999, paddingVertical: 10, alignItems: 'center' },
  btnText: { fontFamily: F.bodyBold, fontSize: 13, color: C.onAccent },
  card: { borderRadius: 14, borderWidth: 1, padding: 12, marginTop: 12 },
  amber: { backgroundColor: amber().bg, borderColor: amber().line },
  amberTitle: { color: amber().title },
  amberText: { color: amber().text },
  amberLink: { color: amber().link },
  fire: { backgroundColor: C.red + '14', borderColor: C.red + '66' },
  good: { backgroundColor: C.green + '14', borderColor: C.green + '55' },
  cardTitle: { fontFamily: F.bodyBold, fontSize: 14.5 },
  cardText: { fontFamily: F.body, fontSize: 12.5, lineHeight: 17, color: C.ink, marginTop: 3 },
}));
