// Accounts (Oct 10, 2026): email + password through Supabase, and Google (Oct 12, 2026). Apple when
// we join the Apple Developer Program. Anyone can still use the app as a guest.
import type { Session } from '@supabase/supabase-js';
import * as Linking from 'expo-linking';
import * as WebBrowser from 'expo-web-browser';
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { AppState, Platform } from 'react-native';

import { AccountGate } from '@/components/account-gate';
import { SignInSheet } from '@/components/sign-in-sheet';
import { supabase } from '@/lib/supabase';

type Ctx = {
  session: Session | null;
  name: string; // what we show next to reviews
  ready: boolean;
  // Returns an error to show, null when logged in, or NEED_CODE when the email must be confirmed with a code first.
  signUp: (name: string, email: string, password: string) => Promise<string | null>;
  signIn: (email: string, password: string) => Promise<string | null>;
  confirmCode: (email: string, code: string) => Promise<string | null>; // the sign-up code (picture 184 A)
  resendSignupCode: (email: string) => Promise<string | null>;
  signInWithGoogle: () => Promise<string | null>; // null = logged in (or the person closed Google)
  signOut: () => Promise<void>;
  deleteAccount: () => Promise<string | null>; // deletes the member's account and data on our server
  openSignIn: (why?: string, mode?: 'join' | 'login') => void; // shows the Join / Log in sheet
  // Free account (picture 106, set 2, Oct 18, 2026)
  askAccount: (title: string, sub?: string) => void; // soft "free account" sheet for features that need one
  memberSince: string; // "Oct 2026"
  withGoogle: boolean;
  profile: { name: string; zip: string };
  updateProfile: (p: { name: string; zip: string }) => Promise<string | null>;
  prefs: AlertPrefs;
  setPref: (k: keyof AlertPrefs, v: boolean) => Promise<void>;
  changePassword: (pw: string) => Promise<string | null>;
  // Forgot password (picture 115 A, Oct 19, 2026): a 6-digit code by email, then a new password.
  sendResetCode: (email: string) => Promise<string | null>;
  checkResetCode: (email: string, code: string) => Promise<string | null>; // logs them in when the code is right
};
/** What a member wants to hear about. Kept with the account (Supabase user info), so it follows them to a new phone. */
export type AlertPrefs = { upkeep: boolean; price: boolean; nearby: boolean; rates: boolean; email: boolean };
const PREFS: AlertPrefs = { upkeep: true, price: true, nearby: false, rates: false, email: true };
const AuthCtx = createContext<Ctx | null>(null);

// Plain-word errors.
/** Sign-up or log-in needs the 6-digit code from the email first (picture 184 A, Nov 5, 2026). */
export const NEED_CODE = '__need_code__';
/** What sign-up gave back: logged in, needs the email code, or an error message. */
export function signUpOutcome(r: { data?: { session?: unknown; user?: unknown } | null; error?: { message: string } | null }): string | null {
  if (r.error) return friendly(r.error.message);
  if (r.data?.session) return null;
  return NEED_CODE; // email confirmation is on: the code is on its way
}

function friendly(msg: string) {
  if (/invalid login/i.test(msg)) return 'That email and password don’t match. Try again.';
  if (/already registered|already been registered/i.test(msg)) return 'That email already has an account. Tap “Log in” instead.';
  if (/password/i.test(msg) && /least|short|weak/i.test(msg)) return 'Use a password with at least 8 characters.';
  if (/email/i.test(msg) && /invalid/i.test(msg)) return 'That email doesn’t look right. Check it and try again.';
  if (/network|fetch/i.test(msg)) return 'Can’t reach Carvessa right now. Check your internet.';
  return 'Something went wrong. Please try again.';
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [ready, setReady] = useState(false);
  const [sheet, setSheet] = useState<{ why?: string; mode: 'join' | 'login' } | null>(null);
  const [gate, setGate] = useState<{ title: string; sub?: string } | null>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => setSession(data.session)).catch(() => {}).finally(() => setReady(true));
    const { data } = supabase.auth.onAuthStateChange((_e, s) => setSession(s));
    // Keep the login fresh only while the app is open.
    const sub = AppState.addEventListener('change', (st) => (st === 'active' ? supabase.auth.startAutoRefresh() : supabase.auth.stopAutoRefresh()));
    return () => { data.subscription.unsubscribe(); sub.remove(); };
  }, []);

  const signUp = useCallback(async (name: string, email: string, password: string) => {
    const r = await supabase.auth.signUp({ email: email.trim(), password, options: { data: { name: name.trim() } } }).catch((e) => ({ data: null, error: e as Error }));
    return signUpOutcome(r);
  }, []);
  const resendSignupCode = useCallback(async (email: string) => {
    const { error } = await supabase.auth.resend({ type: 'signup', email: email.trim() }).catch((e) => ({ error: e as Error }));
    if (!error) return null;
    if (/rate|seconds|too many/i.test(error.message)) return 'Please wait a minute, then ask for a new code.';
    if (/network|fetch/i.test(error.message)) return 'Can’t reach Carvessa right now. Check your internet and try again.';
    return null;
  }, []);
  const signIn = useCallback(async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({ email: email.trim(), password }).catch((e) => ({ error: e as Error }));
    // Made an account but never typed the code: send a new one and ask for it.
    if (error && /not confirmed/i.test(error.message)) { await resendSignupCode(email); return NEED_CODE; }
    return error ? friendly(error.message) : null;
  }, [resendSignupCode]);
  const confirmCode = useCallback(async (email: string, code: string) => {
    const { error } = await supabase.auth.verifyOtp({ email: email.trim(), token: code.trim(), type: 'signup' }).catch((e) => ({ error: e as Error }));
    if (!error) return null;
    if (/network|fetch/i.test(error.message)) return 'Can’t reach Carvessa right now. Check your internet and try again.';
    return 'That code didn’t work. Check the numbers, or ask for a new code.';
  }, []);
  // Google: open Google's page in a browser window; it sends the person back to the app with the login.
  const signInWithGoogle = useCallback(async () => {
    if (Platform.OS === 'web') return 'Google sign-in works in the phone app. Use email here.';
    const back = Linking.createURL('auth'); // carvessa://auth in the real app, exp://… in Expo Go
    const { data, error } = await supabase.auth.signInWithOAuth({ provider: 'google', options: { redirectTo: back, skipBrowserRedirect: true } }).catch((e) => ({ data: null, error: e as Error }));
    if (error || !data?.url) return friendly(error?.message ?? '');
    const res = await WebBrowser.openAuthSessionAsync(data.url, back).catch(() => null);
    if (!res || res.type !== 'success') return null; // closed by the person
    const p = new URLSearchParams(res.url.split('#')[1] ?? res.url.split('?')[1] ?? '');
    const access_token = p.get('access_token');
    const refresh_token = p.get('refresh_token');
    if (!access_token || !refresh_token) return 'Google didn’t finish signing you in. Please try again.';
    const { error: e2 } = await supabase.auth.setSession({ access_token, refresh_token });
    return e2 ? friendly(e2.message) : null;
  }, []);
  const signOut = useCallback(async () => { await supabase.auth.signOut().catch(() => {}); }, []);
  // Delete my account (Apple requires it). The database deletes only the logged-in member
  // (supabase/migrations/008_delete_my_account.sql); then we log out on this phone.
  const deleteAccount = useCallback(async () => {
    const { error } = await supabase.rpc('delete_my_account').then((r) => r, (e) => ({ error: e as Error }));
    if (error) return /network|fetch/i.test(error.message) ? 'Can’t reach Carvessa right now. Check your internet and try again.' : 'Couldn’t delete your account. Please try again, or email hello@carvessa.app.';
    await supabase.auth.signOut({ scope: 'local' }).catch(() => {});
    return null;
  }, []);
  const openSignIn = useCallback((why?: string, mode: 'join' | 'login' = 'join') => setSheet({ why, mode }), []);
  const askAccount = useCallback((title: string, sub?: string) => setGate({ title, sub }), []);
  const updateProfile = useCallback(async ({ name: n, zip }: { name: string; zip: string }) => {
    const { error } = await supabase.auth.updateUser({ data: { name: n.trim(), zip: zip.trim() } }).catch((e) => ({ error: e as Error }));
    return error ? friendly(error.message) : null;
  }, []);
  // We never say whether an email has an account: only "too many tries" and "no internet" come back as errors.
  const sendResetCode = useCallback(async (email: string) => {
    const { error } = await supabase.auth.resetPasswordForEmail(email.trim()).catch((e) => ({ error: e as Error }));
    if (!error) return null;
    if (/rate|seconds|too many/i.test(error.message)) return 'Please wait a minute, then ask for a new code.';
    if (/network|fetch/i.test(error.message)) return 'Can’t reach Carvessa right now. Check your internet and try again.';
    return null;
  }, []);
  const checkResetCode = useCallback(async (email: string, code: string) => {
    const { error } = await supabase.auth.verifyOtp({ email: email.trim(), token: code.trim(), type: 'recovery' }).catch((e) => ({ error: e as Error }));
    if (!error) return null;
    if (/network|fetch/i.test(error.message)) return 'Can’t reach Carvessa right now. Check your internet and try again.';
    return 'That code didn’t work. Check the numbers, or ask for a new code.';
  }, []);
  const changePassword = useCallback(async (pw: string) => {
    if (pw.length < 8) return 'Use a password with at least 8 characters.';
    const { error } = await supabase.auth.updateUser({ password: pw }).catch((e) => ({ error: e as Error }));
    return error ? friendly(error.message) : null;
  }, []);

  // First name only (Google gives the full name), so reviews don't show last names.
  const meta = session?.user.user_metadata as { name?: string; full_name?: string; zip?: string; alerts?: Partial<AlertPrefs> } | undefined;
  const name = ((meta?.name || meta?.full_name)?.trim().split(/\s+/)[0] || session?.user.email?.split('@')[0] || '').slice(0, 40);
  const created = session?.user.created_at;
  const memberSince = created ? new Date(created).toLocaleDateString('en-US', { month: 'short', year: 'numeric' }) : '';
  const withGoogle = session?.user.app_metadata?.provider === 'google';
  const zip = meta?.zip ?? '';
  const profile = useMemo(() => ({ name, zip }), [name, zip]);
  const alerts = meta?.alerts;
  const prefs = useMemo(() => ({ ...PREFS, ...alerts }), [alerts]);
  const setPref = useCallback(async (k: keyof AlertPrefs, v: boolean) => {
    await supabase.auth.updateUser({ data: { alerts: { ...prefs, [k]: v } } }).catch(() => {});
  }, [prefs]);
  const value = useMemo(() => ({ session, name, ready, signUp, signIn, signInWithGoogle, signOut, deleteAccount, openSignIn, askAccount, memberSince, withGoogle, profile, updateProfile, prefs, setPref, changePassword, sendResetCode, checkResetCode, confirmCode, resendSignupCode }),
    [session, name, ready, signUp, signIn, signInWithGoogle, signOut, deleteAccount, openSignIn, askAccount, memberSince, withGoogle, profile, updateProfile, prefs, setPref, changePassword, sendResetCode, checkResetCode, confirmCode, resendSignupCode]);
  return (
    <AuthCtx.Provider value={value}>
      {children}
      {sheet && <SignInSheet why={sheet.why} startMode={sheet.mode} onClose={() => setSheet(null)} />}
      {gate && !session && <AccountGate title={gate.title} sub={gate.sub} onClose={() => setGate(null)}
        onEmail={() => { setGate(null); setSheet({ why: gate.title, mode: 'join' }); }} />}
    </AuthCtx.Provider>
  );
}

export function useAuth() {
  const c = useContext(AuthCtx);
  if (!c) throw new Error('useAuth must be inside AuthProvider');
  return c;
}
