// Home "You can afford" card (Design 5, picture 200, Nov 6, 2026): for a monthly payment, how many of our
// cars fit, the best fit, and about how much car (out the door) that payment buys. All estimates:
// their credit and money down from the coach, else Good credit and $1,750 down, 72 months.
import { aprOf, MONTHS, TIERS } from '@/data/afford';
import { CARS, type Car, yearsOf } from '@/data/cars';
import { monthlyPayment } from '@/data/costs';
import { loanOf, monthlyPick } from '@/data/search-budget';
import { DOWN, type Answers } from '@/state/answers';

export const SLIDER_LO = 200;
export const SLIDER_HI = 800;
export const SLIDER_STEP = 25;
export const clampMonthly = (n: number) => Math.max(SLIDER_LO, Math.min(SLIDER_HI, Math.round(n / SLIDER_STEP) * SLIDER_STEP));

export type AffordFit = { car: Car; year: number; pay: number };
export type AffordCard = { count: number; total: number; best: AffordFit | null; more: AffordFit[]; maxOtd: number };

/** Cars that fit this monthly payment (newest year that fits), best-sellers first, then the payment closest to it. */
export function affordCard(a: Answers, monthly: number): AffordCard {
  const fits: { car: Car; year: number; pay: number }[] = [];
  for (const car of CARS) {
    const pick = monthlyPick(a, car, yearsOf(car), monthly);
    if (pick && !pick.over) fits.push({ car, year: pick.year, pay: pick.pay });
  }
  fits.sort((x, y) => Number(!!y.car.popular) - Number(!!x.car.popular) || y.pay - x.pay);
  const loan = loanOf(a);
  const t = TIERS.find((x) => x.tier === loan.credit) ?? TIERS[2];
  // Used-car rate unless they only want new (most of our shoppers buy used).
  const apr = aprOf(t, a.newUsed === 'New only');
  const perDollar = monthlyPayment(1000, apr, MONTHS) / 1000;
  const maxOtd = Math.round((monthly / perDollar + (DOWN[loan.down ?? ''] ?? 0)) / 500) * 500;
  // The next 3 that fit show as small cards under the best fit (Loudjier, Nov 8: 'a see all, not just one car').
  return { count: fits.length, total: CARS.length, best: fits[0] ?? null, more: fits.slice(1, 4), maxOtd };
}
