// "The car you have now" pop-up in the coach (picture 185, Nov 4, 2026): year, make and model on scroll
// wheels, miles (about), filled in from My Garage, and "Save to My Garage" so nobody types it twice.
import { useEffect, useState } from 'react';
import { ActivityIndicator, Modal, ScrollView, StyleSheet, View } from 'react-native';

import { BRANDS } from '@/components/car-picker';
import { KeyboardSheet } from '@/components/keyboard-sheet';
import { Label, tap } from '@/components/ui';
import { Wheel } from '@/components/wheel';
import { kindOfCar, type CarKind } from '@/data/car-kind';
import { CARS } from '@/data/cars';
import { modelsFor } from '@/data/gov';
import { thisYear } from '@/data/year';
import type { MyCar } from '@/state/saved';
import { C, F, themed } from '@/theme';
import { Pressable, Text, TextInput } from '@/components/t';

const YEARS = Array.from({ length: 25 }, (_, i) => String(thisYear() + 1 - i));
const long = (b: string) => (/^chevy$/i.test(b) ? 'Chevrolet' : /^vw$/i.test(b) ? 'Volkswagen' : b);
const short = (b: string) => (b === 'Chevrolet' ? 'Chevy' : b);
const brandOf = (make: string) => BRANDS.find((b) => b.toLowerCase() === long(make).toLowerCase()) ?? long(make);

export type CarNow = { year: number; make: string; model: string; miles?: number };

export function CarNowSheet({ garage, onUse, onClose }: {
  garage: MyCar[];
  onUse: (car: CarNow, kind: CarKind | undefined, save: boolean) => void;
  onClose: () => void;
}) {
  const first = garage[0];
  const [from, setFrom] = useState<number | null>(first ? 0 : null); // which garage car is filled in
  const [year, setYear] = useState(first ? String(first.year) : String(thisYear() - 6));
  const [brand, setBrand] = useState(first ? brandOf(first.make) : 'Chevrolet');
  const [model, setModel] = useState<string | null>(first?.model ?? null);
  const [miles, setMiles] = useState(first?.miles ? String(first.miles) : '');
  const [save, setSave] = useState(true);
  const [models, setModels] = useState<{ key: string; list: string[] } | null>(null);
  const [busy, setBusy] = useState(false);
  const key = `${brand}|${year}`;
  const brands = BRANDS.includes(brand) ? BRANDS : [brand, ...BRANDS];

  useEffect(() => {
    let on = true;
    const known = CARS.filter((c) => c.make === short(brand)).map((c) => c.model);
    modelsFor(brand, Number(year)).then((m) => (m.length ? m : known)).catch(() => known)
      .then((list) => { if (on) setModels({ key, list }); });
    return () => { on = false; };
  }, [key]); // eslint-disable-line react-hooks/exhaustive-deps

  const loading = models?.key !== key;
  let list = loading ? [] : models!.list;
  if (model && !loading && !list.some((m) => m.toLowerCase() === model.toLowerCase())) list = [model, ...list];
  // The model wheel starts on the first model when theirs isn't picked yet.
  const shown = model && list.includes(model) ? model : list[0] ?? null;

  const fill = (i: number) => {
    const c = garage[i];
    tap(); setFrom(i); setYear(String(c.year)); setBrand(brandOf(c.make)); setModel(c.model); setMiles(c.miles ? String(c.miles) : '');
  };
  const picked = from !== null ? garage[from] : undefined;
  const same = !!picked && String(picked.year) === year && brandOf(picked.make) === brand && picked.model === shown;
  const inGarage = same || garage.some((c) => String(c.year) === year && brandOf(c.make) === brand && c.model === shown);

  const use = async () => {
    if (!shown || busy) return;
    tap(); setBusy(true);
    const car: CarNow = { year: Number(year), make: short(brand), model: shown, miles: Number(miles.replace(/\D/g, '')) || undefined };
    // Find what kind of car it is; never wait more than 5 seconds (the coach asks anyway).
    const kind = await Promise.race([kindOfCar(car.year, car.make, car.model).catch(() => undefined), new Promise<undefined>((r) => setTimeout(() => r(undefined), 5000))]);
    setBusy(false);
    onUse(car, kind, save && !inGarage);
  };

  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <KeyboardSheet onClose={onClose} backStyle={s.back} sheetStyle={s.sheet}>
        <View style={s.grab} />
        <Text style={s.h} accessibilityRole="header">The car you have now</Text>
        <Text style={s.sub}>So we only show real step ups.</Text>
        {garage.length > 0 && (
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6 }} style={{ marginTop: 10, flexGrow: 0 }}>
            {garage.map((c, i) => (
              <Pressable key={`${c.year}${c.make}${c.model}${i}`} onPress={() => fill(i)} accessibilityRole="button" accessibilityState={{ selected: from === i && same }}
                style={[s.from, from === i && same && s.fromOn]}>
                <Text style={[s.fromT, from === i && same && { color: C.green }]}>{from === i && same ? '✓ ' : ''}From My Garage: {c.nick || `${c.year} ${c.model}`}</Text>
              </Pressable>
            ))}
          </ScrollView>
        )}
        <View style={s.labels}>
          <Label style={s.label}>Year</Label><Label style={s.label}>Make</Label><Label style={s.label}>Model</Label>
        </View>
        <View style={s.wheels}>
          <Wheel label="Year" items={YEARS} value={year} onChange={(v) => { setYear(v); setFrom(null); }} />
          <Wheel label="Make" items={brands} value={brand} onChange={(v) => { setBrand(v); setModel(null); setFrom(null); }} />
          {loading ? <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}><ActivityIndicator color={C.yellow} /></View>
            : list.length ? <Wheel label="Model" items={list} value={shown} onChange={(v) => { setModel(v); setFrom(null); }} />
              : <View style={{ flex: 1, justifyContent: 'center' }}><Text style={s.hint}>No list for this one. Close this and type it in the box.</Text></View>}
        </View>
        <Label style={[s.label, { marginTop: 12 }]}>Miles, about</Label>
        <TextInput value={miles} onChangeText={(v) => setMiles(v.replace(/\D/g, '').slice(0, 7))} placeholder="Like: 92000" placeholderTextColor="#8A93A3"
          keyboardType="number-pad" accessibilityLabel="Miles, about" style={s.input} />
        {!inGarage && (
          <Pressable onPress={() => { tap(); setSave(!save); }} accessibilityRole="checkbox" accessibilityState={{ checked: save }} style={s.ck}>
            <View style={[s.box, save && s.boxOn]}>{save ? <Text style={s.tick}>✓</Text> : null}</View>
            <Text style={s.ckT}>Save to My Garage</Text>
          </Pressable>
        )}
        <Pressable onPress={use} accessibilityRole="button" accessibilityState={{ disabled: !shown || busy }} style={[s.btn, (!shown || busy) && { opacity: 0.6 }]}>
          {busy ? <ActivityIndicator color={C.onAccent} /> : <Text style={s.btnT}>Use this car</Text>}
        </Pressable>
        <Text style={s.small}>Not sure of the miles? Leave it empty.</Text>
      </KeyboardSheet>
    </Modal>
  );
}

const s = themed(() => StyleSheet.create({
  back: { flex: 1, backgroundColor: 'rgba(15,26,42,0.45)' },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 26, borderTopRightRadius: 26, padding: 20, paddingBottom: 30 },
  grab: { alignSelf: 'center', width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, marginBottom: 14 },
  h: { fontFamily: F.head, fontSize: 21, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 14, color: C.muted, marginTop: 2 },
  from: { borderRadius: 12, paddingHorizontal: 12, paddingVertical: 9, backgroundColor: C.bg, borderWidth: 1, borderColor: C.line },
  fromOn: { backgroundColor: 'rgba(28,107,64,0.10)', borderColor: 'rgba(28,107,64,0.35)' },
  fromT: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.ink },
  labels: { flexDirection: 'row', marginTop: 14 },
  label: { flex: 1, textAlign: 'center', fontSize: 10.5, color: C.muted },
  wheels: { flexDirection: 'row', gap: 4, backgroundColor: C.bg, borderRadius: 16, padding: 4, marginTop: 4 },
  hint: { fontFamily: F.body, fontSize: 12.5, color: C.muted, textAlign: 'center' },
  input: { height: 50, borderRadius: 12, backgroundColor: C.bg, borderWidth: 1, borderColor: C.line, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink, marginTop: 4 },
  ck: { flexDirection: 'row', alignItems: 'center', gap: 10, marginTop: 12 },
  box: { width: 24, height: 24, borderRadius: 7, borderWidth: 2, borderColor: C.line, alignItems: 'center', justifyContent: 'center' },
  boxOn: { backgroundColor: C.fill, borderColor: C.fill },
  tick: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
  ckT: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  btn: { marginTop: 16, backgroundColor: C.fill, borderRadius: 14, height: 52, alignItems: 'center', justifyContent: 'center' },
  btnT: { fontFamily: F.bodyBold, fontSize: 16, color: C.onAccent },
  small: { fontFamily: F.body, fontSize: 12.5, color: C.muted, textAlign: 'center', marginTop: 8 },
}));
