// The full "About this car" guide for every car (picture 119 A, Loudjier Oct 20, 2026: "Build A").
// Text lives in guide-a/b/c.ts as [English, Spanish] pairs; the screen shows the English and our
// Text component translates it with GUIDE_ES (merged into the Spanish list in i18n/es.ts).
import { GUIDE_A } from '@/data/guide-a';
import { GUIDE_B } from '@/data/guide-b';
import { GUIDE_C } from '@/data/guide-c';
import type { Guide, Pair } from '@/data/guide-types';

export type { Guide, GuideIcon, Pair } from '@/data/guide-types';
export const GUIDE: Record<string, Guide> = { ...GUIDE_A, ...GUIDE_B, ...GUIDE_C };

// Words on the guide itself (headings, the questions every buyer should ask).
export const GUIDE_UI = {
  why: ['Why people buy it', 'Por qué la gente lo compra'],
  drive: ['What it’s like to drive', 'Cómo se siente al manejar'],
  right: ['Is it right for you?', '¿Es para ti?'],
  great: ['✓ Great if you…', '✓ Ideal si…'],
  skip: ['✕ Skip it if you…', '✕ No es para ti si…'],
  version: ['Which version to get', 'Qué versión escoger'],
  best: ['Best value', 'Mejor precio'],
  apps: ['If you drive for apps', 'Si manejas para apps'],
  years: ['Buying used: which years', 'Comprar usado: qué años'],
  yearsSub: ['What changed, in plain words', 'Qué cambió, en simple'],
  costs: ['What it costs to keep', 'Cuánto cuesta mantenerlo'],
  perMonth: ['Per month', 'Al mes'],
  gas: ['Gas, 12,000 miles a year', 'Gasolina, 12,000 millas al año'],
  charge: ['Charging, 12,000 miles a year', 'Carga eléctrica, 12,000 millas al año'],
  insurance: ['Insurance (varies a lot)', 'Seguro (cambia mucho)'],
  upkeep: ['Upkeep and repairs', 'Mantenimiento y reparaciones'],
  fullCost: ['See the full 5-year cost', 'Ver el costo de 5 años'],
  ask: ['Ask the dealer', 'Pregunta en el concesionario'],
  note: ['Carvessa’s notes in plain words, not the carmaker’s or a dealer’s. Trims and features change by year: check the exact car.', 'Notas de Carvessa en simple, no del fabricante ni del concesionario. Las versiones y equipos cambian por año: revisa el carro exacto.'],
} as const satisfies Record<string, Pair>;

// Asked about every car, after the questions for this car.
export const COMMON_ASK: Pair[] = [
  ['Which trim is it, exactly?', '¿Qué versión es, exactamente?'],
  ['Any open recalls, and were they fixed?', '¿Tiene llamados a revisión abiertos y ya los arreglaron?'],
  ['Can I see the service records?', '¿Puedo ver los registros de servicio?'],
  ['What’s the out-the-door price?', '¿Cuál es el precio final con todo incluido?'],
];

// English → Spanish for every guide line.
function collect(): Record<string, string> {
  const out: Record<string, string> = {};
  const add = (p: Pair) => { out[p[0]] = p[1]; };
  Object.values(GUIDE_UI).forEach(add);
  COMMON_ASK.forEach(add);
  for (const g of Object.values(GUIDE)) {
    g.why.forEach((w) => { add(w.title); add(w.text); });
    [g.drive, g.trimNote, ...g.greatIf, ...g.skipIf, ...g.ask].forEach(add);
    if (g.apps) add(g.apps);
    g.trims.forEach((t) => { add(t.text); out[t.name] = t.name; });
    g.years.forEach((y) => add(y.text));
  }
  return out;
}
export const GUIDE_ES = collect();
