// Tips about your car (picture 128 · Tips A, Oct 23, 2026): a small section under My car in the Garage.
// True facts only: "Did you know?" comes from our checked car guide; the monthly checks are general care
// that fits every car; "By your miles" uses the same general guide as What's due. No made-up numbers:
// the owner's manual has the final word.
import { carForMine } from '@/data/cars';
import { GUIDE } from '@/data/guide';
import { UPKEEP, milesUntil } from '@/data/upkeep';
import type { MyCar } from '@/state/saved';

export type Check = { icon: 'tire' | 'wiper' | 'battery' | 'cool' | 'light' | 'wrench'; title: string; text: string };

// Facts about this car: the note for its model years first, then why people buy it and how it drives.
export function factsFor(c: MyCar): string[] {
  const car = carForMine(c.make, c.model);
  const g = car && GUIDE[car.id];
  if (!g) return [];
  const inYears = g.years.filter((y) => {
    const m = y.years.match(/^(\d{4})(?:[–-](\d{4}))?$/);
    return m && c.year >= Number(m[1]) && c.year <= Number(m[2] ?? m[1]);
  });
  return [...inYears.map((y) => y.text[0]), ...g.why.map((w) => `${w.title[0]}: ${w.text[0]}`), g.drive[0]];
}

const COLD: Check = { icon: 'tire', title: 'Cold mornings lower tire pressure', text: 'About 1 PSI for every 10°F colder. Check before a morning drive.' };
const WIPERS: Check = { icon: 'wiper', title: 'Wipers and washer fluid', text: 'Streaks or squeaks mean new blades before the rain.' };
const BATTERY_COLD: Check = { icon: 'battery', title: 'Cold is hard on batteries', text: 'Slow to start? Most auto parts stores test batteries for free.' };
const LIGHTS: Check = { icon: 'light', title: 'Darker evenings', text: 'Walk around the car: headlights, brake lights and turn signals.' };
const TREAD: Check = { icon: 'tire', title: 'After winter: tire tread', text: 'Put a penny in the groove, Lincoln’s head down. If you see all of his head, it’s time for new tires.' };
const AC: Check = { icon: 'cool', title: 'Check the A/C before summer', text: 'Weak cold air is cheaper to fix early than in July.' };
const COOLANT: Check = { icon: 'cool', title: 'Heat: coolant level', text: 'Only check when the engine is cold. Never open a hot radiator cap.' };
const BATTERY_HOT: Check = { icon: 'battery', title: 'Heat is hard on batteries too', text: 'An older battery can quit on a hot day. Ask for a free test.' };
const HOT_CAR: Check = { icon: 'light', title: 'Never leave kids or pets inside', text: 'A parked car gets dangerously hot fast, even with a window cracked.' };

// Two checks for the month (0 = January).
export function checksFor(month: number): Check[] {
  if (month === 11 || month <= 1) return [COLD, BATTERY_COLD];
  if (month <= 3) return [TREAD, WIPERS];
  if (month === 4) return [AC, WIPERS];
  if (month <= 7) return [COOLANT, month === 6 ? HOT_CAR : BATTERY_HOT];
  if (month === 8) return [LIGHTS, WIPERS];
  return [COLD, WIPERS];
}

export const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

// Upkeep coming up within 1,500 miles, plus the yearly battery check on a car 3+ years old.
export function byMiles(c: MyCar, thisYear: number): Check[] {
  let out: Check[] = [];
  for (const u of UPKEEP) {
    // The last oil change from their service history beats our every-6,000 guess (same rule as My car's "what's due").
    const n = u.what === 'Oil change' && c.miles && c.lastOil && c.lastOil <= c.miles ? Math.max(0, c.lastOil + u.every - c.miles) : milesUntil(c.miles, u.every);
    if (n !== null && n <= 1500) out.push({ icon: 'wrench', title: `${u.what} soon`, text: `${u.note}. Your owner’s manual has the exact schedule.` });
  }
  out = out.slice(0, 2);
  if (thisYear - c.year >= 3) out.push({ icon: 'battery', title: 'Yearly battery check', text: 'Batteries often last about 3 to 5 years. A test is quick and usually free.' });
  return out;
}
