// Phone reminders made on the phone itself (no server, no push token): car payments, the monthly
// "Is your mileage about …?" check and "Oil change coming up" (My car plan, Oct 30, 2026).
// Each time the cars change we cancel ours (ids start with "plan-") and set the next few again.
// All at 8–9 AM, never in quiet hours (9 PM–8 AM).
import * as Notifications from 'expo-notifications';
import { Platform } from 'react-native';

import { dayName, daysToMiles, estMiles, nextDue, nextMilesCheck, payoffDate, shortDate } from '@/data/car-plan';
import { alertAt, remDue, remName } from '@/data/car-reminders';
import { carName } from '@/data/my-cars';
import { milesUntil } from '@/data/upkeep';
import { tr } from '@/i18n';
import type { MyCar } from '@/state/saved';

export const CHANNEL = 'reminders';
const usd = (n: number) => `$${Math.round(n).toLocaleString('en-US')}`;

export type Planned = { id: string; at: Date; title: string; body: string; data: Record<string, unknown> };

// What we would set for these cars (pure, so it can be tested).
export function plan(cars: MyCar[], now: Date, opts: { upkeep: boolean }): Planned[] {
  const out: Planned[] = [];
  const at = (d: Date, h: number, m = 0) => new Date(d.getFullYear(), d.getMonth(), d.getDate(), h, m);
  cars.forEach((c, i) => {
    const name = carName(c);
    const data = { mine: true, year: c.year, make: c.make, model: c.model };
    const L = c.loan;
    if (L?.remind && L.left > 0 && L.payment > 0) {
      let from = now;
      for (let k = 0; k < 2; k++) {
        const due = nextDue(L, from);
        const who = L.lender ? ` to ${L.lender}` : '';
        const before = at(new Date(due.getFullYear(), due.getMonth(), due.getDate() - 3), 9);
        if (before > now) out.push({ id: `plan-pay-${i}-${k}-a`, at: before, data: { ...data, screen: 'loan' },
          title: L.autopay ? `Autopay goes out ${dayName(due)}` : `Car payment due ${dayName(due)}`,
          body: `${usd(L.payment)}${who} on ${shortDate(due)} · ${name}` });
        const day = at(due, 8);
        if (day > now && !L.autopay) out.push({ id: `plan-pay-${i}-${k}-b`, at: day, data: { ...data, screen: 'loan' },
          title: 'Car payment due today', body: `${usd(L.payment)}${who} · ${name}` });
        from = new Date(due.getFullYear(), due.getMonth(), due.getDate() + 1);
      }
    }
    const t = now.getTime();
    const m = estMiles(c, t);
    if (c.checkMiles !== false && m) {
      const when = nextMilesCheck(now);
      const then = Math.round((estMiles(c, when.getTime()) ?? m) / 100) * 100;
      out.push({ id: `plan-miles-${i}`, at: when, data: { ...data, screen: 'miles' },
        title: `Quick check on your ${c.model}`, body: `Is your mileage about ${then.toLocaleString('en-US')}? Tap to check.` });
    }
    // Lease ends in about 3 months: time to decide (return it, buy it, or trade up).
    if (L?.kind === 'lease' && L.left > 0) {
      const end = payoffDate(L, now);
      const heads = new Date(end.getFullYear(), end.getMonth() - 3, end.getDate(), 10);
      if (heads > now) out.push({ id: `plan-lease-${i}`, at: heads, data: { ...data, screen: 'loan' },
        title: 'Your lease ends in about 3 months', body: `Time to decide on your ${c.model}: return it, buy it, or trade up.` });
    }
    // Pickup day (the insurance step): 9 AM on the day they said they buy the car, until they mark it insured.
    const b = c.boughtOn?.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (b && !c.insured && c.insureRemind !== false) {
      const day = new Date(Number(b[3]), Number(b[1]) - 1, Number(b[2]), 9);
      if (day > now) out.push({ id: `plan-insure-${i}`, at: day, data: { ...data, screen: 'insure' },
        title: 'Insure your car before you drive it home', body: `Your ${c.model}'s details are ready in Carvessa: VIN, miles and lender.` });
    }
    // Value check every 3 months: the first Saturday of Jan, Apr, Jul and Oct, 10 AM.
    if (c.valueTips !== false && m) {
      const q = new Date(now.getFullYear(), Math.floor(now.getMonth() / 3) * 3 + 3, 1, 10);
      while (q.getDay() !== 6) q.setDate(q.getDate() + 1);
      out.push({ id: `plan-value-${i}`, at: q, data: { ...data, screen: 'value' },
        title: `What’s your ${c.model} worth now?`, body: 'See your new value estimate and what you’d have after your loan.' });
    }
    // Their own reminders (picture 221 A): insurance, car payment, tag renewal, car wash… each at the time they picked.
    for (const r of c.reminders ?? []) {
      const when = alertAt(r, now.getTime());
      if (!when) continue;
      const due = new Date(remDue(r, now.getTime()));
      const days = Math.round((due.getTime() - new Date(when.getFullYear(), when.getMonth(), when.getDate(), 12).getTime()) / 86400000);
      const name = tr(remName(r));
      const money = r.amount ? `${usd(r.amount)} · ` : '';
      out.push({ id: `plan-rem-${i}-${r.id}`, at: when, data: { ...data, screen: 'reminders' },
        title: days <= 0 ? `${name}: today` : days === 1 ? `${name}: tomorrow` : `${name} in ${days} days`,
        body: `${money}${shortDate(due)} · ${c.model}` });
    }
    if (opts.upkeep && m) {
      // Oil on its own (a cabin filter coming up first must not hide it): their last oil change, else every ~6,000 miles.
      const left = c.lastOil && c.lastOil <= m ? c.lastOil + 6000 - m : milesUntil(m, 6000);
      const days = left !== null && left > 300 ? daysToMiles(c, m + left - 300, t) : null;
      if (days !== null && days > 0 && days <= 120) out.push({ id: `plan-oil-${i}`, at: at(new Date(t + days * 86400000), 9), data: { ...data },
        title: 'Oil change coming up', body: `Your ${c.model} is about 300 miles from its next oil change (estimate).` });
    }
  });
  return out;
}

export async function canRemind(ask: boolean): Promise<boolean> {
  if (Platform.OS === 'web') return false;
  try {
    if (Platform.OS === 'android') await Notifications.setNotificationChannelAsync(CHANNEL, { name: 'Reminders', importance: Notifications.AndroidImportance.DEFAULT });
    let { status } = await Notifications.getPermissionsAsync();
    if (status !== 'granted' && ask) status = (await Notifications.requestPermissionsAsync()).status;
    return status === 'granted';
  } catch {
    return false;
  }
}

export async function syncReminders(cars: MyCar[], opts: { upkeep: boolean; allowed: boolean }) {
  if (Platform.OS === 'web') return;
  try {
    const old = await Notifications.getAllScheduledNotificationsAsync();
    for (const n of old) if (n.identifier.startsWith('plan-')) await Notifications.cancelScheduledNotificationAsync(n.identifier);
    if (!opts.allowed || !(await canRemind(false))) return;
    for (const p of plan(cars, new Date(), opts)) {
      await Notifications.scheduleNotificationAsync({
        identifier: p.id,
        content: { title: tr(p.title), body: tr(p.body), data: p.data },
        trigger: { type: Notifications.SchedulableTriggerInputTypes.DATE, date: p.at, channelId: CHANNEL },
      });
    }
  } catch {
    // An older test app without notifications: reminders just don't show.
  }
}
