// Android runs this (without opening the app) when a Carvessa widget is added, resized, refreshed
// (every 30 minutes at most, Android's rule) or tapped on 'Another tip' / 'N of M cars'.
import type { WidgetTaskHandlerProps } from 'react-native-android-widget';

import { getWeather, skyWord } from '@/data/weather';
import { applyLang } from '@/i18n';
import { GARAGE_KEY, readNum, readSnap, TIP_KEY, weatherTip, writeNum, writeSnap, type WidgetSnap } from './data';
import { readPark, readTrips, readWeek, tickWeek, writeWeek } from './more';
import { bothLooks, plainCard, type Extra } from './widgets';

const HOUR = 60 * 60 * 1000;
/** Days since 1970 on the phone's clock, so the tip changes each morning. */
export const dayNumber = (now = new Date()) => Math.floor((now.getTime() - now.getTimezoneOffset() * 60_000) / 86_400_000);

/** The weather widget refreshes its own weather once an hour (free weather.gov, no key). */
export async function freshWeather(s: WidgetSnap, now = Date.now()): Promise<WidgetSnap> {
  if (!s.spot || (s.weather && now - s.weather.at < HOUR)) return s;
  try {
    const w = await getWeather(s.spot.lat, s.spot.lon, 30);
    const short = s.cars.length ? s.cars[Math.min(s.active, s.cars.length - 1)].short : 'car';
    const next = { ...s, weather: { tempF: w.tempF, sky: w.sky, isDay: w.isDay, word: skyWord(w.sky, !w.isDay), at: now, tip: weatherTip(w.tempF, w.sky, short) } };
    await writeSnap(next);
    return next;
  } catch {
    return s;
  }
}

export async function widgetTaskHandler({ widgetInfo, widgetAction, clickAction, renderWidget }: WidgetTaskHandlerProps) {
  if (widgetAction === 'WIDGET_DELETED') return;
  const name = widgetInfo.widgetName;
  // A plain card right away, so the widget is never an empty box while we get its data.
  if (widgetAction === 'WIDGET_ADDED') {
    try { renderWidget(plainCard('Carvessa', 'Loading your car…')); } catch { /* the full drawing below */ }
  }
  try {
    let s = await readSnap();
    if (s) applyLang(s.lang);
    if (s && (name === 'Weather' || name === 'DriveAlert' || name === 'Health')) s = await withTimeout(freshWeather(s), 8000, s);
    let pick = 0;
    if (name === 'Tip' || name === 'Garage') {
      const key = name === 'Tip' ? TIP_KEY : GARAGE_KEY;
      pick = await readNum(key);
      if (widgetAction === 'WIDGET_CLICK' && (clickAction === 'NEXT_TIP' || clickAction === 'NEXT_CAR')) {
        pick += 1;
        await writeNum(key, pick);
      }
    }
    const now = Date.now();
    let week = await readWeek(now);
    const tick = widgetAction === 'WIDGET_CLICK' && clickAction?.match(/^TICK_(\d)$/);
    if (tick) { week = tickWeek(week, Number(tick[1]), now); await writeWeek(week); }
    const x: Extra = { now, week, park: await readPark(), trips: await readTrips() };
    renderWidget(bothLooks(name, s, pick, dayNumber(), { w: widgetInfo.width, h: widgetInfo.height }, x));
  } catch (e) {
    renderWidget(plainCard('Carvessa', 'Open Carvessa, then come back.', `Widget error: ${String((e as Error)?.message ?? e).slice(0, 120)}`));
  }
}

/** The task has 30 seconds in all (Android), so slow internet never stops the drawing. */
export function withTimeout<T>(p: Promise<T>, ms: number, fallback: T): Promise<T> {
  return new Promise((resolve) => {
    const t = setTimeout(() => resolve(fallback), ms);
    p.then((v) => { clearTimeout(t); resolve(v); }, () => { clearTimeout(t); resolve(fallback); });
  });
}
