// Add or edit one of your cars (picture 128 A, Oct 23, 2026): year, make, model, miles, nickname, color,
// Save, and "Delete this car" with one more tap so nobody deletes a car by accident.
import { useState } from 'react';
import { Modal, StyleSheet, View } from 'react-native';

import { paintsFor } from '@/components/car-photo';
import { carKey, useCarPhoto } from '@/state/car-photos';
import { Label, tap } from '@/components/ui';
import { carForMine } from '@/data/cars';
import { carName } from '@/data/my-cars';
import type { MyCar } from '@/state/saved';
import { C, F, themed } from '@/theme';
import { KeyboardSheet } from '@/components/keyboard-sheet';
import { Pressable, Text, TextInput } from '@/components/t';

function Field({ label, value, onChange, placeholder, numeric }: { label: string; value: string; onChange: (v: string) => void; placeholder: string; numeric?: boolean }) {
  return (
    <View style={{ flex: 1 }}>
      <Label style={s.label}>{label}</Label>
      <TextInput value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor="#8A93A3" accessibilityLabel={label}
        keyboardType={numeric ? 'number-pad' : 'default'} style={s.input} autoCorrect={false} />
    </View>
  );
}

// car = the car to edit; no car = add a new one. start = prefill for a new car (e.g. from the coach chat).
export function CarSheet({ car, start, onSave, onDelete, onClose }: {
  car?: MyCar; start?: Partial<MyCar>; onSave: (c: MyCar) => void; onDelete?: () => void; onClose: () => void;
}) {
  const from = car ?? start;
  const [year, setYear] = useState(from?.year ? String(from.year) : '');
  const [make, setMake] = useState(from?.make ?? '');
  const [model, setModel] = useState(from?.model ?? '');
  const [miles, setMiles] = useState(from?.miles ? String(from.miles) : '');
  const [nick, setNick] = useState(car?.nick ?? '');
  const [color, setColor] = useState(car?.color);
  const [sure, setSure] = useState(false);
  const ok = /^(19|20)\d\d$/.test(year) && !!make.trim() && !!model.trim();
  const id = ok ? carForMine(make.trim(), model.trim())?.id : undefined;
  // No color dots when this car has their own photo: the photo shows the real color (Loudjier, Nov 18, 2026).
  const ownPhoto = useCarPhoto(car ? carKey(car) : null);
  const paints = id && !ownPhoto ? paintsFor(id, Number(year)) : [];

  const save = () => {
    if (!ok) return;
    tap();
    const m = Number(miles.replace(/\D/g, '')) || undefined;
    const same = car && car.year === Number(year) && car.make === make.trim() && car.model === model.trim();
    onSave({
      // A different car keeps nothing car-specific (dealer, color, dates) except what's typed here.
      ...(same ? car : {}),
      year: Number(year), make: make.trim(), model: model.trim(), miles: m,
      nick: nick.trim() || undefined,
      color: paints.some((p) => p.name === color) && color !== paints[0]?.name ? color : undefined,
    });
  };

  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <KeyboardSheet onClose={onClose} backStyle={s.back} sheetStyle={s.sheet}>
          <View style={s.grab} />
          <>
            {sure && car ? (
              <View style={s.confirm}>
                <Text style={s.confirmH}>Delete your {carName(car)}?</Text>
                <Text style={s.confirmT}>Its miles, oil and tag reminders and your dealer go away. Recalls for it stop. You can add it again later.</Text>
                <View style={{ gap: 9, marginTop: 14 }}>
                  <Pressable onPress={() => { tap(); setSure(false); onClose(); }} accessibilityRole="button" style={[s.btn, s.keepDark]}><Text style={s.keepDarkT}>Keep it</Text></Pressable>
                  <Pressable onPress={() => { tap(); setSure(false); }} accessibilityRole="button" style={[s.btn, s.editBtn]}><Text style={s.editT}>✎ Edit this car instead</Text></Pressable>
                  <Pressable onPress={() => { tap(); onDelete?.(); }} accessibilityRole="button" style={[s.btn, s.delOutline]}><Text style={s.delOutlineT}>Delete</Text></Pressable>
                </View>
              </View>
            ) : (<>
              <Text style={s.h} accessibilityRole="header">{car ? 'Edit your car' : 'Add a car'}</Text>
              <View style={s.row}>
                <Field label="Year" value={year} onChange={(v) => setYear(v.replace(/\D/g, '').slice(0, 4))} placeholder="2020" numeric />
                <Field label="Make" value={make} onChange={setMake} placeholder="Chevy" />
              </View>
              <View style={s.row}>
                <Field label="Model" value={model} onChange={setModel} placeholder="Trax" />
                <Field label="Miles (about)" value={miles} onChange={(v) => setMiles(v.replace(/\D/g, '').slice(0, 7))} placeholder="45000" numeric />
              </View>
              <View style={s.row}>
                <Field label="Nickname (optional)" value={nick} onChange={(v) => setNick(v.slice(0, 24))} placeholder="Like: My car, Mom’s car, Work truck" />
              </View>
              {paints.length > 0 && (<>
                <Label style={[s.label, { marginTop: 12 }]}>Color</Label>
                <View style={s.dots} accessibilityRole="radiogroup">
                  {paints.map((p, i) => {
                    const on = (color ?? paints[0].name) === p.name;
                    return (
                      <Pressable key={p.name} onPress={() => { tap(); setColor(i === 0 ? undefined : p.name); }} accessibilityRole="radio" accessibilityState={{ checked: on }}
                        accessibilityLabel={p.name} hitSlop={4} style={[s.dotRing, on && { borderColor: C.yellow }]}>
                        <View style={[s.dot, { backgroundColor: p.hex }]} />
                      </Pressable>
                    );
                  })}
                </View>
              </>)}
              <Pressable onPress={save} accessibilityRole="button" accessibilityState={{ disabled: !ok }} style={[s.save, !ok && { opacity: 0.5 }]}>
                <Text style={s.saveT}>{car ? 'Save' : 'Add this car'}</Text>
              </Pressable>
              {car && onDelete ? (
                <Pressable onPress={() => { tap(); setSure(true); }} accessibilityRole="button" style={{ alignSelf: 'center', padding: 12 }}>
                  <Text style={s.delLink}>Delete this car</Text>
                </Pressable>
              ) : (
                <Pressable onPress={onClose} accessibilityRole="button" style={{ alignSelf: 'center', padding: 12 }}>
                  <Text style={s.cancel}>Cancel</Text>
                </Pressable>
              )}
            </>)}
          </>
      </KeyboardSheet>
    </Modal>
  );
}

const s = themed(() => StyleSheet.create({
  back: { flex: 1, backgroundColor: 'rgba(15,26,42,0.45)' },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 26, borderTopRightRadius: 26, padding: 20, paddingBottom: 30 },
  grab: { alignSelf: 'center', width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, marginBottom: 14 },
  h: { fontFamily: F.head, fontSize: 21, color: C.ink },
  row: { flexDirection: 'row', gap: 8, marginTop: 12 },
  label: { fontSize: 10.5, color: C.muted, marginBottom: 4 },
  input: { height: 50, borderRadius: 12, backgroundColor: C.bg, borderWidth: 1, borderColor: C.line, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink },
  dots: { flexDirection: 'row', flexWrap: 'wrap', gap: 6 },
  dotRing: { width: 40, height: 40, borderRadius: 20, borderWidth: 2.5, borderColor: 'transparent', alignItems: 'center', justifyContent: 'center' },
  dot: { width: 28, height: 28, borderRadius: 14, borderWidth: 1, borderColor: 'rgba(15,26,42,0.18)' },
  save: { marginTop: 18, backgroundColor: C.fill, borderRadius: 14, height: 50, alignItems: 'center', justifyContent: 'center' },
  saveT: { fontFamily: F.bodyBold, fontSize: 16, color: C.onAccent },
  delLink: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.red },
  cancel: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.muted },
  confirm: { paddingTop: 4 },
  keepDark: { backgroundColor: C.ink },
  keepDarkT: { fontFamily: F.bodyBold, fontSize: 16, color: C.bg },
  editBtn: { backgroundColor: C.card, borderWidth: 1.5, borderColor: C.line },
  editT: { fontFamily: F.bodyBold, fontSize: 16, color: C.ink },
  delOutline: { backgroundColor: 'transparent', borderWidth: 1.5, borderColor: C.red },
  delOutlineT: { fontFamily: F.bodyBold, fontSize: 16, color: C.red },
  confirmH: { fontFamily: F.head, fontSize: 21, color: C.ink, textAlign: 'center' },
  confirmT: { fontFamily: F.body, fontSize: 14, lineHeight: 20, color: C.muted, marginTop: 6, textAlign: 'center' },
  btn: { flex: 1, height: 48, borderRadius: 14, alignItems: 'center', justifyContent: 'center' },
  keep: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line },
  keepT: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  del: { backgroundColor: '#B3412F' },
  delT: { fontFamily: F.bodyBold, fontSize: 15, color: '#FFFFFF' },
}));
