// One car in a list: photo, name, price, and a heart to save it.
import { router } from 'expo-router';
import { StyleSheet, View } from 'react-native';

import { CarPhoto, CarThumb } from '@/components/car-photo';
import { HeartIcon } from '@/components/icons';
import { Body, H, Label, tap } from '@/components/ui';
import { Car, carName } from '@/data/cars';
import { priceFor, priceLine } from '@/data/prices';
import { useSaved } from '@/state/saved';
import { useSaveToggle } from '@/state/save-gate';
import { calm, C, themed } from '@/theme';
import { Pressable } from '@/components/t';

export function SaveHeart({ id, year }: { id: string; year: number }) {
  const { isSaved } = useSaved();
  const saveToggle = useSaveToggle();
  const on = isSaved(id, year);
  return (
    <Pressable onPress={() => { tap(); saveToggle(id, year); }} hitSlop={10} accessibilityRole="button"
      accessibilityLabel={on ? 'Remove from saved cars' : 'Save this car'} accessibilityState={{ selected: on }}
      style={[s.heart, on && { backgroundColor: C.accentSoft, borderColor: C.yellow }]}>
      <HeartIcon size={18} color={C.ink} />
    </Pressable>
  );
}

// tag: a small colored label under the price, like "1 recall" or "No recalls". line: replaces the price line
// (Search › Monthly shows the payment estimate there).
export function CarCard({ car, year, note, tag, line }: { car: Car; year: number; note?: string; tag?: { text: string; bad?: boolean }; line?: string }) {
  const name = carName(car, year);
  const open = () => { tap(); router.push({ pathname: '/car/[id]', params: { id: car.id, year: String(year) } }); };
  return (
    <Pressable onPress={open} accessibilityRole="button" accessibilityLabel={name} style={({ pressed }) => [s.card, pressed && { opacity: 0.85 }]}>
      {calm ? <CarThumb id={car.id} year={year} label={name} width={92} height={64} /> : <CarPhoto id={car.id} label={name} style={s.photo} />}
      <View style={{ flex: 1 }}>
        <Label style={{ fontSize: 10.5, color: C.muted }}>{note ?? `${car.body}${car.green === 'ev' ? ' · Electric' : car.green === 'hybrid' ? ' · Hybrid' : ''}`}</Label>
        <H size={18} style={{ marginTop: 1 }}>{name}</H>
        <Body bold style={{ fontSize: 13, marginTop: 2 }}>{line ?? priceLine(priceFor(car, year))}</Body>
        {!!tag && (
          <View style={[s.tag, { backgroundColor: tag.bad ? C.red : C.goodBg }]}>
            <Body bold style={{ fontSize: 11.5, color: tag.bad ? '#FFFFFF' : C.goodInk }}>{tag.text}</Body>
          </View>
        )}
      </View>
      <SaveHeart id={car.id} year={year} />
    </Pressable>
  );
}

const s = themed(() => StyleSheet.create({
  card: calm
    ? { flexDirection: 'row', gap: 10, alignItems: 'center', borderRadius: 22, padding: 9, marginBottom: 8, backgroundColor: C.card, shadowColor: '#1F6E4E', shadowOpacity: 0.08, shadowRadius: 12, shadowOffset: { width: 0, height: 5 }, elevation: 2 }
    : { flexDirection: 'row', gap: 10, alignItems: 'center', borderWidth: 1, borderColor: C.line, borderRadius: 12, padding: 8, marginBottom: 8, backgroundColor: C.bg },
  photo: { width: 96, height: 66 },
  tag: { alignSelf: 'flex-start', borderRadius: 10, paddingHorizontal: 8, paddingVertical: 2, marginTop: 4 },
  heart: { width: 38, height: 38, borderWidth: 1, borderColor: C.line, borderRadius: calm ? 19 : 12, alignItems: 'center', justifyContent: 'center', alignSelf: 'flex-start' },
}));
