// Weather for the Home city scene, from the US National Weather Service
// (api.weather.gov): free, no key, OK for business use, US only.
// NWS asks every app to say who it is and how to reach it, so we send our
// contact email in the User-Agent. (Web browsers ignore this header and send their own.)
import { onPullClear } from '@/lib/refresh';

export type Sky = 'clear' | 'partly' | 'cloudy' | 'rain' | 'storm' | 'snow' | 'fog';
export type Weather = { sky: Sky; isDay: boolean; tempF: number; text: string };

const NWS_HEADERS: Record<string, string> = {
  Accept: 'application/geo+json',
  'User-Agent': 'Carvessa/0.1 (https://carvessa.app, hello@carvessa.app)',
};

async function getJson(url: string) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 20000);
  try {
    const r = await fetch(url, { headers: NWS_HEADERS, signal: ctrl.signal });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return await r.json();
  } finally {
    clearTimeout(t);
  }
}

// Turns the NWS words ("Chance Light Rain", "Mostly Sunny") into one of our scenes.
export function skyFrom(text: string): Sky {
  const s = text.toLowerCase();
  // "Chance T-storms" is a maybe: show rain, not lightning (Nov 4, 2026: it said Storms while it only rained).
  if (/thunder|t-storm|storm/.test(s) && !/chance/.test(s)) return 'storm';
  if (/snow|sleet|flurr|ice|blizzard/.test(s)) return 'snow';
  if (/rain|shower|drizzle/.test(s)) return 'rain';
  if (/fog|haze|smoke|mist/.test(s)) return 'fog';
  if (/cloud|overcast/.test(s) && !/mostly sunny|mostly clear|partly/.test(s)) return 'cloudy';
  if (/partly|mostly sunny|mostly clear|few clouds/.test(s)) return 'partly';
  return 'clear';
}

export function parseHourly(j: any): Weather {
  const p = j?.properties?.periods?.[0];
  if (!p) throw new Error('No forecast');
  const text = String(p.shortForecast ?? '');
  return { sky: skyFrom(text), isDay: !!p.isDaytime, tempF: Number(p.temperature), text };
}

/** What the weather station sees RIGHT NOW (Nov 4, 2026, Loudjier: "it's cloudy and raining" while the
 * forecast said storms). Old (over 90 min) or empty reports don't count. Temperature comes in °C. */
export function parseObservation(j: any, now = Date.now()): { sky: Sky; tempF: number; text: string } | null {
  const p = j?.properties;
  const text = String(p?.textDescription ?? '').trim();
  const at = Date.parse(p?.timestamp ?? '');
  if (!text || !Number.isFinite(at) || now - at > 90 * 60 * 1000) return null;
  const c = p?.temperature?.value;
  return { sky: skyFrom(text), tempF: typeof c === 'number' ? Math.round(c * 9 / 5 + 32) : NaN, text };
}

// Where to ask for the hourly forecast and the closest station rarely changes, so we keep them per spot.
const gridUrl = new Map<string, { hourly: string; stations?: string }>();
let last: { key: string; at: number; w: Weather } | null = null;
onPullClear(() => { last = null; });

/** Plain words for the sky chip on Home ("72° · Sunny"). Ours, so they translate. */
export function skyWord(sky: Sky, night: boolean): string {
  return { clear: night ? 'Clear skies' : 'Sunny', partly: 'Partly cloudy', cloudy: 'Cloudy', rain: 'Rain', storm: 'Storms', snow: 'Snow', fog: 'Fog' }[sky];
}

/** maxAgeMin: how old a saved answer may be (Oct 26, 2026: opening the app checks again after 10 minutes). */
export async function getWeather(lat: number, lon: number, maxAgeMin = 15): Promise<Weather> {
  const key = `${lat.toFixed(2)},${lon.toFixed(2)}`;
  if (last && last.key === key && Date.now() - last.at < maxAgeMin * 60 * 1000) return last.w;
  let urls = gridUrl.get(key);
  if (!urls) {
    const pt = await getJson(`https://api.weather.gov/points/${key}`);
    const hourly = pt?.properties?.forecastHourly as string;
    if (!hourly) throw new Error('Outside the US');
    urls = { hourly, stations: pt?.properties?.observationStations as string | undefined };
    gridUrl.set(key, urls);
  }
  // The forecast says day or night; the closest station says what the sky is doing now.
  const [fc, obs] = await Promise.all([
    getJson(urls.hourly).then(parseHourly),
    nowAt(urls.stations).catch(() => null),
  ]);
  const w: Weather = obs ? { ...fc, sky: obs.sky, text: obs.text, tempF: Number.isFinite(obs.tempF) ? obs.tempF : fc.tempF } : fc;
  last = { key, at: Date.now(), w };
  return w;
}

const stationOf = new Map<string, string>();
async function nowAt(stations?: string) {
  if (!stations) return null;
  let id = stationOf.get(stations);
  if (!id) {
    const j = await getJson(stations);
    id = j?.features?.[0]?.properties?.stationIdentifier as string;
    if (!id) return null;
    stationOf.set(stations, id);
  }
  return parseObservation(await getJson(`https://api.weather.gov/stations/${id}/observations/latest`));
}

// When we can't get the weather (offline, outside the US), show a clear sky
// that follows the phone's clock.
export function fallbackWeather(now = new Date()): Weather {
  const h = now.getHours();
  return { sky: 'clear', isDay: h >= 7 && h < 19, tempF: NaN, text: '' };
}
