// Search: every car, with easy filter chips. Each car shows the newest year that fits the price filter.
// Picture 122 A (Oct 21, 2026): a "Price | Monthly" switch; Monthly ranks by our payment estimate.
// Versions (trims) from the car guide count in the search words ("RAV4 XLE").
import { PreLink } from '@/components/plan-cards';
import { router, useLocalSearchParams } from 'expo-router';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { FlatList, Modal, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Circle, Path } from 'react-native-svg';

import { BodyGrid, carIsKind, KINDS, type Kind } from '@/components/body-tiles';
import { BrandMore, brandOf, dataMake, useBrandModels } from '@/components/brand-more';
import { BigCard, CompareBar } from '@/components/big-card';
import { FilterBar } from '@/components/filters';
import { carOk, NO_FILTERS, yearOk, type Filters } from '@/data/filters';
import { SmartFinder } from '@/components/smart-finder';
import { VMark } from '@/components/brand';
import { Body, Chip, H, Label, tap } from '@/components/ui';
import { CARS, Car, yearsOf } from '@/data/cars';
import { money, priceFor } from '@/data/prices';
import { CREDIT_CHOICES, DOWN_CHOICES, loanOf, MONTHLY_CHIPS, monthlyPick } from '@/data/search-budget';
import { costsFor, stateFromZip } from '@/data/state-costs';
import { trimNames, trimParts } from '@/data/trims';
import { DOWN, useAnswers } from '@/state/answers';
import { UseMyLocation } from '@/components/use-location';
import { canScan } from '@/lib/scan';
import { calm, C, F, PAD, themed, skyLook } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text, TextInput } from '@/components/t';
import { usePullRefresh } from '@/components/pull-refresh';
import { MapIcon } from '@/components/icons';

const PRICES: [string, number][] = [['Under $15K', 15000], ['Under $25K', 25000], ['Under $40K', 40000], ['Under $60K', 60000]];
const MORE = ['New only', 'Third row', 'AWD / 4x4'];
// Kinds of car we have at least one car for (picture 68 B tiles).
const HAVE = KINDS.map((k) => k.kind).filter((k) => CARS.some((c) => carIsKind(c, k)));

export default function Search() {
  const pull = usePullRefresh();
  const [q, setQ] = useState('');
  const [type, setType] = useState<Kind | null>(null);
  // Home's "Shop by type" tiles open Search with a kind already picked.
  // Home's "Shop by brand" chips open it with the brand typed in (q).
  const { kind, q: qp, monthly: mp } = useLocalSearchParams<{ kind?: string; q?: string; monthly?: string }>();
  const [seenKind, setSeenKind] = useState<string | undefined>(undefined);
  if (kind !== seenKind) { setSeenKind(kind); if (kind && HAVE.includes(kind as Kind)) setType(kind as Kind); }
  const [seenQ, setSeenQ] = useState<string | undefined>(undefined);
  if (qp !== seenQ) { setSeenQ(qp); if (qp) { setQ(qp); setType(null); } }
  const [max, setMax] = useState<number | null>(null);
  const { answers, setAnswers } = useAnswers();
  const [mode, setMode] = useState<'price' | 'monthly'>('price');
  const [cap, setCap] = useState<number | null>(null);
  const [sheetOpen, setSheetOpen] = useState(false);
  const monthly = mode === 'monthly' && !!cap;
  // Home's "You can afford" card opens Monthly with its slider amount.
  const [seenM, setSeenM] = useState<string | undefined>(undefined);
  // ...and jumps straight down to the cars that fit (Loudjier, Nov 8: 'See all' must show the cars, not the tiles).
  const listRef = useRef<FlatList<any>>(null);
  const resultsY = useRef(0);
  const [jump, setJump] = useState(0);
  if (mp !== seenM) { setSeenM(mp); const n = Number(mp); if (n > 0) { setMode('monthly'); setCap(n); setJump((j) => j + 1); } }
  useEffect(() => {
    if (!jump) return;
    const t = setTimeout(() => listRef.current?.scrollToOffset({ offset: Math.max(0, resultsY.current - 8), animated: true }), 350);
    return () => clearTimeout(t);
  }, [jump]);
  const [more, setMore] = useState<string[]>([]);
  const brand = brandOf(q);
  const brandModels = useBrandModels(brand);
  const toggleMore = (m: string) => setMore(more.includes(m) ? more.filter((x) => x !== m) : [...more, m]);

  const [fl, setFl] = useState<Filters>(NO_FILTERS);
  const build = useCallback((fl: Filters) => {
    const words = q.toLowerCase().split(/\s+/).filter(Boolean);
    const out: { car: Car; year: number; pay?: number; over?: number; trim?: string }[] = [];
    for (const car of CARS) {
      const trims = trimNames(car.id);
      const text = `${car.make} ${car.model} ${car.body} ${car.tag} ${car.green ?? ''} ${trims.join(' ')}`.toLowerCase();
      // A brand name ("Chevrolet", "VW") matches every car from that brand.
      if (brand ? car.make !== dataMake(brand) || words.some((w) => !text.includes(w) && brandOf(w) !== brand) : words.some((w) => !text.includes(w))) continue;
      if (type && !carIsKind(car, type)) continue;
      if (!carOk(car, fl)) continue;
      if (more.includes('Third row') && car.features['Third row'] !== 'inc') continue;
      if (more.includes('AWD / 4x4') && !car.features['4x4 / AWD']) continue;
      let years = yearsOf(car).filter((y) => yearOk(car, y, fl));
      if (!years.length) continue;
      if (more.includes('New only')) years = years.filter((y) => priceFor(car, y)?.isNew);
      // A search word that names a version ("XLE") shows it on the card.
      const trim = words.length ? trims.find((n) => trimParts(n).some((p) => words.includes(p.toLowerCase()))) : undefined;
      if (monthly) {
        const pick = monthlyPick(answers, car, years, cap!);
        if (pick) out.push({ car, year: pick.year, pay: pick.pay, over: pick.over, trim });
        continue;
      }
      if (max) years = years.filter((y) => (priceFor(car, y)?.amount ?? Infinity) <= max);
      if (!years.length) continue;
      out.push({ car, year: years[0], trim });
    }
    // Monthly: cars that fit first (best-sellers, then lower payment), then "Just over".
    if (monthly) return out.sort((a, b) => (a.over ?? 0) - (b.over ?? 0) || Number(!!b.car.popular) - Number(!!a.car.popular) || (a.pay ?? 0) - (b.pay ?? 0));
    // Best-sellers first, then cheaper first.
    return out.sort((a, b) => Number(!!b.car.popular) - Number(!!a.car.popular) || (priceFor(a.car, a.year)?.amount ?? 0) - (priceFor(b.car, b.year)?.amount ?? 0));
  }, [q, type, max, more, brand, monthly, cap, answers]);
  const list = useMemo(() => build(fl), [build, fl]);
  const countFor = useCallback((x: Filters) => build(x).length, [build]);
  const fitCount = list.filter((x) => !x.over).length;
  const loan = loanOf(answers);
  const st = stateFromZip(answers.zip);

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm && <SkyHeader title="Search" />}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <FlatList ref={listRef} refreshControl={pull}
        data={list}
        keyExtractor={(x) => `${x.car.id}-${x.year}`}
        keyboardShouldPersistTaps="handled"
        initialNumToRender={10}
        contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 110 }}
        ListHeaderComponent={
          <View>
            {!calm && <H size={34} style={{ marginTop: 14 }}>Search</H>}
            <View style={s.box}>
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none" stroke="#888" strokeWidth={2}><Circle cx="11" cy="11" r="7" /><Path d="M20 20l-4-4" /></Svg>
              <TextInput value={q} onChangeText={setQ} placeholder="Try “truck” or “Honda”" placeholderTextColor="#888" style={s.input}
                accessibilityLabel="Search cars" returnKeyType="search" autoCorrect={false} />
            </View>
            {/* Smart car finder (Loudjier, Nov 12, 2026: 'This option should be available in search as an option too'). */}
            {!q && <SmartFinder />}
            {/* Cars for sale near you (picture 59, Oct 15, 2026): the map + list with drive times. */}
            <Pressable onPress={() => { tap(); router.push('/shop'); }} accessibilityRole="button" style={({ pressed }) => [s.shop, pressed && { opacity: 0.85 }]}>
              <MapIcon size={26} color={C.ink} />
              <View style={{ flex: 1 }}>
                <Text style={s.shopTitle}>Cars for sale near you</Text>
                <Text style={s.shopLine}>Real cars on a map, closest drive first.</Text>
              </View>
              <Text style={s.shopArrow}>›</Text>
            </Pressable>
            {/* "Check a car you found" (picture 45 A): a used car from anywhere, checked before you buy. */}
            <View style={s.check}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
                <VMark height={15} color="#CDB38B" />
                <Text style={s.checkTitle}>Found a car somewhere else?</Text>
              </View>
              <Text style={s.checkLine}>Check it before you buy: recalls, safety, a fair price and if it fits your budget.</Text>
              {canScan ? (
                <View style={{ flexDirection: 'row', gap: 8 }}>
                  <Pressable onPress={() => { tap(); router.push('/scan'); }} accessibilityRole="button" style={[s.checkBtn, { flex: 1 }]}>
                    <Text style={s.checkBtnText}>Scan a VIN</Text>
                  </Pressable>
                  <Pressable onPress={() => { tap(); router.push('/check'); }} accessibilityRole="button" style={[s.checkBtn, s.checkBtnGhost, { flex: 1 }]}>
                    <Text style={[s.checkBtnText, { color: skyLook ? '#FFC896' : calm ? '#7DA9F2' : '#CDB38B' }]}>Type it</Text>
                  </Pressable>
                </View>
              ) : (
                <Pressable onPress={() => { tap(); router.push('/check'); }} accessibilityRole="button" style={s.checkBtn}>
                  <Text style={s.checkBtnText}>Check a car</Text>
                </Pressable>
              )}
            </View>
            <Label style={{ marginTop: 16, color: C.muted }}>What kind of car?</Label>
            <BodyGrid value={type} onChange={setType} kinds={HAVE} />
            <View style={s.seg} accessibilityRole="tablist">
              {(['price', 'monthly'] as const).map((m) => (
                <Pressable key={m} onPress={() => { tap(); setMode(m); }} accessibilityRole="tab" accessibilityState={{ selected: mode === m }}
                  style={[s.segB, mode === m && s.segOn]}>
                  <Text style={[s.segT, mode === m && { color: C.onAccent }]}>{m === 'price' ? 'Price' : 'Monthly'}</Text>
                </Pressable>
              ))}
            </View>
            {mode === 'price' ? (
              <View style={s.chips}>{PRICES.map(([l, v]) => <Chip key={l} label={l} on={max === v} onPress={() => setMax(max === v ? null : v)} />)}</View>
            ) : (
              <>
                <View style={s.chips}>{MONTHLY_CHIPS.map((v) => <Chip key={v} label={`$${v}/mo`} on={cap === v} onPress={() => setCap(cap === v ? null : v)} />)}</View>
                <Pressable onPress={() => { tap(); setSheetOpen(true); }} accessibilityRole="button" accessibilityLabel="Change loan details" style={s.how}>
                  <Text style={s.howT}>{`${loan.credit} credit`}</Text>
                  <Text style={s.howT}> · </Text>
                  <Text style={s.howT}>{`${money(DOWN[loan.down!] ?? 0)} down`}</Text>
                  <Text style={s.howT}> · </Text>
                  <Text style={s.howT}>72 months</Text>
                  <Text style={s.howT}> · </Text>
                  <Text style={s.howT}>{costsFor(st).name}</Text>
                  <Text style={[s.howT, { color: C.yellow, fontFamily: F.bodyBold }]}>  Change ›</Text>
                </Pressable>
                <PreLink />
              </>
            )}
            <View style={s.chips}>{MORE.map((m) => <Chip key={m} label={m} on={more.includes(m)} onPress={() => toggleMore(m)} />)}</View>
            <View style={{ marginTop: 14 }}><FilterBar value={fl} onChange={setFl} count={countFor} /></View>
            <View onLayout={(e) => { resultsY.current = e.nativeEvent.layout.y; }} />
            {brand ? (
              <View style={{ marginTop: 16, marginBottom: 8 }}>
                <H size={30}>{brand}</H>
                <Body style={{ fontSize: 13, color: C.muted }}>
                  {brandModels ? `${Math.max(brandModels.length, list.length)} models · ${list.length} with full details` : `${list.length} with full details · loading the full list…`}
                </Body>
              </View>
            ) : monthly ? <Label style={{ marginTop: 14, marginBottom: 8 }}>{`${fitCount} fit about $${cap}/mo`}</Label>
              : <Label style={{ marginTop: 14, marginBottom: 8 }}>{list.length} car{list.length === 1 ? '' : 's'}{mode === 'price' && max ? ' · newest year in your price' : ''}</Label>}
          </View>
        }
        renderItem={({ item, index }) => (
          <View>
            {monthly && item.over && (index === 0 || !list[index - 1].over) ? <Label style={{ marginTop: 10, marginBottom: 8 }}>Just over</Label> : null}
            {/* Picture 129 A (Oct 24, 2026): big cards. Monthly passes its payment and how much over the chip it is. */}
            <BigCard car={item.car} year={item.year}
              note={item.trim ? `${item.car.body} · ${item.trim} version` : undefined}
              pay={item.pay} over={item.pay != null ? item.over ?? 0 : undefined} />
          </View>
        )}
        ListEmptyComponent={<Body>No cars match. Try fewer filters, or ask your coach.</Body>}
        ListFooterComponent={
          <View>
            {!!list.length && <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 6 }}>{monthly ? 'Payments are estimates with tax and fees, not a loan offer. Your real rate depends on the lender.' : 'New prices are starting prices before tax. Used prices are estimates.'}</Body>}
            {!!brand && <BrandMore brand={brand} models={brandModels} />}
          </View>
        }
      />
      </View>
      <CompareBar lift={70} />
      {sheetOpen && <LoanSheet onClose={() => setSheetOpen(false)} answers={answers} setAnswers={setAnswers} />}
    </SafeAreaView>
  );
}

// "Change ›" in Monthly: credit, money down and ZIP. Saved in the coach answers, so the coach and car pages match.
function LoanSheet({ onClose, answers, setAnswers }: { onClose: () => void } & Pick<ReturnType<typeof useAnswers>, 'answers' | 'setAnswers'>) {
  const loan = loanOf(answers);
  const [zip, setZip] = useState(answers.zip ?? '');
  const saveZip = (z: string) => { setZip(z); if (/^\d{5}$/.test(z)) setAnswers({ ...answers, zip: z }); };
  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <Pressable style={s.back} onPress={onClose} accessibilityLabel="Close" />
      <View style={s.sheet} accessibilityViewIsModal>
        <View style={s.grab} />
        <Text style={s.sheetH}>Your loan, about</Text>
        <Label style={s.sheetL}>Credit</Label>
        <View style={s.chips}>{CREDIT_CHOICES.map((c) => <Chip key={c} label={c} on={loan.credit === c} onPress={() => setAnswers({ ...answers, credit: c })} />)}</View>
        <Label style={s.sheetL}>Money down</Label>
        <View style={s.chips}>{DOWN_CHOICES.map((d) => <Chip key={d} label={d} on={loan.down === d} onPress={() => setAnswers({ ...answers, down: d })} />)}</View>
        <Label style={s.sheetL}>ZIP code (for tax and fees)</Label>
        <TextInput value={zip} onChangeText={(z) => saveZip(z.replace(/\D/g, '').slice(0, 5))} keyboardType="number-pad" placeholder="30303" placeholderTextColor="#888"
          accessibilityLabel="ZIP code" style={[s.box, s.input, { flex: 0 }]} />
        <UseMyLocation needZip style={{ marginTop: 8 }} onSpot={(sp) => saveZip(sp.zip!)} />
        <Body style={{ fontSize: 12, color: C.muted, marginTop: 10 }}>72-month loan. We never check your credit.</Body>
        <Pressable onPress={() => { tap(); onClose(); }} accessibilityRole="button" style={s.done}>
          <Text style={s.doneT}>Done</Text>
        </Pressable>
      </View>
    </Modal>
  );
}

const s = themed(() => StyleSheet.create({
  // Sunset Calm: the dark card turns deep green with peach, like the Welcome road.
  check: { backgroundColor: skyLook ? '#1F4D3A' : calm ? '#0F1A2A' : '#0E1014', borderRadius: 16, padding: 14, marginTop: 12 },
  shop: { flexDirection: 'row', alignItems: 'center', gap: 12, backgroundColor: C.card, borderRadius: 16, padding: 14, marginTop: 12, borderWidth: 1.5, borderColor: C.yellow },
  shopTitle: { fontFamily: F.head, fontSize: 19, textTransform: 'uppercase', color: C.ink },
  shopLine: { fontFamily: F.body, fontSize: 13, color: C.muted },
  shopArrow: { fontFamily: F.bodyBold, fontSize: 28, color: C.yellow },
  checkTitle: { fontFamily: F.head, fontSize: 18, textTransform: 'uppercase', color: '#F2EFE8' },
  checkLine: { fontFamily: F.body, fontSize: 13.5, lineHeight: 19, color: skyLook ? '#CFE6D8' : '#C9CED6', marginTop: 4 },
  checkBtn: { marginTop: 10, backgroundColor: skyLook ? '#FFC896' : calm ? '#7DA9F2' : '#CDB38B', borderRadius: 12, height: 46, alignItems: 'center', justifyContent: 'center' },
  checkBtnGhost: { backgroundColor: 'transparent', borderWidth: 1.5, borderColor: skyLook ? '#FFC896' : calm ? '#7DA9F2' : '#CDB38B' },
  checkBtnText: { fontFamily: F.head, fontSize: 16, letterSpacing: 1, textTransform: 'uppercase', color: skyLook ? '#1F4D3A' : calm ? '#0F1A2A' : '#0E1014' },
  box: { flexDirection: 'row', alignItems: 'center', gap: 8, borderWidth: 1, borderColor: C.line, borderRadius: 12, height: 52, paddingHorizontal: 12, marginTop: 12 },
  input: { flex: 1, fontFamily: F.body, fontSize: 15.5, color: C.ink },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 10 },
  seg: { flexDirection: 'row', backgroundColor: C.line, borderRadius: 12, padding: 3, marginTop: 14 },
  segB: { flex: 1, alignItems: 'center', paddingVertical: 9, borderRadius: 10 },
  segOn: { backgroundColor: C.fill },
  segT: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.muted },
  how: { flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', marginTop: 8 },
  howT: { fontFamily: F.body, fontSize: 12.5, color: C.muted },
  back: { flex: 1, backgroundColor: 'rgba(15,26,42,0.45)' },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 26, borderTopRightRadius: 26, padding: 20, paddingBottom: 30 },
  grab: { alignSelf: 'center', width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, marginBottom: 14 },
  sheetH: { fontFamily: F.head, fontSize: 21, color: C.ink },
  sheetL: { marginTop: 14, color: C.muted },
  done: { marginTop: 16, backgroundColor: C.fill, borderRadius: 14, height: 50, alignItems: 'center', justifyContent: 'center' },
  doneT: { fontFamily: F.bodyBold, fontSize: 16, color: C.onAccent },
}));
