// "Car info" on the car page (picture 209, Loudjier Nov 6, 2026): real facts for this model year in simple tiles.
// Safety stars, MPG and recalls come from NHTSA and EPA; seats and features from our car list. When a feature depends
// on the version we say so ("Some versions · ask the dealer"), never a guess.
import { router } from 'expo-router';
import { StyleSheet, View } from 'react-native';
import Svg, { Circle, Path } from 'react-native-svg';

import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { featureAt, type Car } from '@/data/cars';
import type { Facts } from '@/data/gov';
import { C, F, themed } from '@/theme';

const featureWord = (st?: string) => (st === 'inc' ? ['Standard', ''] : st === 'trim' || st === 'plan' ? ['Some versions', 'Ask the dealer'] : st === 'check' ? ['Check', 'May not have it'] : ['No', '']);
const fuelWord = (car: Car, f?: string) => (car.green === 'ev' ? 'Electric' : /premium/i.test(f ?? '') ? 'Premium' : /electric/i.test(f ?? '') ? 'Electric' : f ? 'Regular' : '—');

const Icon = ({ d }: { d: string }) => (
  <Svg width={15} height={15} viewBox="0 0 24 24" fill="none" stroke={C.yellow} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"><Path d={d} /></Svg>
);
const I = {
  star: 'M12 3l2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1L3.2 9.5l6.1-.9z',
  gas: 'M4 20V5a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v15M3 20h12M14 9h2a2 2 0 0 1 2 2v5a1.5 1.5 0 0 0 3 0V8l-3-3M6 8h6',
  seat: 'M8 3h5a2 2 0 0 1 2 2v7H8zM8 12h9l2 6M8 12v7M17 18v2',
  car: 'M4 16v-4l2-5h12l2 5v4M4 12h16',
  cruise: 'M12 7v5l3 2M4 12a8 8 0 1 0 16 0 8 8 0 1 0-16 0',
};

function Tile({ icon, k, v, sub }: { icon: string; k: string; v: string; sub?: string }) {
  return (
    <View style={s.tile} accessible accessibilityLabel={`${k}: ${v}${sub ? `, ${sub}` : ''}`}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}><Icon d={icon} /><Text style={s.k}>{k}</Text></View>
      <Text style={s.v} numberOfLines={1}>{v}</Text>
      {sub ? <Text style={s.sub} numberOfLines={1}>{sub}</Text> : null}
    </View>
  );
}

export function CarInfo({ car, year, facts }: { car: Car; year: number; facts: Facts | null }) {
  const awd = featureWord(featureAt(car, year, '4x4 / AWD'));
  const cruise = featureWord(featureAt(car, year, 'Adaptive cruise'));
  const mpg = facts?.mpg;
  const recalls = facts?.recalls?.length ?? 0;
  const parts = [...new Set((facts?.recalls ?? []).map((r) => (r.part ?? '').split(':')[0].split(',')[0].toLowerCase().replace(/s$/, '')))].slice(0, 3).join(', ');
  return (
    <View style={{ marginTop: 18 }}>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-end' }}>
        <Text style={s.h}>Car info</Text>
        <Text style={s.src}>{`${year} · NHTSA + EPA${facts?.saved ? ` · last checked ${facts.saved}` : ''}`}</Text>
      </View>
      <View style={s.grid}>
        <Tile icon={I.star} k="Safety" v={facts?.stars ? '★'.repeat(facts.stars) : facts === null ? '…' : 'Not rated'} sub={facts?.stars ? `${facts.stars} stars overall` : undefined} />
        <Tile icon={I.gas} k={car.green === 'ev' ? 'Range' : 'Gas'} v={mpg ? `${mpg.combined} MPG` : facts === null ? '…' : 'Not known'} sub={mpg ? `${mpg.city} city · ${mpg.hwy} highway` : undefined} />
        <Tile icon={I.seat} k="Seats" v={String(car.seats)} sub={car.seats >= 7 ? 'Three rows' : undefined} />
        <Tile icon={I.gas} k="Fuel" v={fuelWord(car, mpg?.fuel)} />
        <Tile icon={I.car} k="AWD" v={awd[0]} sub={awd[1] || undefined} />
        <Tile icon={I.cruise} k="Adaptive cruise" v={cruise[0]} sub={cruise[1] || (cruise[0] === 'Standard' ? 'Keeps your distance' : undefined)} />
      </View>
      {facts && (
        <View style={[s.recall, !recalls && { backgroundColor: C.goodBg }]}>
          <Text style={[s.recallH, { color: recalls ? C.ink : C.goodInk }]}>{recalls ? `${recalls} recall${recalls === 1 ? '' : 's'} for ${year}` : `No recalls for ${year}`}</Text>
          {recalls ? <Text style={s.sub}>{`${parts ? `${parts.charAt(0).toUpperCase()}${parts.slice(1)}… ` : ''}Fixes are free at any dealer.`}</Text> : null}
        </View>
      )}
      <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>
        <Pressable onPress={() => { tap(); router.push('/check'); }} accessibilityRole="button" style={s.btn}>
          <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.ink} strokeWidth={2.2} strokeLinecap="round"><Path d="M5 12l5 5 9-10" /></Svg>
          <Text style={s.btnT}>Check my VIN</Text>
        </Pressable>
        <Pressable onPress={() => { tap(); router.push({ pathname: '/cost/[id]', params: { id: car.id, year: String(year) } }); }} accessibilityRole="button" style={s.btn}>
          <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.ink} strokeWidth={2} strokeLinecap="round"><Circle cx="12" cy="12" r="8" /><Path d="M12 8v8M9.5 10.5h4a1.5 1.5 0 0 1 0 3h-3a1.5 1.5 0 0 0 0 3H15" /></Svg>
          <Text style={s.btnT}>Cost to own</Text>
        </Pressable>
      </View>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  h: { fontFamily: F.head, fontSize: 19, color: C.ink },
  src: { fontFamily: F.bodySemi, fontSize: 11, color: C.muted },
  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginTop: 8 },
  tile: { width: '48.5%', flexGrow: 1, flexBasis: '45%', backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 16, padding: 11 },
  k: { fontFamily: F.bodyBold, fontSize: 11.5, color: C.muted },
  v: { fontFamily: F.head, fontSize: 17, color: C.ink, marginTop: 2 },
  sub: { fontFamily: F.bodySemi, fontSize: 11.5, color: C.muted },
  recall: { marginTop: 8, borderRadius: 16, padding: 12, backgroundColor: C.fill },
  recallH: { fontFamily: F.bodyBold, fontSize: 14.5 },
  btn: { flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 7, borderWidth: 1.5, borderColor: C.line, borderRadius: 14, minHeight: 46, backgroundColor: C.card },
  btnT: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
}));
