// The shopper's ZIP for Popular in your area (data/popular.ts). Its own tiny file so code that runs outside the app
// (the website build reads state/answers.tsx) doesn't load the database client.
let zip = '';
/** Set from the coach answers (AnswersProvider), like the home state for taxes. */
export function setPopularZip(z?: string) { zip = z && /^\d{5}$/.test(z) ? z : ''; }
export function popularZip() { return zip; }
