// Pick by body style (picture 68 B "Car photos", picked Oct 16, 2026). Search shows a 2-across grid
// of photo tiles; the cars-for-sale map shows the same tiles in one swipe row (68 E).
// Photos are our own stock photos (credits on Me › Where our info comes from).
import { Image } from 'expo-image';
import { ScrollView, StyleSheet, View } from 'react-native';

import { photoOf } from '@/components/car-photo';
import { tap } from '@/components/ui';
import { carIsKind, type Kind } from '@/data/cars';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

export { carIsKind };
export type { Kind } from '@/data/cars';
export const KINDS: { kind: Kind; label: string; photo: string }[] = [
  { kind: 'SUV', label: 'SUV', photo: 'rav4' },
  { kind: 'Sedan', label: 'Sedan', photo: 'camry' },
  { kind: 'Truck', label: 'Truck', photo: 'f150' },
  { kind: 'Minivan', label: 'Minivan', photo: 'sienna' },
  { kind: 'Hatchback', label: 'Hatchback', photo: 'mirage' },
  { kind: 'Sports', label: 'Sports car', photo: 'p911' },
  { kind: 'Electric', label: 'Electric', photo: 'model3' },
  { kind: 'Hybrid', label: 'Hybrid', photo: 'crv' },
];

function Tile({ k, on, onPress, h, small }: { k: (typeof KINDS)[number]; on: boolean; onPress: () => void; h: number; small?: boolean }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" accessibilityState={{ selected: on }} accessibilityLabel={k.label}
      style={({ pressed }) => [s.tile, { height: h }, on && s.on, pressed && { opacity: 0.85 }]}>
      <Image source={photoOf(k.photo)} style={StyleSheet.absoluteFill} contentFit="cover" />
      <View style={s.shade} />
      <Text numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.7} style={[s.label, small && s.small]}>{k.label}</Text>
      {on && <View style={s.check}><Text style={s.checkText}>✓</Text></View>}
    </Pressable>
  );
}

// Search: 2 across. Tap again to clear.
export function BodyGrid({ value, onChange, kinds, cols = 2, h = 72 }: { value: Kind | null; onChange: (k: Kind | null) => void; kinds: Kind[]; cols?: 2 | 4; h?: number }) {
  return (
    <View style={s.grid}>
      {KINDS.filter((k) => kinds.includes(k.kind)).map((k) => (
        <View key={k.kind} style={{ width: cols === 4 ? '23.5%' : '48.5%' }}>
          <Tile k={k} h={h} small={cols === 4} on={value === k.kind} onPress={() => onChange(value === k.kind ? null : k.kind)} />
        </View>
      ))}
    </View>
  );
}

// Map: one swipe row. `first` is the "your picks" tile (the coach's cars).
export function BodyRow({ value, onChange, first }: { value: Kind | null; onChange: (k: Kind | null) => void; first: string }) {
  return (
    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8, paddingRight: 8 }}>
      <Pressable onPress={() => { tap(); onChange(null); }} accessibilityRole="button" accessibilityState={{ selected: !value }}
        style={[s.tile, s.picks, { height: 58 }, !value && s.on]}>
        <Text style={s.picksTop}>Your picks</Text>
        <Text style={s.picksText} numberOfLines={2}>{first}</Text>
      </Pressable>
      {KINDS.map((k) => (
        <View key={k.kind} style={{ width: 96 }}>
          <Tile k={k} h={58} small on={value === k.kind} onPress={() => onChange(value === k.kind ? null : k.kind)} />
        </View>
      ))}
    </ScrollView>
  );
}

const s = themed(() => StyleSheet.create({
  grid: { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'space-between', rowGap: 8, marginTop: 10 },
  tile: { borderRadius: 12, overflow: 'hidden', justifyContent: 'flex-end', backgroundColor: C.hero },
  on: { borderWidth: 3, borderColor: C.yellow },
  shade: { position: 'absolute', left: 0, right: 0, bottom: 0, height: '60%', backgroundColor: 'rgba(0,0,0,0.42)' },
  label: { fontFamily: F.head, fontSize: 15, letterSpacing: 0.6, textTransform: 'uppercase', color: '#FFFFFF', paddingHorizontal: 8, paddingBottom: 5 },
  // 4 across (coach): normal case so 'Hatchback' and 'Sports car' fit on one line (picture 185).
  small: { fontSize: 12, letterSpacing: 0, textTransform: 'none', paddingHorizontal: 6 },
  check: { position: 'absolute', top: 5, right: 5, width: 22, height: 22, borderRadius: 11, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  checkText: { fontFamily: F.bodyBold, fontSize: 13, color: C.onAccent },
  picks: { width: 96, backgroundColor: C.card, borderWidth: 1, borderColor: C.line, padding: 7, justifyContent: 'center' },
  picksTop: { fontFamily: F.head, fontSize: 12.5, letterSpacing: 0.6, textTransform: 'uppercase', color: C.yellow },
  picksText: { fontFamily: F.body, fontSize: 11, color: C.muted, marginTop: 1 },
}));
