// Language switch (picture 50 B, picked Oct 14, 2026): the "ES" / "EN" button at the top of Login,
// and English / Español on Me. Switching redraws the app (like switching looks) and comes back here.
import { Platform, StyleSheet, View } from 'react-native';

import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { lang, type Lang } from '@/i18n';
import { useSaved } from '@/state/saved';
import { C, F, resumeAt, themed } from '@/theme';
import { GlobeIcon } from '@/components/icons';

export function useSetLang() {
  const { prefs, setPrefs } = useSaved();
  return (l: Lang, back: string) => {
    if (l === lang) return;
    tap();
    if (Platform.OS !== 'web') resumeAt(back);
    setPrefs({ ...prefs, lang: l });
  };
}

// The small round button on Login. Shows the other language.
export function LangChip() {
  const setLang = useSetLang();
  const other: Lang = lang === 'es' ? 'en' : 'es';
  return (
    <Pressable onPress={() => setLang(other, '/login')} accessibilityRole="button" hitSlop={8}
      accessibilityLabel={other === 'es' ? 'Español. Cambiar a español' : 'English. Switch to English'} style={s.chip}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 5 }}><GlobeIcon size={15} color="#FFFFFF" /><Text style={s.chipText}>{other.toUpperCase()}</Text></View>
    </Pressable>
  );
}

// English / Español on Me.
export function LangPicker() {
  const setLang = useSetLang();
  return (
    <View style={s.row} accessibilityRole="radiogroup">
      {([['en', 'English'], ['es', 'Español']] as const).map(([l, name]) => {
        const on = lang === l;
        return (
          <Pressable key={l} onPress={() => setLang(l, '/me')} accessibilityRole="radio" accessibilityState={{ checked: on }}
            accessibilityLabel={name} style={[s.opt, on && s.on]}>
            <Text style={s.optText}>{name}</Text>
          </Pressable>
        );
      })}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  chip: { borderWidth: 1.5, borderColor: '#FFFFFF', borderRadius: 999, paddingHorizontal: 10, paddingVertical: 4 },
  chipText: { fontFamily: F.head, fontSize: 14, letterSpacing: 1, color: '#FFFFFF' },
  row: { flexDirection: 'row', gap: 10, marginTop: 8 },
  opt: { flex: 1, height: 50, borderRadius: 14, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, alignItems: 'center', justifyContent: 'center' },
  on: { borderWidth: 2, borderColor: C.ink },
  optText: { fontFamily: F.bodyBold, fontSize: 16, color: C.ink },
}));
