import { useEffect, useState } from 'react';
import { StyleSheet } from 'react-native';

import { onNotify } from '@/components/notify';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

export function Toast() {
  const [msg, setMsg] = useState<{ title: string; msg: string } | null>(null);
  useEffect(() => {
    let t: ReturnType<typeof setTimeout>;
    onNotify((title, m) => { setMsg({ title, msg: m }); clearTimeout(t); t = setTimeout(() => setMsg(null), 2600); });
    return () => { onNotify(null); clearTimeout(t); };
  }, []);
  if (!msg) return null;
  return (
    <Pressable onPress={() => setMsg(null)} style={s.box} accessibilityRole="alert">
      <Text style={s.title}>{msg.title}</Text>
      <Text style={s.msg}>{msg.msg}</Text>
    </Pressable>
  );
}

const s = themed(() => StyleSheet.create({
  box: { position: 'absolute', left: 16, right: 16, top: 60, backgroundColor: C.hero, borderWidth: 2, borderColor: C.yellow, padding: 14, zIndex: 100 },
  title: { fontFamily: F.head, fontSize: 18, color: C.yellow, textTransform: 'uppercase' },
  msg: { fontFamily: F.body, fontSize: 14, color: C.ink, marginTop: 2 },
}));
