// Soft "free account" sheet (picture 104/106, Oct 18, 2026): shows only when someone taps a feature that
// needs an account (recall alerts, reminders, price drops, more than 3 saved cars). Always has "Not now".
import { Modal, Platform, StyleSheet, View } from 'react-native';

import { BellIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { BigBtn, tint } from '@/components/account-ui';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/state/auth';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

export function AccountGate({ title, sub, onClose, onEmail }: { title: string; sub?: string; onClose: () => void; onEmail: () => void }) {
  const { signInWithGoogle } = useAuth();
  const google = async () => {
    const err = await signInWithGoogle();
    if (err) return notify('Google sign-in', err);
    const { data } = await supabase.auth.getSession();
    if (data.session) { notify('Welcome!', 'Your free account is ready.'); onClose(); }
  };
  const c = tint('blue');
  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <Pressable style={s.back} onPress={onClose} accessibilityLabel="Close" />
      <View style={s.sheet} accessibilityViewIsModal>
        <View style={s.grab} />
        <View style={[s.icon, { backgroundColor: c.bg }]}><BellIcon size={24} color={c.fg} /></View>
        <Text style={s.title}>{title}</Text>
        <Text style={s.sub}>{sub ?? 'Free account. 30 seconds. No spam, and we never sell your info.'}</Text>
        {Platform.OS !== 'web' && <BigBtn label="Continue with Google" onPress={google} />}
        <BigBtn label="Use my email" kind={Platform.OS === 'web' ? 'solid' : 'soft'} onPress={onEmail} />
        <Pressable onPress={onClose} accessibilityRole="button" style={{ alignItems: 'center', paddingVertical: 14 }}>
          <Text style={s.not}>Not now</Text>
        </Pressable>
      </View>
    </Modal>
  );
}

const s = themed(() => StyleSheet.create({
  back: { flex: 1, backgroundColor: 'rgba(15,26,42,0.45)' },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 26, borderTopRightRadius: 26, padding: 20, paddingBottom: 30 },
  grab: { alignSelf: 'center', width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, marginBottom: 14 },
  icon: { alignSelf: 'center', width: 52, height: 52, borderRadius: 16, alignItems: 'center', justifyContent: 'center' },
  title: { fontFamily: F.head, fontSize: 21, color: C.ink, textAlign: 'center', marginTop: 12 },
  sub: { fontFamily: F.body, fontSize: 14, lineHeight: 20, color: C.muted, textAlign: 'center', marginTop: 6, marginBottom: 6 },
  not: { fontFamily: F.bodyBold, fontSize: 15, color: C.muted },
}));
