// Brand dealers near your ZIP (moved from the old "Find near me" page to the bottom of the one car page).
import { useEffect, useState } from 'react';
import { ActivityIndicator, Linking, Platform, StyleSheet, View } from 'react-native';

import { PinIcon } from '@/components/icons';
import { Body, H, Label, tap } from '@/components/ui';
import { BRAND, type Dealer, type DealerResult, findDealers } from '@/data/dealers';
import { useAnswers } from '@/state/answers';
import { C, F, themed } from '@/theme';
import { Pressable, TextInput } from '@/components/t';
import { UseMyLocation } from '@/components/use-location';

// The web preview link cannot go online, so it only has a saved dealer list.
const PREVIEW = process.env.EXPO_PUBLIC_PREVIEW === '1';

const mapsUrl = (d: Dealer) =>
  Platform.OS === 'ios'
    ? `http://maps.apple.com/?daddr=${d.lat},${d.lon}&q=${encodeURIComponent(d.name)}`
    : `https://www.google.com/maps/dir/?api=1&destination=${d.lat},${d.lon}`;

function Action({ label, onPress, dark }: { label: string; onPress: () => void; dark?: boolean }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button"
      style={({ pressed }) => [s.act, dark && { backgroundColor: C.hero, borderColor: C.ink }, pressed && { opacity: 0.7 }]}>
      <Label style={{ fontSize: 12, color: dark ? C.yellow : C.ink, textAlign: 'center' }}>{label}</Label>
    </Pressable>
  );
}

export function DealersNear({ carId }: { carId: string }) {
  const { answers, setAnswers } = useAnswers();
  const brand = BRAND[carId] ?? '';
  const [zip, setZip] = useState(answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '');
  const [typed, setTyped] = useState(zip);
  const [found, setFound] = useState<{ key: string; res: DealerResult | null; error: boolean }>({ key: '', res: null, error: false });
  const [near, setNear] = useState(0); // bumps after "Use my location" so distances count from the real spot
  const key = zip && brand ? `${brand}-${zip}-${near}` : '';
  useEffect(() => {
    if (!key) return;
    let live = true;
    findDealers(brand, zip)
      .then((r) => live && setFound({ key, res: r, error: false }))
      .catch(() => live && setFound({ key, res: null, error: true }));
    return () => { live = false; };
  }, [key, brand, zip]);
  if (!brand) return null;
  const fresh = found.key === key;
  const res = fresh ? found.res : null;
  const state: 'idle' | 'loading' | 'error' = !key ? 'idle' : !fresh ? 'loading' : found.error ? 'error' : 'idle';
  const go = () => {
    const z = typed.trim();
    if (!/^\d{5}$/.test(z)) return;
    setAnswers({ ...answers, zip: z });
    setZip(z);
  };

  return (
    <View>
      <Label style={s.sec}>{brand} dealers near you</Label>
      <View style={s.zipRow}>
        <TextInput value={typed} onChangeText={setTyped} onSubmitEditing={go} keyboardType="number-pad" maxLength={5}
          placeholder="Your ZIP code" placeholderTextColor="#999" accessibilityLabel="ZIP code" style={s.zip} returnKeyType="search" />
        <Pressable onPress={() => { tap(); go(); }} style={s.zipBtn} accessibilityRole="button" accessibilityLabel="Search">
          <Label style={{ color: C.yellow, fontSize: 14 }}>Search</Label>
        </Pressable>
      </View>
      {state === 'loading' && <View style={s.box}><ActivityIndicator color={C.ink} /><Body>Finding {brand} dealers…</Body></View>}
      {state === 'error' && (
        <View style={s.box}>
          <Body style={{ flex: 1 }}>
            {PREVIEW
              ? 'This preview link can’t go online, so only ZIP 30311 works here. In the real app, any ZIP works.'
              : 'We couldn’t load dealers right now. Check your internet and try again.'}
          </Body>
        </View>
      )}
      <UseMyLocation needZip style={{ marginTop: 8 }} onSpot={(sp) => { setTyped(sp.zip!); setAnswers({ ...answers, zip: sp.zip! }); setZip(sp.zip!); setNear((n) => n + 1); }} />
      {!zip && state === 'idle' && <Body style={{ marginTop: 10 }}>Type your ZIP code to see dealers near you.</Body>}
      {res && (
        <>
          <Label style={{ marginTop: 12 }}>
            {res.dealers.length ? `${res.dealers.length} ${brand} dealer${res.dealers.length > 1 ? 's' : ''} within 30 miles of ${res.place}` : `No ${brand} dealers found within 30 miles of ${res.place}`}
          </Label>
          {res.saved && <Body style={{ fontSize: 12, color: C.muted }}>Saved list from {res.saved}.{PREVIEW ? '' : ' Connect to the internet for the newest list.'}</Body>}
          {res.dealers.map((d) => (
            <View key={d.id} style={s.dealer}>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 8 }}>
                <Body bold style={{ flex: 1, fontSize: 16 }}>{d.name}</Body>
                <H size={20}>{d.miles} mi</H>
              </View>
              {!!d.address && (
                <View style={{ flexDirection: 'row', gap: 4, alignItems: 'center', marginTop: 2 }}>
                  <PinIcon size={13} /><Body style={{ fontSize: 13, flex: 1 }}>{d.address}</Body>
                </View>
              )}
              <View style={s.acts}>
                {!!d.website && <Action label="Check availability" dark onPress={() => Linking.openURL(d.website!)} />}
                {!!d.phone && <Action label="Call" dark={!d.website} onPress={() => Linking.openURL(`tel:${d.phone!.replace(/[^\d+]/g, '')}`)} />}
                <Action label="Directions" dark={!d.website && !d.phone} onPress={() => Linking.openURL(mapsUrl(d))} />
              </View>
            </View>
          ))}
          <Body style={{ fontSize: 11, color: C.muted, marginTop: 8 }}>Dealer map data © OpenStreetMap contributors. Call ahead to check what’s in stock.</Body>
        </>
      )}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  sec: { marginTop: 20, marginBottom: 6 },
  zipRow: { flexDirection: 'row', gap: 6 },
  zip: { flex: 1, height: 50, borderWidth: 1, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 17, color: C.ink },
  zipBtn: { width: 90, height: 50, backgroundColor: C.hero, alignItems: 'center', justifyContent: 'center', borderRadius: 12 },
  box: { flexDirection: 'row', gap: 10, alignItems: 'center', borderWidth: 2, borderColor: C.line, padding: 12, marginTop: 12 },
  dealer: { borderWidth: 1, borderColor: C.line, borderRadius: 12, padding: 12, marginTop: 8 },
  acts: { flexDirection: 'row', gap: 6, marginTop: 10, flexWrap: 'wrap' },
  act: { borderWidth: 1, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, paddingVertical: 8, backgroundColor: C.bg },
}));
