// "For sale near you" on the car page (picture 71 A): real cars of this model near the shopper's ZIP,
// each with the Looks low / fair / high tag. Only test accounts get real cars until Auto.dev says yes in
// writing; everyone else sees "Coming soon" (the shop screen has the email box).
import { router } from 'expo-router';
import { useEffect, useState } from 'react';
import { Image, ScrollView, StyleSheet, View } from 'react-native';

import { ColorDots } from '@/components/color-pick';
import { PriceTag } from '@/components/price-box';
import { colorFamily, type ColorFamily } from '@/data/colors';
import { Body, Label, tap } from '@/components/ui';
import type { Car } from '@/data/cars';
import { listingTag } from '@/data/fair-price';
import { findListings, listingName, skipAccidents, withoutAccidents, type Found } from '@/data/listings';
import { money } from '@/data/prices';
import { useAnswers } from '@/state/answers';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';
import { useRefreshTick } from '@/lib/refresh';

export const openShop = (car: Car) => router.push({ pathname: '/shop', params: { ids: car.id } });

export function ForSaleRow({ car, onCount }: { car: Car; onCount?: (n: number) => void }) {
  const { answers } = useAnswers();
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  const noWreck = skipAccidents(answers);
  const key = zip ? `${car.id}-${zip}${noWreck ? '-nw' : ''}` : '';
  const [got, setGot] = useState<{ key: string; found: Found } | null>(null);
  const tick = useRefreshTick();
  useEffect(() => {
    if (!key) return;
    let on = true;
    const done = (raw: Found) => {
      if (!on) return;
      const found = noWreck ? withoutAccidents(raw) : raw;
      on = false;
      setGot({ key, found });
      onCount?.(found.kind === 'cars' ? found.cars.length : 0);
    };
    // A weak signal never leaves the row stuck on "Looking…".
    const slow = setTimeout(() => done({ kind: 'offline' }), 15000);
    findListings({ zip, models: [car] }).then(done).catch(() => done({ kind: 'offline' }));
    return () => { on = false; clearTimeout(slow); };
  }, [key, zip, car, onCount, noWreck, tick]);
  const found = got?.key === key ? got.found : null;
  const [color, setColor] = useState<ColorFamily | null>(null);

  const card = (title: string, line: string) => (
    <Pressable onPress={() => { tap(); openShop(car); }} accessibilityRole="button" style={s.card}>
      <Body bold>{title}</Body>
      <Body style={s.small}>{line}</Body>
    </Pressable>
  );

  let body: React.ReactNode;
  if (!zip) body = card(`See ${car.model}s for sale near you`, 'Add your ZIP code to see real cars at dealers near you.');
  else if (!found) body = <Body style={s.small}>Looking for {car.model}s near {zip}…</Body>;
  else if (found.kind === 'soon') body = card('Coming soon', `Soon you’ll see real ${car.model}s for sale near ${zip} here, each with a fair-price tag.`);
  else if (found.kind !== 'cars') body = card(`See ${car.model}s for sale near you`, 'Couldn’t load cars right now. Tap to try again.');
  else if (!found.cars.length) body = card(`No ${car.model}s for sale nearby right now`, 'Tap to look farther away.');
  else {
    const cars = [...found.cars].filter((l) => !color || colorFamily(l.color) === color).sort((a, b) => a.min - b.min).slice(0, 8);
    body = (
      <>
      <Label style={[s.small, { marginBottom: 2 }]}>Colors for sale near you</Label>
      <ColorDots colors={found.cars.map((l) => l.color)} value={color} onChange={setColor} />
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8 }}>
        {cars.map((l) => {
          const t = listingTag(l);
          return (
            <Pressable key={l.vin} onPress={() => { tap(); router.push({ pathname: '/listing/[vin]', params: { vin: l.vin } }); }}
              accessibilityRole="button" accessibilityLabel={`${listingName(l)}, ${money(l.price)}, about ${l.min} minutes away`} style={s.mini}>
              {l.photo ? <Image source={{ uri: l.photo }} style={s.photo} resizeMode="cover" /> : <View style={[s.photo, { backgroundColor: C.line }]} />}
              <View style={{ padding: 8, gap: 3 }}>
                <Text style={s.price}>{money(l.price)}</Text>
                {t ? <PriceTag tag={t.tag} /> : null}
                <Body style={s.small} numberOfLines={1}>{`${l.year} · about ${l.min} min${l.miles != null ? ` · ${Math.round(l.miles / 1000)}K mi` : ''}`}</Body>
              </View>
            </Pressable>
          );
        })}
      </ScrollView>
      </>
    );
  }
  return (
    <View>
      <Label style={s.sec}>{found?.kind === 'cars' && found.cars.length ? (color ? `${color} · ${found.cars.filter((l) => colorFamily(l.color) === color).length} for sale` : `For sale near you · ${found.cars.length} cars`) : 'For sale near you'}</Label>
      {body}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  sec: { marginTop: 18, marginBottom: 6 },
  small: { fontSize: 12.5, color: C.muted },
  card: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 14, padding: 12, gap: 2 },
  mini: { width: 150, backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 12, overflow: 'hidden' },
  photo: { width: '100%', height: 84 },
  price: { fontFamily: F.head, fontSize: 20, color: C.ink },
}));
