// More than one car (picture 128 A, Oct 23, 2026): the list of the user's own cars and which one is open.
// Pure helpers so the rules are easy to test; the state lives in state/saved.tsx.
import type { MyCar } from '@/state/saved';

export const MAX_CARS = 5;

export type Garage = { cars: MyCar[]; active: number };

// "2022 Mazda Mazda3" reads twice: when the model already starts with the brand, say it once (like carLine).
export const carName = (c: MyCar) => `${c.year} ${c.model.toLowerCase().startsWith(c.make.toLowerCase()) ? c.model : `${c.make} ${c.model}`}`;

// The open car, or null when there are none.
export const activeOf = (g: Garage): MyCar | null => g.cars[Math.min(g.active, g.cars.length - 1)] ?? null;

// Add a car and open it (no more than MAX_CARS).
export function addTo(g: Garage, c: MyCar): Garage {
  if (g.cars.length >= MAX_CARS) return g;
  return { cars: [...g.cars, c], active: g.cars.length };
}

// Change the open car (or add the first one).
export function replaceActive(g: Garage, c: MyCar): Garage {
  if (!g.cars.length) return { cars: [c], active: 0 };
  const i = Math.min(g.active, g.cars.length - 1);
  return { cars: g.cars.map((x, j) => (j === i ? c : x)), active: i };
}

// Delete one car. The open car stays open when another one is deleted.
export function removeAt(g: Garage, i: number): Garage {
  if (i < 0 || i >= g.cars.length) return g;
  const cars = g.cars.filter((_, j) => j !== i);
  const active = g.active > i ? g.active - 1 : Math.min(g.active, Math.max(cars.length - 1, 0));
  return { cars, active };
}

// Older versions kept one car under `myCar`; it becomes car #1.
export function fromStored(d: { myCars?: unknown; activeCar?: unknown; myCar?: unknown }): Garage {
  const cars = Array.isArray(d.myCars) ? (d.myCars as MyCar[]).filter((c) => c && c.year && c.make && c.model).slice(0, MAX_CARS) : d.myCar ? [d.myCar as MyCar] : [];
  const a = typeof d.activeCar === 'number' ? d.activeCar : 0;
  return { cars, active: Math.max(0, Math.min(a, cars.length - 1)) };
}
