// What kind of car someone drives now, for the coach's "real step up" (picture 185, Nov 4, 2026).
// A friend with a Nissan Pathfinder (7 seats) picked "Sedan" and only got sedans; the coach never knew her car.
// Common models are in the list below (works offline); anything else asks NHTSA's free model list.
import { carForMine } from '@/data/cars';
import { vpicTypeOf } from '@/data/gov';

/** The coach's kind answers ("SUV (3 rows)" is only offered when someone's car has 3 rows). */
export type KindLabel = 'SUV' | 'SUV (3 rows)' | 'Sedan' | 'Truck' | 'Minivan' | 'Hatchback' | 'Sports car';
export type CarKind = { kind: KindLabel; seats: number };

const K = (kind: KindLabel, seats: number, names: string): [string, CarKind][] => names.split(',').map((n) => [n.trim(), { kind, seats }]);
// Model names in lower case. Seats = the usual number (some versions differ; it's only used to ask a question).
const TABLE: [string, CarKind][] = [
  ...K('SUV (3 rows)', 7, 'pathfinder, highlander, grand highlander, pilot, telluride, palisade, explorer, expedition, tahoe, suburban, traverse, acadia, yukon, yukon xl, durango, atlas, ascent, cx-9, cx-90, sequoia, armada, mdx, qx60, qx80, enclave, aviator, navigator, escalade, escalade esv, x7, gls, q7, xc90, grand cherokee l, wagoneer, grand wagoneer, sorento, model x, ev9, santa fe xl, flex, mountaineer, land cruiser, gx, lx, cx-8'),
  ...K('Minivan', 7, 'odyssey, sienna, pacifica, carnival, sedona, grand caravan, town & country, town and country, quest, voyager, routan, mazda5'),
  ...K('SUV', 5, 'trax, trailblazer, equinox, blazer, rav4, cr-v, hr-v, passport, rogue, rogue sport, murano, kicks, juke, escape, edge, bronco, bronco sport, ecosport, tucson, kona, santa fe, venue, ioniq 5, sportage, seltos, soul, niro, ev6, cx-3, cx-30, cx-5, cx-50, forester, crosstrek, outback, solterra, encore, encore gx, envision, terrain, wrangler, cherokee, grand cherokee, compass, renegade, 4runner, venza, c-hr, corolla cross, bz4x, rx, nx, ux, x1, x3, x5, glc, gle, gla, glb, q3, q5, q8, model y, mustang mach-e, tiguan, taos, id.4, xc40, xc60, macan, cayenne, range rover, discovery, defender, g-class, mdx sport, rdx, qx50, outlander, outlander sport, eclipse cross'),
  ...K('Truck', 5, 'f-150, f150, f-250, silverado, silverado 1500, sierra, sierra 1500, ram 1500, 1500, 2500, tacoma, tundra, ranger, colorado, canyon, frontier, titan, maverick, ridgeline, gladiator, santa cruz, cybertruck, lightning'),
  ...K('Sedan', 5, 'camry, accord, civic, corolla, altima, sentra, versa, maxima, elantra, sonata, forte, k4, k5, optima, rio, malibu, impala, cruze, fusion, focus, taurus, mazda3, mazda 3, mazda6, mazda 6, jetta, passat, charger, 300, model 3, legacy, impreza, wrx, es, is, ls, avalon, a3, a4, a6, 3 series, 5 series, c-class, e-class, tlx, ilx, ct4, ct5, q50, g70, g80, s60, prius, insight, ioniq'),
  ...K('Hatchback', 5, 'mirage, fit, yaris, spark, bolt, bolt ev, golf, gti, veloster, leaf, 500, mini, cooper, versa note, accent, fiesta, sonic'),
  ...K('Sports car', 4, 'mustang, camaro, corvette, challenger, 911, miata, mx-5, mx-5 miata, brz, gr86, 86, supra, 370z, 350z, z, gt-r, m2, m4'),
];
const MINIVAN = /(odyssey|sienna|pacifica|carnival|sedona|caravan|town|quest|voyager|transit connect|promaster city|metris)/i;
const clean = (s: string) => s.toLowerCase().replace(/\s+/g, ' ').trim();

/** Kind from the list (no internet). Longest name that is the model or starts it ("Silverado 1500 LT" → Silverado 1500). */
export function kindFromName(model: string): CarKind | undefined {
  const m = clean(model);
  let best: [string, CarKind] | undefined;
  for (const e of TABLE) if ((m === e[0] || m.startsWith(`${e[0]} `)) && (!best || e[0].length > best[0].length)) best = e;
  return best?.[1];
}

/** Kind for any car: our own car data, then the list, then NHTSA. undefined when nobody knows. */
export async function kindOfCar(year: number, make: string, model: string): Promise<CarKind | undefined> {
  const listed = kindFromName(model);
  if (listed) return listed;
  const ours = carForMine(make, model);
  if (ours) return carKindOf(ours.body, ours.seats);
  const t = await vpicTypeOf(make === 'Chevy' ? 'Chevrolet' : make, year, model).catch(() => null);
  if (t === 'mpv') return MINIVAN.test(model) ? { kind: 'Minivan', seats: 7 } : { kind: 'SUV', seats: 5 };
  if (t === 'car') return { kind: 'Sedan', seats: 5 };
  if (t === 'truck') return { kind: 'Truck', seats: 5 };
  return undefined;
}

/** Our car data's body + seats as a coach kind. */
export function carKindOf(body: string, seats: number): CarKind {
  if (body === 'SUV' || body === 'Wagon') return { kind: seats >= 7 ? 'SUV (3 rows)' : 'SUV', seats };
  if (body === 'Sports car') return { kind: 'Sports car', seats };
  return { kind: (['Sedan', 'Truck', 'Minivan', 'Hatchback'].includes(body) ? body : 'Sedan') as KindLabel, seats };
}

/** Short words for a chat bubble: "an SUV with 3 rows, seats 7". */
export function kindWords(k: CarKind): string {
  switch (k.kind) {
    case 'SUV (3 rows)': return `an SUV with 3 rows, seats ${k.seats}`;
    case 'Minivan': return `a minivan, seats ${k.seats}`;
    case 'SUV': return 'an SUV';
    case 'Truck': return 'a truck';
    case 'Hatchback': return 'a hatchback';
    case 'Sports car': return 'a sports car';
    default: return 'a sedan';
  }
}

/** Seats a kind usually has, to know when someone picked smaller than their car. Electric/Hybrid = any size. */
export function seatsOfKind(kind?: string): number | undefined {
  return ({ SUV: 5, 'SUV (3 rows)': 7, Sedan: 5, Hatchback: 5, 'Sports car': 4, Minivan: 7 } as Record<string, number>)[kind ?? ''];
}
