export const DEFAULT_LOOK: ThemeName = 'showroom';
// Day and night versions of each look, for "Auto: follow my phone" (Oct 18, 2026).
// Oct 22, 2026 (Loudjier): only Clean turns to Clean night by itself, after sunset where the user is; every other look is picked by hand.
// Follow the day (picture 133, Oct 24, 2026): Clean, Sunset Calm, Sunset Calm night and Clean night take turns by the
// sun (data/sun.ts dayLookAt). The other four looks stay as picked.
export const FOLLOWS_DAY: ThemeName[] = ['clean', 'calm', 'calmNight', 'cleanNight', 'showroom', 'showroomNight'];
/** The day/night pair a dayLook stands for: the two night looks are 'dark'. */
const darkDay = (d: ThemeName) => d === 'calmNight' || d === 'cleanNight';
export const followsDay = (l: ThemeName) => FOLLOWS_DAY.includes(l);
// Picture 222 A (Nov 13, 2026, Loudjier: "Choose for me"): 4 colors, each with a light and a dark look, all in the new
// design. Auto = light in the day, dark after sunset where they are. White, Midnight and Trust Blue were retired:
// anyone on them is shown the closest color (Midnight → Gold dark, Trust Blue → Blue light).
export type ColorFam = 'gold' | 'blue' | 'green' | 'navy';
export const FAMILY: Record<ColorFam, [ThemeName, ThemeName]> = {
  gold: ['showroom', 'showroomNight'], blue: ['clean', 'cleanNight'], green: ['calm', 'calmNight'], navy: ['light', 'navy'],
};
export const famOf = (t: ThemeName): ColorFam =>
  t === 'clean' || t === 'cleanNight' || t === 'blue' ? 'blue' : t === 'calm' || t === 'calmNight' ? 'green' : t === 'light' || t === 'navy' ? 'navy' : 'gold';
/** The look to draw: their color, light or dark (on Auto by the sun where they are). */
export const lookNow = (picked: ThemeName, follow: boolean, dayLook: ThemeName): ThemeName => {
  const [light, dark] = FAMILY[famOf(picked)];
  if (follow) return darkDay(dayLook) ? dark : light;
  return isDarkLook(picked) ? dark : light;
};
// Older rule (Oct 22): only Clean turned to Clean night. Kept for the look tests of that rule.
const NIGHT_OF: Partial<Record<ThemeName, ThemeName>> = { clean: 'cleanNight' };
const DAY_OF: Partial<Record<ThemeName, ThemeName>> = Object.fromEntries(Object.entries(NIGHT_OF).map(([d, n]) => [n, d]));
/** The look to show on auto: Clean night when it's dark where they are, Clean when it's light. Other looks stay as picked. */
export const lookFor = (picked: ThemeName, phoneDark: boolean): ThemeName => (phoneDark ? NIGHT_OF[picked] ?? picked : DAY_OF[picked] ?? picked);
export const isDarkLook = (name: ThemeName) => name === 'showroomNight' || name === 'midnight' || name === 'navy' || name === 'calmNight' || name === 'cleanNight';
/** Looks with the soft Manrope style (round buttons, normal-case headings): Clean and Sunset Calm. */
// Loudjier, Oct 22, 2026: "when user change the look they get the clean version with the color they choose".
// Every look now uses the Clean layout; only the colors change.
export const isCalmLook = (_name: ThemeName) => true;
/** Only Sunset Calm draws the sky; Clean uses plain white headers. */
export const isSkyLook = (_name: ThemeName) => false;
/** The page color of a look, for the very first paint before the screens draw. */
export const pageOf = (name: ThemeName) => (PALETTES[name] ?? SHOWROOM).bg;

// One shared color object. Switching the look changes its values; the app then redraws
// from the top so every screen picks up the new colors.
export const C = { ...SHOWROOM };
export let theme: Mode = 'light';
/** The look picked on Me (theme above is just light or dark). */
export let look: ThemeName = 'showroom';
/** True for the Sunset Calm looks: Manrope everywhere, round buttons, the sky on top. */
export let calm = true;
/** True only for Sunset Calm (the sky on top). */
export let skyLook = false;
/** True for the Design 5 showroom looks (picture 200 day, picture 199 night). */
/** Picked chips and switches are black on the white day showroom (picture 208); gold-tinted elsewhere. */
export const pickedBg = () => (look === 'showroom' ? C.ink : C.fill);
export const pickedInk = () => (look === 'showroom' ? '#FFFFFF' : C.onAccent);
// Design 5 layout for EVERY look, each in its own colors (Loudjier, Nov 12, 2026: 'I need the new design to be
// available for every color option'). The name stays so older code reads the same.
export const isShowroom = () => true;
export const isShowroomColors = () => look === 'showroom' || look === 'showroomNight';
// After a switch the app redraws from the start; this sends the person back where they were.
let resumeRoute: string | null = null;
export const resumeAt = (route: string | null) => { resumeRoute = route; };
export const takeResume = () => { const r = resumeRoute; resumeRoute = null; return r; };
let version = 0;
export function applyTheme(name: ThemeName) {
  if (!PALETTES[name]) name = DEFAULT_LOOK;
  if (name === look) return;
  Object.assign(C, PALETTES[name]);
  look = name;
  theme = isDarkLook(name) ? 'midnight' : 'light';
  calm = isCalmLook(name);
  skyLook = isSkyLook(name);
  Object.assign(F, calm ? CALM_FONTS : CLASSIC_FONTS);
  version++;
}

// Styles that follow the look: built on first use and again after each switch.
export function themed<T extends object>(make: () => T): T {
  let made = -1;
  let cache = {} as T;
  return new Proxy({} as T, {
    get(_t, key) {
      if (made !== version) { cache = make(); made = version; }
      return cache[key as keyof T];
    },
  });
}

