// Picture 238 A (Nov 13, 2026): the Filters button (with how many are on), the picked filters as ✕ chips, and the
// full Filters page: sections that open and close, min/max year and price, and a "Show N cars" button that counts.
import { useMemo, useState } from 'react';
import { Modal, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Circle, Path } from 'react-native-svg';

import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { OLDEST_YEAR } from '@/data/cars';
import { LATEST_MODEL_YEAR } from '@/data/year';
import { bodyLabel, BODIES, filterChips, filterCount, FUELS, MAKES, MUSTS, NO_FILTERS, PRICE_STEPS, SEATS, type Filters } from '@/data/filters';
import { tr } from '@/i18n';
import { C, F, isDarkLook, look, themed } from '@/theme';

const YEARS = Array.from({ length: LATEST_MODEL_YEAR - OLDEST_YEAR + 1 }, (_, i) => LATEST_MODEL_YEAR - i);
const k = (n: number) => `$${(n / 1000).toFixed(0)}K`;
const MUST_LABEL: Record<string, string> = { '4x4 / AWD': 'AWD / 4x4', 'Third row': '3rd row' };

/** The Filters button + the chips of the filters that are on (tap ✕ to remove one). */
export function FilterBar({ value, onChange, count, right }: { value: Filters; onChange: (f: Filters) => void; count: (f: Filters) => number; right?: React.ReactNode }) {
  const [open, setOpen] = useState(false);
  const n = filterCount(value);
  const chips = filterChips(value);
  return (
    <View>
      <View style={s.bar}>
        <Pressable onPress={() => { tap(); setOpen(true); }} accessibilityRole="button" accessibilityLabel={`${tr('Filters')}${n ? `, ${n} ${tr('on')}` : ''}`} style={s.btn}>
          <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.ink} strokeWidth={2.2} strokeLinecap="round">
            <Path d="M4 6h10M18 6h2M4 12h4M12 12h8M4 18h12M20 18h0" /><Circle cx="16" cy="6" r="2" /><Circle cx="10" cy="12" r="2" /><Circle cx="18" cy="18" r="2" />
          </Svg>
          <Text style={s.btnT}>Filters</Text>
          {n > 0 && <View style={s.badge}><Text style={s.badgeT}>{String(n)}</Text></View>}
        </Pressable>
        {right}
      </View>
      {chips.length > 0 && (
        <View style={s.chips}>
          {chips.map((c) => (
            <Pressable key={c.label} onPress={() => { tap(); onChange(c.remove(value)); }} accessibilityRole="button" accessibilityLabel={`${tr('Remove')} ${tr(c.label)}`} style={[s.chip, s.chipOn]}>
              <Text style={[s.chipT, { color: C.onAccent }]}>{`${c.label}  ✕`}</Text>
            </Pressable>
          ))}
        </View>
      )}
      <FilterPage visible={open} value={value} count={count} onClose={() => setOpen(false)} onApply={(f) => { onChange(f); setOpen(false); }} />
    </View>
  );
}

function Section({ title, sub, open, onToggle, children }: { title: string; sub?: string; open: boolean; onToggle: () => void; children: React.ReactNode }) {
  return (
    <View style={s.sec}>
      <Pressable onPress={() => { tap(); onToggle(); }} accessibilityRole="button" accessibilityState={{ expanded: open }} style={s.secHead}>
        <View style={{ flex: 1 }}>
          <Text style={s.secT}>{title}</Text>
          {!!sub && !open && <Text style={s.secSub} numberOfLines={1}>{sub}</Text>}
        </View>
        <Svg width={18} height={18} viewBox="0 0 24 24" fill="none" stroke={C.muted} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round">
          <Path d={open ? 'M6 15l6-6 6 6' : 'M6 9l6 6 6-6'} />
        </Svg>
      </Pressable>
      {open && <View style={{ paddingBottom: 14 }}>{children}</View>}
    </View>
  );
}

function Chips<T extends string | number>({ items, on, toggle, label }: { items: readonly T[]; on: (v: T) => boolean; toggle: (v: T) => void; label?: (v: T) => string }) {
  return (
    <View style={s.chips}>
      {items.map((v) => (
        <Pressable key={String(v)} onPress={() => { tap(); toggle(v); }} accessibilityRole="button" accessibilityState={{ selected: on(v) }} style={[s.chip, on(v) && s.chipOn]}>
          <Text style={[s.chipT, on(v) && { color: C.onAccent }]}>{label ? label(v) : String(v)}</Text>
        </Pressable>
      ))}
    </View>
  );
}

/** A min or max box: tap it and the choices open under it as chips. */
function PickBox({ label, value, open, onOpen }: { label: string; value: string; open: boolean; onOpen: () => void }) {
  return (
    <Pressable onPress={() => { tap(); onOpen(); }} accessibilityRole="button" accessibilityLabel={`${tr(label)}: ${tr(value)}`} style={[s.box, open && s.boxOn]}>
      <View style={{ flex: 1 }}>
        <Text style={s.boxL}>{label}</Text>
        <Text style={s.boxV} numberOfLines={1}>{value}</Text>
      </View>
      <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.muted} strokeWidth={2.4} strokeLinecap="round"><Path d={open ? 'M6 15l6-6 6 6' : 'M6 9l6 6 6-6'} /></Svg>
    </Pressable>
  );
}

function FilterPage({ visible, value, count, onClose, onApply }: { visible: boolean; value: Filters; count: (f: Filters) => number; onClose: () => void; onApply: (f: Filters) => void }) {
  const [f, setF] = useState<Filters>(value);
  const [seen, setSeen] = useState(visible);
  if (visible !== seen) { setSeen(visible); if (visible) setF(value); } // start from what's on each time it opens
  const [open, setOpen] = useState<string | null>('body');
  const [box, setBox] = useState<string | null>(null);
  const n = useMemo(() => count(f), [count, f]);
  const tog = <T,>(list: T[], v: T) => (list.includes(v) ? list.filter((x) => x !== v) : [...list, v]);
  const sec = (id: string) => ({ open: open === id, onToggle: () => setOpen(open === id ? null : id) });
  const night = isDarkLook(look);

  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      <SafeAreaView style={{ flex: 1, backgroundColor: C.bg }}>
        <View style={s.top}>
          <Pressable onPress={() => { tap(); onClose(); }} accessibilityRole="button" accessibilityLabel={tr('Close')} hitSlop={8} style={s.x}>
            <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.ink} strokeWidth={2.6} strokeLinecap="round"><Path d="M6 6l12 12M18 6L6 18" /></Svg>
          </Pressable>
          <Text style={s.title} accessibilityRole="header">Filters</Text>
          <Pressable onPress={() => { tap(); setF(NO_FILTERS); setBox(null); }} accessibilityRole="button" hitSlop={8}>
            <Text style={[s.clear, filterCount(f) === 0 && { opacity: 0.4 }]}>Clear all</Text>
          </Pressable>
        </View>
        <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingBottom: 120 }}>
          <Section title="New or used" sub={f.newUsed} {...sec('nu')}>
            <Chips items={['New', 'Used'] as const} on={(v) => f.newUsed === v} toggle={(v) => setF({ ...f, newUsed: f.newUsed === v ? undefined : v })} />
          </Section>
          <Section title="Make" sub={f.makes.join(', ')} {...sec('make')}>
            <Chips items={MAKES} on={(v) => f.makes.includes(v)} toggle={(v) => setF({ ...f, makes: tog(f.makes, v) })} />
          </Section>

          <View style={s.two}>
            <PickBox label="Min year" value={f.yearMin ? String(f.yearMin) : 'Oldest'} open={box === 'ymin'} onOpen={() => setBox(box === 'ymin' ? null : 'ymin')} />
            <PickBox label="Max year" value={f.yearMax ? String(f.yearMax) : 'Newest'} open={box === 'ymax'} onOpen={() => setBox(box === 'ymax' ? null : 'ymax')} />
          </View>
          {(box === 'ymin' || box === 'ymax') && (
            <Chips items={YEARS} on={(v) => (box === 'ymin' ? f.yearMin : f.yearMax) === v}
              toggle={(v) => { setF(box === 'ymin' ? { ...f, yearMin: f.yearMin === v ? undefined : v, yearMax: f.yearMax && f.yearMax < v ? undefined : f.yearMax } : { ...f, yearMax: f.yearMax === v ? undefined : v, yearMin: f.yearMin && f.yearMin > v ? undefined : f.yearMin }); setBox(null); }} />
          )}
          <View style={s.two}>
            <PickBox label="Min price" value={f.priceMin ? k(f.priceMin) : 'Lowest'} open={box === 'pmin'} onOpen={() => setBox(box === 'pmin' ? null : 'pmin')} />
            <PickBox label="Max price" value={f.priceMax ? k(f.priceMax) : 'Highest'} open={box === 'pmax'} onOpen={() => setBox(box === 'pmax' ? null : 'pmax')} />
          </View>
          {(box === 'pmin' || box === 'pmax') && (
            <Chips items={PRICE_STEPS} label={k} on={(v) => (box === 'pmin' ? f.priceMin : f.priceMax) === v}
              toggle={(v) => { setF(box === 'pmin' ? { ...f, priceMin: f.priceMin === v ? undefined : v, priceMax: f.priceMax && f.priceMax < v ? undefined : f.priceMax } : { ...f, priceMax: f.priceMax === v ? undefined : v, priceMin: f.priceMin && f.priceMin > v ? undefined : f.priceMin }); setBox(null); }} />
          )}

          <Section title="Body type" sub={f.bodies.map(bodyLabel).join(', ')} {...sec('body')}>
            <Chips items={BODIES} label={bodyLabel} on={(v) => f.bodies.includes(v)} toggle={(v) => setF({ ...f, bodies: tog(f.bodies, v) })} />
          </Section>
          <Section title="Fuel" sub={f.fuels.join(', ')} {...sec('fuel')}>
            <Chips items={FUELS} on={(v) => f.fuels.includes(v)} toggle={(v) => setF({ ...f, fuels: tog(f.fuels, v) })} />
          </Section>
          <Section title="Seats" sub={f.seats ? `${f.seats}+` : undefined} {...sec('seats')}>
            <Chips items={SEATS} label={(v) => `${v}+`} on={(v) => f.seats === v} toggle={(v) => setF({ ...f, seats: f.seats === v ? undefined : v })} />
          </Section>
          <Section title="Must-haves" sub={f.must.map((m) => MUST_LABEL[m] ?? m).join(', ')} {...sec('must')}>
            <Chips items={MUSTS} label={(v) => MUST_LABEL[v] ?? v} on={(v) => f.must.includes(v)} toggle={(v) => setF({ ...f, must: tog(f.must, v) })} />
            <Text style={s.hint}>Counts when it comes on the car or on some versions. Older years (before 2020): check the car.</Text>
          </Section>
          <Section title="Safety and gas mileage" sub={[f.safe5 && '5★ safety', f.mpg33 && 'Over 33 MPG'].filter(Boolean).join(', ')} {...sec('safe')}>
            <Chips items={['5★ safety (NHTSA)', 'Over 33 MPG (EPA)'] as const}
              on={(v) => (v.startsWith('5') ? !!f.safe5 : !!f.mpg33)}
              toggle={(v) => setF(v.startsWith('5') ? { ...f, safe5: f.safe5 ? undefined : true } : { ...f, mpg33: f.mpg33 ? undefined : true })} />
          </Section>
          <Text style={s.hint}>Prices are our estimates. Mileage, colors and deal ratings are on “Cars for sale near you”.</Text>
        </ScrollView>
        <View style={s.sticky}>
          <Pressable onPress={() => { tap(); onApply(f); }} accessibilityRole="button" style={[s.go, n === 0 && { opacity: 0.6 }]}>
            <Text style={[s.goT, { color: night ? '#0D1626' : '#fff' }]}>{n === 0 ? 'No cars match' : `Show ${n} car${n === 1 ? '' : 's'}`}</Text>
          </Pressable>
        </View>
      </SafeAreaView>
    </Modal>
  );
}

const s = themed(() => StyleSheet.create({
  bar: { flexDirection: 'row', flexWrap: 'wrap', gap: 8, alignItems: 'center' },
  btn: { flexDirection: 'row', alignItems: 'center', gap: 6, backgroundColor: C.card, borderRadius: 999, paddingHorizontal: 14, paddingVertical: 9, borderWidth: 1, borderColor: C.line },
  btnT: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink },
  badge: { minWidth: 20, height: 20, borderRadius: 10, paddingHorizontal: 5, backgroundColor: isDarkLook(look) ? '#9CC0F7' : '#1F5FBF', alignItems: 'center', justifyContent: 'center' },
  badgeT: { fontFamily: F.bodyBold, fontSize: 11.5, color: isDarkLook(look) ? '#0D1626' : '#fff' },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 7, marginTop: 10 },
  chip: { borderRadius: 999, paddingHorizontal: 13, paddingVertical: 8, backgroundColor: C.card, borderWidth: 1.5, borderColor: C.line },
  chipOn: { backgroundColor: C.fill, borderColor: C.fill },
  chipT: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.ink },
  top: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 20, paddingVertical: 12 },
  x: { width: 38, height: 38, borderRadius: 19, backgroundColor: C.card, alignItems: 'center', justifyContent: 'center', shadowColor: '#000', shadowOpacity: 0.08, shadowRadius: 6, shadowOffset: { width: 0, height: 2 }, elevation: 2 },
  title: { fontFamily: F.head, fontSize: 19, color: C.ink },
  clear: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.yellow },
  sec: { borderBottomWidth: 1, borderBottomColor: C.line },
  secHead: { flexDirection: 'row', alignItems: 'center', paddingVertical: 16 },
  secT: { fontFamily: F.bodyBold, fontSize: 16.5, color: C.ink },
  secSub: { fontFamily: F.body, fontSize: 12.5, color: C.onAccent, marginTop: 2 },
  two: { flexDirection: 'row', gap: 10, paddingTop: 14 },
  box: { flex: 1, flexDirection: 'row', alignItems: 'center', backgroundColor: C.card, borderRadius: 14, borderWidth: 1.5, borderColor: C.line, paddingHorizontal: 12, paddingVertical: 8 },
  boxOn: { borderColor: C.yellow },
  boxL: { fontFamily: F.body, fontSize: 11.5, color: C.muted },
  boxV: { fontFamily: F.bodyBold, fontSize: 15.5, color: C.ink },
  hint: { fontFamily: F.body, fontSize: 12, lineHeight: 17, color: C.muted, marginTop: 10 },
  sticky: { position: 'absolute', left: 0, right: 0, bottom: 0, padding: 16, paddingBottom: 28, backgroundColor: C.bg, borderTopWidth: 1, borderTopColor: C.line },
  go: { borderRadius: 999, paddingVertical: 15, alignItems: 'center', backgroundColor: isDarkLook(look) ? '#9CC0F7' : '#1F5FBF' },
  goT: { fontFamily: F.bodyBold, fontSize: 16 },
}));
