// Keeps the home screen widgets up to date while the app is open (Android only): when the cars, miles,
// language or weather change, it writes one small snapshot and asks Android to redraw every Carvessa widget.
import { useCallback, useEffect, useRef, useState } from 'react';
import { AppState } from 'react-native';

import { useSunPlace } from '@/components/sky';
import { recallsForMyCar } from '@/data/gov';
import { getWeather, skyWord, type Weather } from '@/data/weather';
import { lang } from '@/i18n';
import { hasWidgets } from '@/lib/widget-native';
import { zipToPlace } from '@/data/dealers';
import { CARS } from '@/data/cars';
import { priceFor } from '@/data/prices';
import { monthlyCap, paymentFor, topMatches, useAnswers, type Answers } from '@/state/answers';
import { useAuth } from '@/state/auth';
import { useSaved, type MyCar } from '@/state/saved';
import { GARAGE_KEY, readNum, TIP_KEY, readSnap, tipsFor, weatherTip, widgetCar, writeSnap, type NextCar, type WidgetSnap } from './data';
import { readPark, readTrips, readWeek } from './more';
import { bothLooks, plainCard, WIDGETS, type Extra } from './widgets';
import { dayNumber, withTimeout } from './task-handler';

const recallCache = new Map<string, number>();
async function recallCount(c: MyCar): Promise<number | null> {
  const key = `${c.make}|${c.model}|${c.year}`;
  if (recallCache.has(key)) return recallCache.get(key)!;
  try {
    const n = (await recallsForMyCar(c.make, c.model, c.year)).length;
    recallCache.set(key, n);
    return n;
  } catch {
    return null;
  }
}

const placeCache = new Map<string, string>();
/** 'Decatur' from the coach ZIP, for the weather widget (blank without a ZIP). */
async function placeOf(zip: string): Promise<string> {
  if (!zip) return '';
  if (!placeCache.has(zip)) {
    try { placeCache.set(zip, (await zipToPlace(zip)).place.split(',')[0]); } catch { return ''; }
  }
  return placeCache.get(zip) ?? '';
}

/** The car they want next (W): their newest saved car, else the coach's #1 (only after the coach). */
export function nextCarOf(saved: { id: string; year: number; at: number }[], a: Answers): NextCar | undefined {
  const pick = [...saved].sort((x, y) => y.at - x.at)[0];
  let car = pick ? CARS.find((c) => c.id === pick.id) : undefined;
  let year = pick?.year;
  if (!car && a.goal) {
    const m = topMatches(a, 1)[0];
    if (m) { car = m.car; year = m.year; }
  }
  if (!car || !year) return undefined;
  const pr = priceFor(car, year);
  if (!pr) return undefined;
  const cap = monthlyCap(a);
  const monthly = a.goal ? paymentFor(a, pr.amount, pr.isNew) : undefined;
  return { name: `${year} ${car.make} ${car.model}`, id: car.id, year, price: Math.round(pr.amount), isNew: pr.isNew, monthly,
    over: cap && monthly ? Math.max(0, monthly - cap) : undefined };
}

/** Redraw every Carvessa widget on the home screen from this snapshot. */
export async function redrawWidgets(s: WidgetSnap | null) {
  if (!hasWidgets()) return;
  try {
    const { requestWidgetUpdate } = require('react-native-android-widget') as typeof import('react-native-android-widget');
    const now = Date.now();
    const x: Extra = { now, week: await readWeek(now), park: await readPark(), trips: await readTrips() };
    const garage = await readNum(GARAGE_KEY);
    const tip = await readNum(TIP_KEY);
    for (const name of WIDGETS) {
      await requestWidgetUpdate({ widgetName: name, renderWidget: (info) => {
        try {
          return bothLooks(name, s, name === 'Garage' ? garage : name === 'Tip' ? tip : 0, dayNumber(), { w: info.width, h: info.height }, x);
        } catch (e) {
          return plainCard('Carvessa', 'Open Carvessa, then come back.', `Widget error: ${String((e as Error)?.message ?? e).slice(0, 120)}`);
        }
      } }).catch(() => {});
    }
  } catch {
    // An older app file without the widget module: nothing to do.
  }
}

export function WidgetSync() {
  const { myCars, activeCar, ready, saved } = useSaved();
  const { session } = useAuth();
  const user = session?.user ?? null;
  const { answers } = useAnswers();
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  const { spot } = useSunPlace();
  const [lat, lon] = [Math.round(spot.lat * 100) / 100, Math.round(spot.lon * 100) / 100];
  const [tick, setTick] = useStateTick();
  const last = useRef('');

  useEffect(() => {
    if (!hasWidgets() || !ready) return;
    let on = true;
    (async () => {
      const now = Date.now();
      // Draw right away with what we know (recalls still checking), then again with recalls and weather.
      const old0 = await readSnap();
      const quick: WidgetSnap = { at: now, lang, member: !!user, cars: myCars.map((c) => widgetCar(c, recallCache.get(`${c.make}|${c.model}|${c.year}`) ?? null, now)),
        active: Math.min(activeCar, Math.max(0, myCars.length - 1)), tips: tipsFor(myCars[activeCar] ?? null, new Date(now).getMonth()), spot: old0?.spot, weather: old0?.weather };
      if (on && !last.current) { await writeSnap(quick); await redrawWidgets(quick); }
      const counts = await Promise.all(myCars.map((c) => withTimeout(recallCount(c), 12000, null)));
      const cars = myCars.map((c, i) => widgetCar(c, counts[i], now));
      const old = await readSnap();
      let weather = old?.weather;
      try {
        const w = await withTimeout<Weather | null>(getWeather(lat, lon), 10000, null);
        if (!w) throw new Error('slow');
        const short = cars[activeCar]?.short ?? 'car';
        weather = { tempF: w.tempF, sky: w.sky, isDay: w.isDay, word: skyWord(w.sky, !w.isDay), at: now, tip: weatherTip(w.tempF, w.sky, short) };
      } catch { /* keep the last weather */ }
      const snap: WidgetSnap = {
        at: now, lang, member: !!user, cars, active: Math.min(activeCar, Math.max(0, cars.length - 1)),
        tips: tipsFor(myCars[activeCar] ?? null, new Date(now).getMonth()),
        spot: { lat, lon, place: await withTimeout(placeOf(zip), 6000, '') },
        weather,
        next: nextCarOf(saved, answers),
        driver: answers.goal === 'Drive for apps',
      };
      const key = JSON.stringify({ ...snap, at: 0, weather: snap.weather ? { ...snap.weather, at: 0 } : null });
      if (!on || key === last.current) return;
      last.current = key;
      await writeSnap(snap);
      await redrawWidgets(snap);
    })();
    return () => { on = false; };
  }, [ready, myCars, activeCar, user, lat, lon, zip, tick, saved, answers]); // eslint-disable-line react-hooks/exhaustive-deps

  // Coming back to the app (e.g. the next morning) refreshes miles, oil and weather.
  useEffect(() => {
    const sub = AppState.addEventListener('change', (st) => { if (st === 'active') setTick(); });
    return () => sub.remove();
  }, [setTick]);
  return null;
}

function useStateTick(): [number, () => void] {
  const [n, setN] = useState(0);
  return [n, useCallback(() => setN((x) => x + 1), [])];
}
