// Sunrise and sunset for a place and day (NOAA's simple sun formula, good to a few minutes).
// The Sunset Calm sky uses it to follow the time of day (Loudjier said yes, Oct 18, 2026).

export type SkyPhase = 'morning' | 'day' | 'evening' | 'night';

/** Atlanta, used until we know the person's ZIP. */
export const ATLANTA = { lat: 33.749, lon: -84.388 };

const rad = Math.PI / 180;

/** Sunrise and sunset (ms timestamps) on the calendar day of `when` (phone's local date). */
export function sunTimes(when: Date, lat: number, lon: number): { rise: number; set: number } | null {
  const start = Date.UTC(when.getFullYear(), 0, 1);
  const day = Math.floor((Date.UTC(when.getFullYear(), when.getMonth(), when.getDate()) - start) / 864e5) + 1;
  const g = ((2 * Math.PI) / 365) * (day - 1);
  const eq = 229.18 * (0.000075 + 0.001868 * Math.cos(g) - 0.032077 * Math.sin(g) - 0.014615 * Math.cos(2 * g) - 0.040849 * Math.sin(2 * g));
  const decl = 0.006918 - 0.399912 * Math.cos(g) + 0.070257 * Math.sin(g) - 0.006758 * Math.cos(2 * g)
    + 0.000907 * Math.sin(2 * g) - 0.002697 * Math.cos(3 * g) + 0.00148 * Math.sin(3 * g);
  const cosHa = Math.cos(90.833 * rad) / (Math.cos(lat * rad) * Math.cos(decl)) - Math.tan(lat * rad) * Math.tan(decl);
  if (cosHa > 1 || cosHa < -1) return null; // polar day or night
  const ha = Math.acos(cosHa) / rad;
  const midnight = Date.UTC(when.getFullYear(), when.getMonth(), when.getDate());
  return {
    rise: midnight + (720 - 4 * (lon + ha) - eq) * 6e4,
    set: midnight + (720 - 4 * (lon - ha) - eq) * 6e4,
  };
}

/**
 * Which sky to show: morning from just before sunrise to about 2½ hours after, evening from
 * 1½ hours before sunset to 40 minutes after, night in between, day the rest.
 */
export function phaseAt(when: Date, lat = ATLANTA.lat, lon = ATLANTA.lon): SkyPhase {
  const t = sunTimes(when, lat, lon);
  if (!t) return 'day';
  const now = when.getTime();
  const min = 6e4;
  if (now < t.rise - 40 * min || now > t.set + 40 * min) return 'night';
  if (now < t.rise + 150 * min) return 'morning';
  if (now > t.set - 90 * min) return 'evening';
  return 'day';
}

/** Dark where they are: from 20 minutes after sunset to 20 minutes before sunrise (Clean → Clean night). */
export function isDarkAt(when: Date, lat = ATLANTA.lat, lon = ATLANTA.lon): boolean {
  const t = sunTimes(when, lat, lon);
  if (!t) return false;
  const now = when.getTime();
  return now < t.rise - 20 * 6e4 || now > t.set + 20 * 6e4;
}

// Follow the day (picture 133, Oct 24, 2026, Loudjier: "Clean is for morning. Clean night is for night. Sunset Calm
// is for sunset. Sunset Calm night is for sunset calm night."). The four looks take turns by the real sun:
// Clean from 20 min before sunrise; Sunset Calm from 1 hour before sunset to 20 min after; Sunset Calm night
// until 11 PM; Clean night until morning.
export type DayLook = 'clean' | 'calm' | 'calmNight' | 'cleanNight';
export const DAY_LOOKS: DayLook[] = ['clean', 'calm', 'calmNight', 'cleanNight'];
export const NIGHT_END_HOUR = 23; // Sunset Calm night ends at 11 PM (phone time)

export type DayPlan = { look: DayLook; from: number; to: number }[];

/** Today's four turns (times in ms). The last one runs into tomorrow morning. */
export function dayPlan(when: Date, lat = ATLANTA.lat, lon = ATLANTA.lon): DayPlan | null {
  const t = sunTimes(when, lat, lon);
  if (!t) return null;
  const m = 6e4;
  const end = new Date(when); end.setHours(NIGHT_END_HOUR, 0, 0, 0);
  const lateFrom = Math.max(end.getTime(), t.set + 20 * m);
  return [
    { look: 'clean', from: t.rise - 20 * m, to: t.set - 60 * m },
    { look: 'calm', from: t.set - 60 * m, to: t.set + 20 * m },
    { look: 'calmNight', from: t.set + 20 * m, to: lateFrom },
    { look: 'cleanNight', from: lateFrom, to: t.rise - 20 * m + 24 * 60 * m },
  ];
}

/** Which of the four looks it is now where they are. No sunrise that day (far north): Clean. */
export function dayLookAt(when: Date, lat = ATLANTA.lat, lon = ATLANTA.lon): DayLook {
  const p = dayPlan(when, lat, lon);
  if (!p) return 'clean';
  const now = when.getTime();
  if (now < p[0].from) return 'cleanNight'; // after midnight, before morning
  return p.find((x) => now >= x.from && now < x.to)?.look ?? 'cleanNight';
}
