// Insurance helper (picture 167 screens 11b + 11c, Oct 30, 2026), no partners yet:
// pick your own insurance company (or type it), then everything they'll ask for is ready: VIN, miles, lender, ZIP.
// We send the insurer nothing: the person opens their insurer's own site or app, or calls.
// Names only, never logos. Partner cards ("Works with Carvessa") come only after real partners sign.
import { router } from 'expo-router';
import { useState } from 'react';
import { KeyboardAvoidingView, Linking, Platform, ScrollView, Share, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BigBtn, Card, ToggleRow } from '@/components/account-ui';
import { BellIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text, TextInput } from '@/components/t';
import { Body, Label, tap } from '@/components/ui';
import { estMiles, findInsurers, INSURERS } from '@/data/car-plan';
import { isVin } from '@/data/check';
import { carName } from '@/data/my-cars';
import { tr } from '@/i18n';
import { canRemind } from '@/lib/reminders';
import { useAnswers } from '@/state/answers';
import { useAuth } from '@/state/auth';
import { useSaved } from '@/state/saved';
import { C, calm, F, PAD, themed } from '@/theme';

const parseDate = (t: string) => /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(t.trim());
// The pickup-day reminder only makes sense for a day still ahead.
const future = (t?: string) => { const m = t?.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/); return !!m && new Date(Number(m[3]), Number(m[1]) - 1, Number(m[2]), 9).getTime() > Date.now(); };

function Line({ k, v, last }: { k: string; v: string; last?: boolean }) {
  return (
    <View style={[s.row, !last && s.line]}>
      <Text style={s.k}>{k}</Text>
      <Text style={s.v} selectable>{v}</Text>
    </View>
  );
}

function Pick({ onPick }: { onPick: (name: string) => void }) {
  const [q, setQ] = useState('');
  const [typing, setTyping] = useState(false);
  const found = findInsurers(q);
  const row = (name: string, i: number, n: number) => (
    <Pressable key={name} onPress={() => { tap(); onPick(name); }} accessibilityRole="button" style={[s.row, i < n - 1 && s.line]}>
      <Text style={s.name}>{name}</Text><Text style={s.chev}>›</Text>
    </Pressable>
  );
  return (<>
    <TextInput value={q} onChangeText={setQ} placeholder="Search your insurance company" placeholderTextColor={C.muted} accessibilityLabel="Search your insurance company" style={s.search} autoCorrect={false} />
    {q.trim() ? (
      <Card style={{ marginTop: 8 }}>
        {found.map((x, i) => row(x.name, i, found.length + 1))}
        <Pressable onPress={() => { tap(); onPick(q.trim()); }} accessibilityRole="button" style={s.row}>
          <Text style={[s.name, { color: C.yellow }]}>{`Use “${q.trim()}”`}</Text><Text style={s.chev}>›</Text>
        </Pressable>
      </Card>
    ) : (<>
      <Label style={s.sec}>Pick yours</Label>
      <Card>{INSURERS.slice(0, 8).map((x, i) => row(x.name, i, 9))}
        <Pressable onPress={() => { tap(); setTyping(true); }} accessibilityRole="button" style={s.row}>
          <Text style={[s.name, { color: C.yellow }]}>{typing ? 'Type its name in the search box above' : 'Mine isn’t here: type it'}</Text><Text style={s.chev}>›</Text>
        </Pressable>
      </Card>
      <Card style={{ marginTop: 12, paddingVertical: 14 }}>
        <Body bold>I don’t have insurance yet</Body>
        <Body style={s.small}>Ask 2–3 companies for a quote before pickup day. Have the car’s VIN ready: it’s on the window sticker or the dealer’s papers. The agent gives you prices and advice, not Carvessa.</Body>
      </Card>
      <Body style={[s.small, { marginTop: 10 }]}>Names only, no logos. Carvessa isn’t connected to these companies.</Body>
    </>)}
  </>);
}

export default function InsureScreen() {
  const { myCar, setMyCar } = useSaved();
  const { answers } = useAnswers();
  const { session, askAccount } = useAuth();
  const [now] = useState(() => Date.now());
  const [changing, setChanging] = useState(false);
  const [vin, setVin] = useState(myCar?.vin ?? '');
  const [bought, setBought] = useState(myCar?.boughtOn ?? '');
  const back = () => router.navigate('/garage');
  const company = !changing ? myCar?.insurer : undefined;
  const site = INSURERS.find((x) => x.name === company)?.site;
  const miles = myCar ? estMiles(myCar, now) : null;

  const saveDetails = () => {
    if (!myCar) return;
    const v = vin.trim().toUpperCase();
    if (v && !isVin(v)) return notify('Check the VIN', 'A VIN has 17 letters and numbers (no I, O or Q). It’s on the window sticker or the dealer’s papers.');
    if (bought.trim() && !parseDate(bought)) return notify('Check the date', 'Use month/day/year, like 11/14/2026.');
    tap();
    setMyCar({ ...myCar, vin: v || undefined, boughtOn: bought.trim() || undefined });
    notify('Saved', 'Your car details are ready.');
  };
  const share = () => {
    if (!myCar) return;
    const lines = [
      `${tr('Car')}: ${carName(myCar)}`,
      myCar.vin ? `VIN: ${myCar.vin}` : '',
      miles ? `${tr('Miles')}: ${miles.toLocaleString('en-US')}` : '',
      myCar.boughtOn ? `${tr('Bought on')}: ${myCar.boughtOn}` : '',
      myCar.loan?.lender ? `${tr('Lender')}: ${myCar.loan.lender}` : '',
      answers.zip ? `${tr('Where it’s parked')}: ZIP ${answers.zip}` : '',
    ].filter(Boolean);
    Share.share({ message: lines.join('\n') }).catch(() => {});
  };
  const open = () => {
    tap();
    Linking.openURL(site ?? `https://www.google.com/search?q=${encodeURIComponent(`${company} car insurance`)}`).catch(() => {});
  };

  let body: React.ReactNode;
  if (!myCar) {
    body = (
      <Card style={{ paddingVertical: 16 }}>
        <Body bold>Add your car first</Body>
        <Body style={s.small}>The car you bought (or are about to pick up) goes in My Garage.</Body>
        <View style={{ marginTop: 12 }}><BigBtn label="Go to My Garage" onPress={back} /></View>
      </Card>
    );
  } else if (!company) {
    body = <Pick onPick={(name) => { setMyCar({ ...myCar, insurer: name, insured: false }); setChanging(false); }} />;
  } else {
    body = (<>
      {myCar.insured && (
        <View style={s.done}><Text style={s.doneT}>✓ Your car is insured. That step is done.</Text></View>
      )}
      <Card style={{ paddingVertical: 6 }}>
        <Body bold style={{ marginTop: 8 }}>Have these ready</Body>
        <Line k="Car" v={carName(myCar)} />
        <Line k="VIN" v={myCar.vin ?? 'Add it below'} />
        <Line k="Miles" v={miles ? miles.toLocaleString('en-US') : 'Add them in My Garage'} />
        <Line k="Bought on" v={myCar.boughtOn ?? 'Add it below'} />
        {!!myCar.loan?.lender && <Line k="Lender" v={myCar.loan.lender} />}
        <Line k="Where it’s parked" v={answers.zip ? `ZIP ${answers.zip}` : 'Your home ZIP'} last />
      </Card>
      <View style={{ gap: 8, marginTop: 12 }}>
        <BigBtn label={site ? `Open ${company}’s site ↗` : `Find ${company} online ↗`} onPress={open} />
        <BigBtn label="Share these details" kind="soft" onPress={share} />
      </View>
      <Card style={{ marginTop: 12, paddingVertical: 12 }}>
        <View style={s.two}>
          <View style={{ flex: 1.5 }}>
            <Label style={s.fl}>VIN (17 LETTERS AND NUMBERS)</Label>
            <TextInput value={vin} onChangeText={setVin} placeholder="2T3RWRFV…" placeholderTextColor={C.muted} autoCapitalize="characters" autoCorrect={false} accessibilityLabel="VIN" style={s.input} />
          </View>
          <View style={{ flex: 1 }}>
            <Label style={s.fl}>BOUGHT ON</Label>
            <TextInput value={bought} onChangeText={setBought} placeholder="11/14/2026" placeholderTextColor={C.muted} accessibilityLabel="Bought on" style={s.input} />
          </View>
        </View>
        <View style={{ marginTop: 10 }}><BigBtn label="Save details" kind="plain" onPress={saveDetails} /></View>
      </Card>
      {!myCar.insured && future(myCar.boughtOn) && (
        <Card style={{ marginTop: 12 }}>
          <ToggleRow last icon={(c) => <BellIcon size={18} color={c} />} label="Remind me on pickup day" sub={`${myCar.boughtOn}, 9 AM`} on={!!session && myCar.insureRemind !== false}
            onChange={async (v) => {
              if (!session) return askAccount('Get a pickup-day reminder', 'Free account. We remind you to insure the car before you drive it home.');
              if (v && Platform.OS !== 'web' && !(await canRemind(true))) return notify('Reminders are off', 'Alerts are off for Carvessa in your phone settings. Turn them on there, then try again.');
              setMyCar({ ...myCar, insureRemind: v });
            }} />
        </Card>
      )}
      <View style={{ gap: 8, marginTop: 12 }}>
        {!myCar.insured && <BigBtn label="✓ Done, my car is insured" kind="plain" onPress={() => { tap(); setMyCar({ ...myCar, insured: true }); }} />}
        <Pressable onPress={() => { tap(); setChanging(true); }} accessibilityRole="button" style={{ alignSelf: 'center', padding: 8 }}>
          <Text style={s.link}>Change insurance company</Text>
        </Pressable>
      </View>
      <Body style={[s.small, { marginTop: 10 }]}>Your insurance company knows you when you log in or call. We don’t send them anything.</Body>
    </>);
  }
  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title={company ? 'Insurance' : 'Who’s your insurance?'} sub={company && myCar ? `Add your ${myCar.model} to ${company}` : 'Pick yours, or type it'} back={() => (changing ? setChanging(false) : back())} />
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={calm ? sheet.page : { flex: 1 }}>
        <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, paddingTop: 6 }} keyboardShouldPersistTaps="handled">
          {body}
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  search: { height: 50, borderWidth: 1.5, borderColor: C.yellow, borderRadius: 14, paddingHorizontal: 14, fontFamily: F.bodyBold, fontSize: 15, color: C.ink, backgroundColor: C.card },
  sec: { marginTop: 16, marginBottom: 6 },
  row: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 10, paddingVertical: 12 },
  line: { borderBottomWidth: 1, borderBottomColor: C.line },
  name: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink, flexShrink: 1 },
  chev: { fontFamily: F.bodyBold, fontSize: 18, color: C.muted },
  small: { fontSize: 12, color: C.muted, marginTop: 6, lineHeight: 17, fontFamily: F.body },
  k: { fontFamily: F.body, fontSize: 13.5, color: C.muted },
  v: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.ink, flexShrink: 1, textAlign: 'right' },
  two: { flexDirection: 'row', gap: 8 },
  fl: { fontSize: 10.5, color: C.muted, marginBottom: 4 },
  input: { height: 46, borderWidth: 1.5, borderColor: C.line, borderRadius: 12, paddingHorizontal: 10, fontFamily: F.bodyBold, fontSize: 14, color: C.ink, backgroundColor: C.card },
  link: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.yellow },
  done: { backgroundColor: 'rgba(31,157,85,0.12)', borderRadius: 14, padding: 12, marginBottom: 10 },
  doneT: { fontFamily: F.bodyBold, fontSize: 14, color: C.green },
}));
