// Opening (picture 49 · C4 "Rev needle", no headlights, picked Oct 14, 2026; replaces the
// headlight opening from pictures 20 and 36). The gold V swings into shape, then settles under a
// rev gauge. The needle shoots to 7 and drops back to idle while the engine revs
// (assets/sounds/rev.wav, made from the same sound as the demo). The gauge turns green with
// READY, then Login (or Home). About 3½ seconds. A tap skips it.
import { createAudioPlayer, type AudioPlayer } from 'expo-audio';
import { router } from 'expo-router';
import { useEffect, useState } from 'react';
import { AccessibilityInfo, StyleSheet, useWindowDimensions, View } from 'react-native';
import Svg, { Circle, Defs, G, Line, Path, Polygon, RadialGradient, Rect, Stop, Text as SvgText } from 'react-native-svg';

import { V_LEFT, V_RIGHT, VMark } from '@/components/brand';
import { useSaved } from '@/state/saved';
import { F, takeResume, themed } from '@/theme';
import { openingFinished } from '@/lib/alert-route';
import { Pressable, Text } from '@/components/t';

const REV_SOUND = require('../../assets/sounds/rev.wav');

// Timeline in ms: [start, length].
const T = {
  vIn: [200, 700], // the V halves swing up into shape
  move: [900, 500], // the V shrinks and drops under the gauge
  ring: [900, 400], // the gauge appears
  up: [1400, 900], // the needle shoots to 7
  down: [2300, 500], // and drops back to idle
  logo: [1200, 450],
  lit: 2800, // turns green, READY
  fade: 3200,
  end: 3600,
} as const;

// The gauge: a 270° arc open at the bottom, 0 to 8 (thousands of RPM), drawn in a 200 × 200 box.
const R = 86;
const START = 135;
const SWEEP = 270;
const pt = (deg: number, r = R) => {
  const a = (deg * Math.PI) / 180;
  return [100 + r * Math.cos(a), 100 + r * Math.sin(a)];
};
function arc(deg: number) {
  if (deg <= 0.01) return '';
  const [ax, ay] = pt(START);
  const [bx, by] = pt(START + deg);
  return `M${ax.toFixed(2)} ${ay.toFixed(2)} A${R} ${R} 0 ${deg > 180 ? 1 : 0} 1 ${bx.toFixed(2)} ${by.toFixed(2)}`;
}
const MARKS = Array.from({ length: 9 }, (_, i) => {
  const deg = START + (i * SWEEP) / 8;
  return { i, a: pt(deg, 74), b: pt(deg, 80), n: pt(deg, 63) };
});

const cl = (x: number) => Math.max(0, Math.min(1, x));
const mix = (a: number, b: number, k: number) => a + (b - a) * k;
const out3 = (k: number) => 1 - Math.pow(1 - cl(k), 3);
const io3 = (k: number) => { k = cl(k); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const io2 = (k: number) => { k = cl(k); return k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2; };
const at = (span: readonly [number, number], t: number, ease = out3) => ease((t - span[0]) / span[1]);
const GOLD = [205, 179, 139];
const GREEN = [59, 227, 127];
const color = (k: number) => `rgb(${GOLD.map((g, i) => Math.round(mix(g, GREEN[i], k))).join(',')})`;

function playRev(): AudioPlayer | null {
  try {
    const p = createAudioPlayer(REV_SOUND);
    p.play();
    return p;
  } catch {
    return null;
  }
}

export default function Opening() {
  const { prefs, ready } = useSaved();
  const { width, height } = useWindowDimensions();
  const [t, setT] = useState(0);
  const next = prefs.seenLogin ? '/home' : '/login';

  useEffect(() => {
    if (!ready) return;
    // Just switched White / Midnight: skip the opening and go back to where they were.
    const back = takeResume();
    if (back) { router.replace(back as '/me'); openingFinished(); return; }
    let gone = false;
    let raf = 0;
    const timer = setTimeout(() => { if (!gone) { gone = true; router.replace(next); openingFinished(); } }, T.end);
    const player = prefs.sound !== false ? playRev() : null;
    const t0 = Date.now();
    AccessibilityInfo.isReduceMotionEnabled().then((still) => {
      if (gone) return;
      if (still) { setT(T.lit + 300); return; }
      const tick = () => {
        const now = Date.now() - t0;
        setT(now);
        if (now < T.end && !gone) raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    }).catch(() => setT(T.lit + 300));
    return () => {
      gone = true;
      clearTimeout(timer);
      cancelAnimationFrame(raf);
      try { player?.remove(); } catch {}
    };
  }, [ready, next, prefs.sound]);

  const skip = () => { router.replace(next); openingFinished(); };

  // Where things go on this screen.
  const dial = Math.min(width * 0.66, 300);
  const cx = width / 2;
  const cy = height * 0.42;
  const word = Math.round(Math.min(26, width * 0.068));

  // Where we are in the timeline.
  const vin = at(T.vIn, t, io3);
  const move = at(T.move, t, io3);
  const ring = at(T.ring, t);
  const n = t < T.down[0] ? mix(0, 7.2 / 8, at(T.up, t, io3)) : mix(7.2 / 8, 1 / 8, at(T.down, t, io2));
  const lit = cl((t - T.lit) / 300);
  const fade = cl((t - T.fade) / 400);
  const logo = at(T.logo, t);
  const c = color(lit);

  const vw = dial * 0.212 * mix(2.6, 0.75, move);
  const vy = mix(cy, cy + dial * 0.25, move);
  const [nx, ny] = pt(START + SWEEP * n, 70);

  return (
    <Pressable onPress={skip} accessibilityRole="button" accessibilityLabel="Carvessa. Tap to skip" style={s.page}>
      <Svg width={width} height={height} style={StyleSheet.absoluteFill}>
        <Defs>
          <RadialGradient id="bg" cx="50%" cy="42%" r="70%">
            <Stop offset="0" stopColor="#1A2130" />
            <Stop offset="1" stopColor="#05070B" />
          </RadialGradient>
          <RadialGradient id="glow" cx="50%" cy="42%" r="45%">
            <Stop offset="0" stopColor="#3BE37F" stopOpacity={0.3} />
            <Stop offset="1" stopColor="#3BE37F" stopOpacity={0} />
          </RadialGradient>
        </Defs>
        <Rect width={width} height={height} fill="url(#bg)" />
        <Rect width={width} height={height} fill="url(#glow)" opacity={lit} />
      </Svg>

      <View style={{ flex: 1, opacity: 1 - fade }} accessible={false}>
        {/* The rev gauge. */}
        <View style={{ position: 'absolute', left: cx - dial / 2, top: cy - dial / 2, width: dial, height: dial, opacity: ring, transform: [{ scale: mix(0.9, 1, ring) }] }}>
          <Svg width={dial} height={dial} viewBox="0 0 200 200">
            <Circle cx={100} cy={100} r={97} fill="none" stroke="#2A303B" strokeWidth={1.5} strokeDasharray="2 6" />
            <Path d={arc(SWEEP)} fill="none" stroke="#1E2430" strokeWidth={9} strokeLinecap="round" />
            {lit > 0 && <Path d={arc(SWEEP)} fill="none" stroke="#3BE37F" strokeOpacity={0.35 * lit} strokeWidth={9} strokeLinecap="round" />}
            {MARKS.map(({ i, a, b, n: p }) => (
              <G key={i}>
                <Line x1={a[0]} y1={a[1]} x2={b[0]} y2={b[1]} stroke="#4A5262" strokeWidth={2} />
                <SvgText x={p[0]} y={p[1] + 4.5} fill={i >= 7 ? '#E0645A' : '#8E97A5'} fontSize={13} fontFamily={F.head} textAnchor="middle">{String(i)}</SvgText>
              </G>
            ))}
            <SvgText x={100} y={77} fill="#8E97A5" fontSize={9} letterSpacing={1} fontFamily={F.head} textAnchor="middle">RPM ×1000</SvgText>
            {n > 0.002 && <Path d={arc(SWEEP * n)} fill="none" stroke={c} strokeOpacity={0.25} strokeWidth={16} strokeLinecap="round" />}
            {n > 0.002 && <Path d={arc(SWEEP * n)} fill="none" stroke={c} strokeWidth={9} strokeLinecap="round" />}
            <Line x1={100} y1={100} x2={nx} y2={ny} stroke={lit ? c : '#F2F4F8'} strokeWidth={3.5} strokeLinecap="round" />
            <Circle cx={100} cy={100} r={7} fill="#2A303B" stroke={c} strokeWidth={2} />
          </Svg>
        </View>

        {/* The gold V: two halves swing up from the bottom point into shape. */}
        <View style={{ position: 'absolute', left: cx - vw / 2, top: vy - (vw * 0.92) / 2, width: vw, height: vw * 0.92, opacity: cl((vin - 0.2) / 0.5) }}>
          <Svg width={vw} height={vw * 0.92} viewBox="0 0 100 92">
            <Polygon points={V_LEFT} fill={c} rotation={-70 * (1 - vin)} originX={50} originY={92} />
            <Polygon points={V_RIGHT} fill={c} rotation={70 * (1 - vin)} originX={50} originY={92} />
          </Svg>
        </View>

        <View style={{ position: 'absolute', left: 0, right: 0, top: cy + dial / 2 + 18, alignItems: 'center', opacity: logo, transform: [{ translateY: (1 - logo) * 10 }] }}>
          <View style={{ flexDirection: 'row', alignItems: 'baseline' }}>
            <Text style={[s.word, { fontSize: word, letterSpacing: word * 0.06, color: '#FFFFFF' }]}>CAR</Text>
            <View style={{ marginLeft: word * 0.12, marginRight: word * 0.07 }}><VMark height={word * 0.75} color={c} /></View>
            <Text style={[s.word, { fontSize: word, letterSpacing: word * 0.06, color: c }]}>essa</Text>
          </View>
          <Text style={[s.ready, { opacity: lit }]}>READY</Text>
        </View>

        <Text style={[s.skip, { opacity: cl((t - 1000) / 400) * (1 - lit) }]}>Tap to skip</Text>
      </View>
    </Pressable>
  );
}

const s = themed(() => StyleSheet.create({
  page: { flex: 1, backgroundColor: '#05070B' },
  word: { fontFamily: F.logo },
  ready: { marginTop: 14, fontFamily: F.head, fontSize: 15, letterSpacing: 4, color: '#3BE37F' },
  skip: { position: 'absolute', bottom: 60, left: 0, right: 0, textAlign: 'center', fontFamily: F.head, fontSize: 14, letterSpacing: 2, textTransform: 'uppercase', color: '#8A8A8A' },
}));
