// Carvessa HQ shows the web test app (carvessa.app/try) inside a phone frame (picture 220 · 4).
// When the app runs inside another page, it tells that page which screen is open, so HQ's
// "What you're looking at" box can follow. Web only; sends only the screen path, nothing about the person.
import { usePathname } from 'expo-router';
import { useEffect } from 'react';
import { Platform } from 'react-native';

const HQ = ['https://hq.carvessa.app', 'https://carvessa-hq.pages.dev'];

export function FrameRoute() {
  const path = usePathname();
  useEffect(() => {
    if (Platform.OS !== 'web' || typeof window === 'undefined' || window.parent === window) return;
    for (const o of HQ) {
      try { window.parent.postMessage({ carvessa: 'route', path }, o); } catch { /* not that page */ }
    }
  }, [path]);
  return null;
}
