import { useEffect, useState } from 'react';

import { Facts, getFacts } from '@/data/gov';
import { useRefreshTick } from '@/lib/refresh';
import { LATEST_MODEL_YEAR } from '@/data/year';

export function useFacts(carId?: string, year = LATEST_MODEL_YEAR) {
  const key = carId ? `${carId}-${year}` : '';
  const [st, setSt] = useState<{ key: string; facts: Facts | null; failed: boolean }>({ key: '', facts: null, failed: false });
  const tick = useRefreshTick();
  useEffect(() => {
    if (!carId) return;
    let live = true;
    getFacts(carId, year)
      .then((f) => live && setSt({ key, facts: f, failed: false }))
      .catch(() => live && setSt({ key, facts: null, failed: true }));
    return () => { live = false; };
  }, [carId, year, key, tick]);
  const current = st.key === key;
  return { facts: current ? st.facts : null, loading: !!carId && !current, failed: current && st.failed };
}
