// "Same car at other dealers" on Check a car results (picture 147, Oct 25, 2026): the same model (year ±1) for sale
// near the shopper's ZIP, sorted by Top choice, price, miles or distance, each compared with the car you're looking at.
// Same Auto.dev feed as Cars for sale: only test accounts get real cars until Auto.dev says yes in writing.
import { router } from 'expo-router';
import { useEffect, useState } from 'react';
import { Image, StyleSheet, View } from 'react-native';

import { CarIcon } from '@/components/icons';
import { PriceTag } from '@/components/price-box';
import { Body, Label, tap } from '@/components/ui';
import type { Found as CarFound } from '@/data/check';
import { listingTag } from '@/data/fair-price';
import { findListings, skipAccidents, withoutAccidents, type Found } from '@/data/listings';
import { money } from '@/data/prices';
import { rank, sameCars, sortCars, versus, type Sort } from '@/data/same-car';
import { useAnswers } from '@/state/answers';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';
import { useRefreshTick } from '@/lib/refresh';

const GOLD = '#D9A92E';
const SORTS: [Sort, string][] = [['top', 'Top choice'], ['price', 'Price'], ['miles', 'Miles'], ['distance', 'Distance']];
const SHOW = 5;
// NHTSA writes brands in capitals (HONDA); dealers write Honda.
const brand = (m: string) => (['BMW', 'GMC'].includes(m.toUpperCase()) ? m.toUpperCase() : m.charAt(0).toUpperCase() + m.slice(1).toLowerCase());

export function SameCar({ found, vin, asking, miles, here }: { found: CarFound; vin?: string; asking?: number; miles?: number; here?: string }) {
  const { answers } = useAnswers();
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  const noWreck = skipAccidents(answers);
  const make = found.car?.make ?? brand(found.make);
  const model = found.car?.model ?? found.model;
  const key = zip ? `${make}/${model}-${zip}${noWreck ? '-nw' : ''}` : '';
  const [got, setGot] = useState<{ key: string; found: Found } | null>(null);
  const [retry, setRetry] = useState(0);
  const tick = useRefreshTick();
  useEffect(() => {
    if (!key) return;
    let on = true;
    const done = (raw: Found) => { if (on) { on = false; setGot({ key, found: noWreck ? withoutAccidents(raw) : raw }); } };
    // A weak signal never leaves it stuck on "Looking…".
    const slow = setTimeout(() => done({ kind: 'offline' }), 15000);
    findListings({ zip, models: [{ make, model }] }).then(done).catch(() => done({ kind: 'offline' }));
    return () => { on = false; clearTimeout(slow); };
  }, [key, zip, make, model, noWreck, retry, tick]);
  const res = got?.key === key ? got.found : null;
  const [by, setBy] = useState<Sort>('top');
  const [allYears, setAllYears] = useState(false);

  const openMap = () => { tap(); router.push({ pathname: '/shop', params: found.car ? { ids: found.car.id } : {} }); };
  const note = (title: string, line: string, onPress: () => void) => (
    <Pressable onPress={onPress} accessibilityRole="button" style={s.card}>
      <Body bold>{title}</Body>
      <Body style={s.small}>{line}</Body>
    </Pressable>
  );

  let body: React.ReactNode;
  if (!zip) body = note('See this car at other dealers', 'Add your ZIP code to see this car at other dealers near you.', openMap);
  else if (!res) body = <Body style={s.small}>{`Looking at other dealers near ${zip}…`}</Body>;
  else if (res.kind === 'soon') body = note('Coming soon', `Soon you’ll see this car at other dealers near ${zip}, sorted by price, miles and distance.`, openMap);
  else if (res.kind !== 'cars') body = note('Couldn’t load cars right now', 'Tap to try again.', () => { tap(); setRetry((n) => n + 1); });
  else {
    const me = { year: found.year, make, model, vin };
    const near = sameCars(res.cars, me);
    const every = sameCars(res.cars, me, true);
    const list = allYears ? every : near;
    if (!list.length) {
      body = (
        <View style={[s.card, s.empty]}>
          <Body bold style={{ textAlign: 'center' }}>{`No other ${model} for sale within 50 miles right now`}</Body>
          {every.length > 0
            ? <Pressable onPress={() => { tap(); setAllYears(true); }} accessibilityRole="button" style={s.btn}><Text style={s.btnText}>{`Show all years (${every.length})`}</Text></Pressable>
            : <Pressable onPress={openMap} accessibilityRole="button" style={s.btn}><Text style={s.btnText}>Look on the map ›</Text></Pressable>}
        </View>
      );
    } else {
      const cars = sortCars(rank(list), by);
      const years = [...new Set(list.map((l) => l.year))].sort();
      body = (
        <>
          <Body style={s.small}>{`${list.length} for sale near you · ${years.length > 1 ? `${years[0]}–${years[years.length - 1]}` : years[0]} ${model}`}</Body>
          {(asking || miles) ? (
            <View style={s.this}>
              <Text style={s.thisLabel} numberOfLines={1}>{here ? `You’re here · ${here}` : 'This car'}</Text>
              <Text style={s.thisVal}>{[asking ? money(asking) : null, miles ? `${miles.toLocaleString('en-US')} mi` : null].filter(Boolean).join(' · ')}</Text>
            </View>
          ) : null}
          <View style={s.chips} accessibilityRole="tablist">
            {SORTS.map(([k, label]) => (
              <Pressable key={k} onPress={() => { tap(); setBy(k); }} accessibilityRole="tab" accessibilityState={{ selected: by === k }} style={[s.chip, by === k && s.chipOn]}>
                <Text style={[s.chipText, by === k && { color: C.onAccent }]}>{label}</Text>
              </Pressable>
            ))}
          </View>
          {cars.slice(0, SHOW).map((l) => {
            const t = listingTag(l);
            const vs = versus(l, asking, miles);
            const big = l.top && by === 'top';
            return (
              <Pressable key={l.vin} onPress={() => { tap(); router.push({ pathname: '/listing/[vin]', params: { vin: l.vin } }); }} accessibilityRole="button"
                accessibilityLabel={`${l.top ? 'Top choice. ' : ''}${l.year} ${l.make} ${l.model}, ${money(l.price)}${l.miles != null ? `, ${l.miles.toLocaleString('en-US')} miles` : ''}, about ${l.min} minutes away`}
                style={[s.row, l.top && s.rowTop]}>
                {l.top && (
                  <View style={s.topLine}>
                    <View style={[s.badge, !big && s.badgeSmall]}><Text style={[s.badgeText, !big && { fontSize: 10.5, letterSpacing: 0 }]}>{big ? '★ TOP CHOICE' : '★ Top choice'}</Text></View>
                    {big && <Text style={s.why} numberOfLines={1}>{l.why.map((w, i) => <Text key={w}>{i ? ' · ' : ''}<Text>{w}</Text></Text>)}</Text>}
                  </View>
                )}
                <View style={{ flexDirection: 'row', gap: 10, alignItems: 'center' }}>
                  {l.photo ? <Image source={{ uri: l.photo }} style={s.photo} resizeMode="cover" /> : <View style={[s.photo, s.noPhoto]}><CarIcon size={26} color={C.muted} /></View>}
                  <View style={{ flex: 1, gap: 2 }}>
                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
                      <Text style={s.price}>{money(l.price)}</Text>
                      {t ? <PriceTag tag={t.tag} /> : null}
                    </View>
                    <Text style={s.facts} numberOfLines={1}>{[l.miles != null ? `${l.miles.toLocaleString('en-US')} mi` : null, `${l.min} min · ${l.city}`, allYears || years.length > 1 ? String(l.year) : null].filter(Boolean).join('  ·  ')}</Text>
                    {vs && <Text style={[s.vs, { color: vs.better ? C.green : C.muted }]} numberOfLines={1}>{vs.parts.map((p, i) => <Text key={p}>{i ? ' · ' : ''}<Text>{p}</Text></Text>)}</Text>}
                  </View>
                </View>
              </Pressable>
            );
          })}
          <Pressable onPress={openMap} accessibilityRole="button" style={{ paddingVertical: 10 }}>
            <Text style={s.more}>{`See all ${list.length} on the map ›`}</Text>
          </Pressable>
        </>
      );
    }
  }
  return (
    <View style={{ marginTop: 18 }}>
      <Label style={{ marginBottom: 4 }}>Same car at other dealers</Label>
      {body}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  small: { fontSize: 12.5, color: C.muted },
  card: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 14, padding: 12, gap: 2 },
  empty: { alignItems: 'center', gap: 10, paddingVertical: 16, borderStyle: 'dashed' },
  btn: { alignSelf: 'stretch', borderRadius: 999, backgroundColor: C.fill, paddingVertical: 10, alignItems: 'center' },
  btnText: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
  this: { flexDirection: 'row', justifyContent: 'space-between', backgroundColor: C.yellow + '1A', borderRadius: 10, paddingHorizontal: 10, paddingVertical: 7, marginTop: 8 },
  thisLabel: { flex: 1, fontFamily: F.body, fontSize: 13, color: C.ink },
  thisVal: { fontFamily: F.bodyBold, fontSize: 13, color: C.ink, marginLeft: 8 },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 10, marginBottom: 2 },
  chip: { borderWidth: 1.5, borderColor: C.line, borderRadius: 999, paddingHorizontal: 12, paddingVertical: 6, backgroundColor: C.card },
  chipOn: { backgroundColor: C.fill, borderColor: C.fill },
  chipText: { fontFamily: F.bodyBold, fontSize: 13, color: C.ink },
  row: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 14, padding: 10, marginTop: 8, gap: 6 },
  rowTop: { borderWidth: 2, borderColor: GOLD },
  topLine: { flexDirection: 'row', alignItems: 'center', gap: 8 },
  badge: { backgroundColor: GOLD, borderRadius: 999, paddingHorizontal: 9, paddingVertical: 3 },
  badgeSmall: { backgroundColor: GOLD + '33' },
  badgeText: { fontFamily: F.bodyBold, fontSize: 11, letterSpacing: 1, color: '#2A1E00' },
  why: { flex: 1, fontFamily: F.bodyBold, fontSize: 12, color: C.ink },
  photo: { width: 84, height: 56, borderRadius: 10 },
  noPhoto: { backgroundColor: C.line, alignItems: 'center', justifyContent: 'center' },
  price: { fontFamily: F.head, fontSize: 19, color: C.ink },
  facts: { fontFamily: F.bodyBold, fontSize: 12, color: C.ink },
  vs: { fontFamily: F.bodyBold, fontSize: 12 },
  more: { fontFamily: F.bodyBold, fontSize: 14, color: C.yellow, textAlign: 'center' },
}));
