// Coach History (picture 185, Nov 4, 2026): the last 3 chats on this phone. Unfinished = Continue / Delete,
// finished = See my picks / Change answers. A 4th chat replaces the oldest.
import { Modal, Pressable as RNPressable, ScrollView, StyleSheet, View } from 'react-native';

import { tap } from '@/components/ui';
import { chatTitle, walk } from '@/data/coach';
import { topMatches, type ChatRec } from '@/state/answers';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function dayOf(at: number) {
  const d = new Date(at), now = new Date();
  const days = Math.round((new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime() - new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()) / 864e5);
  return days <= 0 ? 'Today' : days === 1 ? 'Yesterday' : `${MONTHS[d.getMonth()]} ${d.getDate()}`;
}

export function ChatHistory({ history, openId, onContinue, onPicks, onChange, onDelete, onNew, onClose }: {
  history: ChatRec[]; openId: string;
  onContinue: (id: string) => void; onPicks: (id: string) => void; onChange: (id: string) => void;
  onDelete: (id: string) => void; onNew: () => void; onClose: () => void;
}) {
  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <View style={{ flex: 1, justifyContent: 'flex-end' }}>
        <RNPressable style={[StyleSheet.absoluteFill, s.back]} onPress={onClose} accessibilityLabel="Close" />
        <View style={s.sheet}>
          <View style={s.grab} />
          <Text style={s.h} accessibilityRole="header">Your last chats</Text>
          <Text style={s.sub}>Up to 3, kept on this phone. A 4th chat replaces the oldest.</Text>
          <ScrollView style={{ maxHeight: 460 }} contentContainerStyle={{ gap: 10, paddingTop: 12 }}>
            {!history.length && <Text style={s.sub}>No chats yet. Your chats will show here.</Text>}
            {history.map((c) => {
              const w = walk(c.chat, c.answers);
              const top = c.done ? topMatches(c.answers).map((m) => m.car.model).join(', ') : '';
              return (
                <View key={c.id} style={s.card}>
                  <Text style={s.when}>{`${dayOf(c.at)} · ${c.done ? 'Finished' : 'Not finished'}${c.id === openId ? ' · Open now' : ''}`}</Text>
                  <Text style={s.title}>{chatTitle(c.answers)}</Text>
                  <Text style={s.meta}>{c.done ? `Top 3: ${top}` : `Stopped at step ${w.stepNo} of ${w.total}`}</Text>
                  <View style={s.btns}>
                    {c.done ? (<>
                      <Btn label="See my picks" onPress={() => onPicks(c.id)} />
                      <Btn soft label="Change answers" onPress={() => onChange(c.id)} />
                    </>) : (<>
                      <Btn label="Continue" onPress={() => onContinue(c.id)} />
                      <Btn soft label="Delete" onPress={() => onDelete(c.id)} />
                    </>)}
                  </View>
                  {c.done && (
                    <Pressable onPress={() => { tap(); onDelete(c.id); }} accessibilityRole="button" style={{ alignSelf: 'flex-start', paddingTop: 8 }}>
                      <Text style={s.del}>Delete</Text>
                    </Pressable>
                  )}
                </View>
              );
            })}
          </ScrollView>
          <Pressable onPress={() => { tap(); onNew(); }} accessibilityRole="button" style={s.new}>
            <Text style={s.newT}>+ Start a new chat</Text>
          </Pressable>
        </View>
      </View>
    </Modal>
  );
}

function Btn({ label, soft, onPress }: { label: string; soft?: boolean; onPress: () => void }) {
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" style={[s.btn, soft && s.soft]}>
      <Text style={[s.btnT, soft && { color: C.onAccent }]}>{label}</Text>
    </Pressable>
  );
}

const s = themed(() => StyleSheet.create({
  back: { backgroundColor: 'rgba(15,26,42,0.45)' },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 26, borderTopRightRadius: 26, padding: 20, paddingBottom: 30 },
  grab: { alignSelf: 'center', width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, marginBottom: 14 },
  h: { fontFamily: F.head, fontSize: 21, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 13.5, color: C.muted, marginTop: 3 },
  card: { borderWidth: 1.5, borderColor: C.line, borderRadius: 16, padding: 12 },
  when: { fontFamily: F.bodyBold, fontSize: 11, letterSpacing: 0.6, textTransform: 'uppercase', color: C.muted },
  title: { fontFamily: F.bodyBold, fontSize: 15.5, color: C.ink, marginTop: 3 },
  meta: { fontFamily: F.body, fontSize: 13, color: C.muted, marginTop: 2 },
  btns: { flexDirection: 'row', gap: 8, marginTop: 10 },
  btn: { flex: 1, height: 44, borderRadius: 12, backgroundColor: C.hero, alignItems: 'center', justifyContent: 'center' },
  soft: { backgroundColor: C.fill },
  btnT: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.yellow },
  del: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.muted, textDecorationLine: 'underline' },
  new: { marginTop: 14, height: 50, borderRadius: 14, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  newT: { fontFamily: F.bodyBold, fontSize: 15.5, color: C.onAccent },
}));
