// "Show cars near you" (picture 258, Loudjier Nov 17, 2026: "ask them for a zip code… say to show cars near you.
// And use that ZIP code for both"). Shown once on Home for people with no ZIP yet. One ZIP then drives cars near
// you, Popular in your area, your state's tax in prices, the weather and sunset. Never blocks: Skip = Atlanta.
import { useRef, useState } from 'react';
import { Keyboard, Modal, StyleSheet, TextInput as RNTextInput, View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

import { Pressable, Text, TextInput } from '@/components/t';
import { tap } from '@/components/ui';
import { UseMyLocation } from '@/components/use-location';
import { useAnswers } from '@/state/answers';
import { useSaved } from '@/state/saved';

export function ZipSheet() {
  const { answers, setAnswers } = useAnswers();
  const { prefs, setPrefs, ready } = useSaved();
  const [zip, setZip] = useState('');
  const input = useRef<RNTextInput>(null);
  const has = !!answers.zip && /^\d{5}$/.test(answers.zip);
  if (!ready || has || prefs.zipAsked) return null;
  const done = (z?: string) => {
    Keyboard.dismiss();
    if (z && /^\d{5}$/.test(z)) setAnswers({ ...answers, zip: z });
    setPrefs({ ...prefs, zipAsked: true });
  };
  const ok = /^\d{5}$/.test(zip);
  return (
    <Modal transparent animationType="slide" visible onRequestClose={() => done()}>
      <View style={st.wrap}>
        <Pressable style={StyleSheet.absoluteFill} onPress={() => done()} accessibilityLabel="Skip for now" />
        <View style={st.sheet}>
          <View style={st.grab} />
          <Text style={st.h} accessibilityRole="header">Show cars near you</Text>
          <Text style={st.p}>Type your ZIP code and we’ll show cars, prices and the weather for your area.</Text>
          <Pressable onPress={() => input.current?.focus()} accessible={false} style={st.boxes}>
            {[0, 1, 2, 3, 4].map((i) => (
              <View key={i} style={[st.box, i === Math.min(zip.length, 4) && st.boxOn]}><Text style={st.digit}>{zip[i] ?? ''}</Text></View>
            ))}
            <TextInput ref={input} value={zip} onChangeText={(t) => setZip(t.replace(/\D/g, '').slice(0, 5))} keyboardType="number-pad" maxLength={5}
              autoComplete="postal-code" textContentType="postalCode" accessibilityLabel="ZIP code" style={st.hidden} onSubmitEditing={() => ok && done(zip)} />
          </Pressable>
          <Pressable onPress={() => { tap(); if (ok) done(zip); else input.current?.focus(); }} accessibilityRole="button" style={[st.btn, !ok && { opacity: 0.55 }]}>
            <Text style={st.btnT}>Show cars near me</Text>
          </Pressable>
          <UseMyLocation needZip onSpot={(sp) => done(sp.zip ?? undefined)} style={{ marginTop: 10 }} />
          <Pressable onPress={() => { tap(); done(); }} accessibilityRole="button" hitSlop={8} style={{ alignSelf: 'center', marginTop: 12 }}>
            <Text style={st.skip}>Skip for now · we’ll use Atlanta</Text>
          </Pressable>
          <View style={st.priv}>
            <Svg width={16} height={16} viewBox="0 0 16 16" fill="none" stroke="#147A4B" strokeWidth={1.6}><Path d="M8 1.5 2.5 3.5v4c0 3.4 2.4 5.9 5.5 7 3.1-1.1 5.5-3.6 5.5-7v-4z" /><Path d="m5.5 8 1.8 1.8L10.8 6" /></Svg>
            <Text style={st.privT}>We keep only your ZIP, never your exact spot. Change it anytime in Me.</Text>
          </View>
        </View>
      </View>
    </Modal>
  );
}

const st = StyleSheet.create({
  wrap: { flex: 1, justifyContent: 'flex-end', backgroundColor: 'rgba(8,14,30,0.45)' },
  sheet: { backgroundColor: '#FFFFFF', borderTopLeftRadius: 30, borderTopRightRadius: 30, paddingHorizontal: 22, paddingTop: 12, paddingBottom: 34 },
  grab: { alignSelf: 'center', width: 44, height: 5, borderRadius: 9, backgroundColor: '#D6DDE8', marginBottom: 14 },
  h: { fontSize: 22, fontWeight: '800', color: '#10151B' },
  p: { fontSize: 14, lineHeight: 20, color: '#4A5465', marginTop: 6, marginBottom: 14 },
  boxes: { flexDirection: 'row', gap: 8, marginBottom: 12 },
  box: { flex: 1, height: 56, borderRadius: 14, borderWidth: 2, borderColor: '#E1E7F0', alignItems: 'center', justifyContent: 'center' },
  boxOn: { borderColor: '#1F5FBF' },
  digit: { fontSize: 24, fontWeight: '800', color: '#10151B' },
  hidden: { position: 'absolute', left: 0, top: 0, width: '100%', height: '100%', opacity: 0.02, color: 'transparent' },
  btn: { backgroundColor: '#1F5FBF', borderRadius: 99, paddingVertical: 15, alignItems: 'center' },
  btnT: { color: '#FFFFFF', fontSize: 15, fontWeight: '800' },
  skip: { fontSize: 13, fontWeight: '700', color: '#5B6575' },
  priv: { flexDirection: 'row', gap: 8, alignItems: 'flex-start', marginTop: 14, backgroundColor: '#F4F6FA', borderRadius: 14, padding: 11 },
  privT: { flex: 1, fontSize: 12, lineHeight: 17, color: '#3A4456' },
});
