// "Cost to own" math. Every number here is an ESTIMATE to help people plan, never a quote.
// Real numbers used: the car's price (prices.ts) and its EPA gas mileage (gov.ts).

export const CREDIT: { label: string; apr: number; used: number }[] = [
  // Rough average loan rates by credit level: new car, used car (same as TIERS in afford.ts).
  { label: 'Excellent', apr: 6, used: 7 },
  { label: 'Good', apr: 8, used: 10 },
  { label: 'Fair', apr: 12, used: 14.5 },
  { label: 'Rebuilding', apr: 17, used: 20 },
];
export const TERMS = [36, 48, 60, 72];

export function monthlyPayment(loan: number, aprPct: number, months: number) {
  if (loan <= 0) return 0;
  const r = aprPct / 100 / 12;
  return r === 0 ? loan / months : (loan * r) / (1 - Math.pow(1 + r, -months));
}

export type CostInput = {
  price: number;
  isNew: boolean;
  ageYears: number; // how old the car is when bought
  mpg?: number; // EPA combined; for electric cars this is MPGe
  electric?: boolean;
  milesPerYear: number;
  gasPrice: number; // $ per gallon
  kwhPrice: number; // $ per kWh, for electric cars
  down: number;
  apr: number;
  months: number;
  taxPct: number;
};

export type CostResult = {
  parts: { label: string; amount: number }[];
  total5: number;
  perMonth: number;
  payment: number;
  interest: number;
};

export function fiveYearCost(i: CostInput): CostResult {
  const tax = (i.price * i.taxPct) / 100;
  const loan = Math.max(0, i.price + tax - i.down);
  const payment = monthlyPayment(loan, i.apr, i.months);
  const interest = Math.max(0, payment * i.months - loan);

  // Fuel: gallons per year × gas price. Electric: kWh per mile = 33.7 / MPGe.
  const miles5 = i.milesPerYear * 5;
  const fuel = i.mpg ? (i.electric ? (miles5 * 33.7 * i.kwhPrice) / i.mpg : (miles5 / i.mpg) * i.gasPrice) : miles5 * 0.15;

  // Value lost in 5 years: newer cars lose more at first.
  const lossShare = i.isNew ? 0.45 : i.ageYears <= 2 ? 0.38 : 0.3;
  const valueLost = i.price * lossShare;

  // Insurance and upkeep, rough yearly amounts that grow with price and age.
  const insurance = 5 * Math.min(4500, 1300 + i.price * 0.022);
  const upkeep = 5 * (i.electric ? 450 : 650 + i.ageYears * 120) + Math.min(5000, i.price * 0.02);

  const parts = [
    { label: 'Value lost', amount: valueLost },
    { label: i.electric ? 'Charging' : 'Gas', amount: fuel },
    { label: 'Insurance', amount: insurance },
    { label: 'Upkeep and repairs', amount: upkeep },
    { label: 'Sales tax', amount: tax },
    { label: 'Loan interest', amount: interest },
  ];
  const total5 = parts.reduce((t, p) => t + p.amount, 0);
  return { parts, total5, perMonth: total5 / 60, payment, interest };
}

export const round = (n: number, to = 10) => Math.round(n / to) * to;

/** The 5-year cost with the same starting settings as the cost page (12,000 mi, $3.30 gas, $2,000 down, Good credit, 60 months, your state's tax). */
export function quickFiveYear(price: number, isNew: boolean, ageYears: number, mpg?: number, electric?: boolean, taxPct = 7) {
  const good = CREDIT[1];
  return fiveYearCost({ price, isNew, ageYears, mpg, electric, milesPerYear: 12000, gasPrice: 3.3, kwhPrice: 0.17, down: 2000, apr: isNew ? good.apr : good.used, months: 60, taxPct });
}
