// "What's new" (picture 41, style C "Bell on Home", picked Oct 13, 2026).
// Not general car news: only news about the person's saved cars and their money.
// Step 1 (built): recalls on saved cars (NHTSA) + car loan rates (Federal Reserve, via the
// `loan-rates` Supabase function). Step 2 (later): deals, new models and Sponsored offers from
// sources we may legally use. Every item says where it came from; paid items say "Sponsored".
// "Seen" is kept on this phone; the bell shows how many items the person hasn't seen yet.
import AsyncStorage from '@react-native-async-storage/async-storage';
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';

import { carName, CARS } from '@/data/cars';
import { outTheDoor } from '@/data/afford';
import { monthlyPayment } from '@/data/costs';
import { money, priceFor } from '@/data/prices';
import { SUPABASE_URL } from '@/lib/supabase';
import { useRecalls } from '@/state/recalls';
import { useSaved } from '@/state/saved';

export type NewsKind = 'recall' | 'money' | 'deal' | 'new';
export type NewsItem = {
  id: string;
  kind: NewsKind;
  tag: string;
  title: string;
  sub: string;
  source: string;
  at: number; // when it happened (ms), for sorting
  car?: { id: string; year: number };
  sponsored?: boolean;
};
type Rates = { latest: { date: string; rate: number }; previous: { date: string; rate: number }; source: string };

const KEY = 'carvessa:news-seen:v1';
const MONTHS = 60;
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const nice = (s: string) => s.split(':')[0].toLowerCase().replace(/^./, (x) => x.toUpperCase());
// NHTSA dates look like "26/04/2024" (day/month/year).
function nhtsaDate(s: string) {
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  return m ? new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1])) : null;
}
const shortDate = (d: Date) => `${MONTH_NAMES[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;

type Ctx = { items: NewsItem[]; unseen: number; isNew: (id: string) => boolean; markAllSeen: () => void };
const NewsCtx = createContext<Ctx>({ items: [], unseen: 0, isNew: () => false, markAllSeen: () => {} });

export function NewsProvider({ children }: { children: React.ReactNode }) {
  const { saved } = useSaved();
  const { byCar } = useRecalls();
  const [rates, setRates] = useState<Rates | null>(null);
  const [seen, setSeen] = useState<string[] | null>(null);

  useEffect(() => {
    AsyncStorage.getItem(KEY).then((raw) => setSeen(raw ? JSON.parse(raw) : [])).catch(() => setSeen([]));
    fetch(`${SUPABASE_URL}/functions/v1/loan-rates`).then((r) => (r.ok ? r.json() : null)).then((j) => { if (j?.latest) setRates(j); }).catch(() => {});
  }, []);

  const items = useMemo(() => {
    const out: NewsItem[] = [];
    // Recalls on saved cars, newest first.
    for (const c of Object.values(byCar)) {
      const car = CARS.find((x) => x.id === c.id);
      if (!car) continue;
      for (const r of c.recalls) {
        const d = nhtsaDate(r.date);
        out.push({
          id: `recall:${c.key}:${r.id}`, kind: 'recall', tag: 'Recall · saved car',
          title: `${carName(car, c.year)}: ${nice(r.part)} recall`,
          sub: 'Recall repairs are free at the dealer. Tap to see what to do.',
          source: `From NHTSA${d ? ` · ${shortDate(d)}` : ''}`, at: d?.getTime() ?? 0, car: { id: c.id, year: c.year },
        });
      }
    }
    // Car loan rates, with what the change means for a saved car's payment (an estimate).
    if (rates) {
      const { latest, previous } = rates;
      const diff = latest.rate - previous.rate;
      const first = saved.map((x) => ({ x, car: CARS.find((c) => c.id === x.id) })).find((v) => v.car && priceFor(v.car, v.x.year));
      const price = first ? priceFor(first.car!, first.x.year)!.amount : 0;
      const loan = price ? Math.round(outTheDoor(price) * 0.9) : 30000;
      const change = Math.round(monthlyPayment(loan, latest.rate, MONTHS) - monthlyPayment(loan, previous.rate, MONTHS));
      const on = first ? `on the ${carName(first.car!, first.x.year)}` : `on a ${money(30000)} loan`;
      const d = new Date(`${latest.date}T12:00:00`);
      const steady = Math.abs(diff) < 0.05 || change === 0;
      out.push({
        id: `money:rates:${latest.date}`, kind: 'money', tag: 'Your payment',
        title: steady ? 'Car loan rates held steady' : `Car loan rates went ${diff > 0 ? 'up' : 'down'}`,
        sub: `Average 5-year new-car loan: ${previous.rate.toFixed(2)}% → ${latest.rate.toFixed(2)}%.` +
          (steady ? '' : ` ${on[0].toUpperCase()}${on.slice(1)}, that’s about $${Math.abs(change)} a month ${diff > 0 ? 'more' : 'less'}.`),
        source: `Estimate · Federal Reserve data · ${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}`, at: d.getTime(),
      });
    }
    return out.sort((a, b) => (a.kind === 'recall' ? 0 : 1) - (b.kind === 'recall' ? 0 : 1) || b.at - a.at);
  }, [byCar, rates, saved]);

  const markAllSeen = useCallback(() => {
    if (!items.length || !seen) return;
    // Nothing new: don't save again (saving changes `seen`, which would run this again and again).
    const old = new Set(seen);
    if (items.every((i) => old.has(i.id))) return;
    const next = [...new Set([...seen, ...items.map((i) => i.id)])].slice(-500);
    setSeen(next);
    AsyncStorage.setItem(KEY, JSON.stringify(next)).catch(() => {});
  }, [items, seen]);

  const value = useMemo(() => {
    const old = new Set(seen ?? []);
    const isNew = (id: string) => !!seen && !old.has(id);
    return { items, unseen: seen ? items.filter((i) => !old.has(i.id)).length : 0, isNew, markAllSeen };
  }, [items, seen, markAllSeen]);

  return <NewsCtx.Provider value={value}>{children}</NewsCtx.Provider>;
}

export const useNews = () => useContext(NewsCtx);
