// My car reminders (picture 221 A, Loudjier Nov 13, 2026: "insurance payment, car payment, service, etc… the user will
// choose when they want to be reminded… monthly, yearly… 3 days before, a week… all this require an account").
// Kept with each car (MyCar.reminders), on the phone and in the free account. The phone sets the notifications itself
// (lib/reminders.ts), so they work with no internet. Amounts are only what the person typed.

export type RemKind = 'insurance' | 'payment' | 'oil' | 'service' | 'tag' | 'emissions' | 'wash' | 'custom';
export type Every = 'once' | '2w' | '1m' | '3m' | '6m' | '1y';
export type CarReminder = {
  id: string; kind: RemKind; label?: string; amount?: number;
  due: number; // next due day (noon, phone time)
  every: Every; before: 0 | 1 | 3 | 7 | 14; time: string; // 'HH:MM'
  off?: boolean;
};

export const REM_KINDS: { kind: RemKind; label: string; every: Every; before: CarReminder['before'] }[] = [
  { kind: 'insurance', label: 'Insurance', every: '1m', before: 3 },
  { kind: 'payment', label: 'Car payment', every: '1m', before: 3 },
  { kind: 'oil', label: 'Oil change', every: '6m', before: 7 },
  { kind: 'service', label: 'Service', every: '6m', before: 7 },
  { kind: 'tag', label: 'Tag renewal', every: '1y', before: 14 },
  { kind: 'emissions', label: 'Emissions test', every: '1y', before: 14 },
  { kind: 'wash', label: 'Car wash', every: '2w', before: 0 },
  { kind: 'custom', label: '+ My own', every: 'once', before: 1 },
];
export const EVERY: { every: Every; label: string }[] = [
  { every: 'once', label: 'Once' }, { every: '2w', label: 'Every 2 weeks' }, { every: '1m', label: 'Every month' },
  { every: '3m', label: 'Every 3 months' }, { every: '6m', label: 'Every 6 months' }, { every: '1y', label: 'Every year' },
];
export const BEFORE: { before: CarReminder['before']; label: string }[] = [
  { before: 0, label: 'On the day' }, { before: 1, label: '1 day before' }, { before: 3, label: '3 days before' },
  { before: 7, label: '1 week before' }, { before: 14, label: '2 weeks before' },
];
export const TIMES = ['08:00', '09:00', '12:00', '18:00'];

/** "Car payment" only when the car is financed or leased (Loudjier, Nov 12: "If they own it car payment option
 *  shouldn't be available"). Unknown counts as maybe-financed. */
export const kindsFor = (how: 'own' | 'finance' | 'lease' | null) => REM_KINDS.filter((k) => k.kind !== 'payment' || how !== 'own');

export const remName = (r: Pick<CarReminder, 'kind' | 'label'>) =>
  r.kind === 'custom' ? (r.label?.trim() || 'Reminder') : r.kind === 'insurance' ? 'Insurance payment' : REM_KINDS.find((k) => k.kind === r.kind)!.label;

const noon = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate(), 12).getTime();
export function addEvery(t: number, every: Every): number {
  const d = new Date(t);
  if (every === '2w') return noon(new Date(d.getFullYear(), d.getMonth(), d.getDate() + 14));
  const months = every === '1m' ? 1 : every === '3m' ? 3 : every === '6m' ? 6 : every === '1y' ? 12 : 0;
  if (!months) return t;
  // Keep the day of the month; the 31st becomes the last day of a shorter month.
  const y = d.getFullYear(), m = d.getMonth() + months;
  const last = new Date(y, m + 1, 0).getDate();
  return noon(new Date(y, m, Math.min(d.getDate(), last)));
}

/** The next due day on or after today (a repeating one moves forward on its own). */
export function remDue(r: Pick<CarReminder, 'due' | 'every'>, now: number): number {
  const today = noon(new Date(now));
  let t = noon(new Date(r.due));
  if (r.every === 'once') return t;
  for (let i = 0; i < 600 && t < today; i++) t = addEvery(t, r.every);
  return t;
}

/** When the phone should remind: `before` days ahead at their time. Null when it's off or already past. */
export function alertAt(r: CarReminder, now: number): Date | null {
  if (r.off) return null;
  const due = new Date(remDue(r, now));
  const [h, m] = r.time.split(':').map(Number);
  const at = new Date(due.getFullYear(), due.getMonth(), due.getDate() - r.before, h || 9, m || 0);
  return at.getTime() > now ? at : null;
}

/** "Mark paid / done": a repeating one moves to the next time, a one-time one turns off. */
export function markDone(r: CarReminder, now: number): CarReminder {
  if (r.every === 'once') return { ...r, off: true };
  return { ...r, due: addEvery(remDue(r, now), r.every) };
}

export const daysLeft = (r: Pick<CarReminder, 'due' | 'every'>, now: number) =>
  Math.round((remDue(r, now) - noon(new Date(now))) / 86400000);

/** Soonest first; turned-off ones last. */
export const sortReminders = (list: CarReminder[], now: number) =>
  [...list].sort((a, b) => Number(!!a.off) - Number(!!b.off) || remDue(a, now) - remDue(b, now));

export const newId = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
