// Smart car finder card (Loudjier, Nov 12, 2026: "the smart AI car search is gone… what type of car, budget,
// upgrade, style, payment… This option should be available in search as an option too"). The coach was still
// there, but in Design 5 it hid behind a small "Coach" tile. This card shows it plainly on Home (after the
// afford card, once they have a plan) and at the top of Search: their answers in one line, "Your top 3",
// "New search" and "Upgrade my car".
import { router } from 'expo-router';
import { StyleSheet, View } from 'react-native';

import { CoachIcon } from '@/components/icons';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { carNowOf } from '@/data/coach';
import { tr } from '@/i18n';
import { monthlyCap, useAnswers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { C, F, themed } from '@/theme';

/** Their coach answers in a few plain words ("First car · SUV · $400/mo"). */
export function finderSummary(a: { goal?: string; kind?: string; budget?: string; pay?: string; monthly?: string; myCar?: string }): string {
  const parts: string[] = [];
  if (a.myCar) parts.push(`${tr('Upgrading from')} ${a.myCar}`);
  else if (a.goal) parts.push(tr(a.goal));
  if (a.kind && !a.kind.startsWith('Not sure')) parts.push(tr(a.kind));
  const cap = monthlyCap(a as never);
  if (cap) parts.push(`$${cap}/mo`);
  else if (a.budget) parts.push(tr(a.budget));
  return parts.join(' · ');
}

export function SmartFinder({ style }: { style?: object }) {
  const { answers, startChat } = useAnswers();
  const { myCar } = useSaved();
  const started = !!answers.goal;
  const summary = started ? finderSummary(answers) : '';
  const fresh = () => { tap(); startChat(); router.push('/coach'); };
  const upgrade = () => { tap(); startChat('Upgrade my car', myCar ? carNowOf(myCar) : undefined); router.push('/coach'); };
  return (
    <View style={[s.card, style]}>
      <View style={s.head}>
        <View style={s.icon}><CoachIcon size={22} color={C.onAccent} /></View>
        <View style={{ flex: 1 }}>
          <Text style={s.title}>Smart car finder</Text>
          <Text style={s.sub} numberOfLines={2}>{started && summary ? summary : 'Car type, budget or monthly payment, how you pay. Get your top 3.'}</Text>
        </View>
      </View>
      <View style={s.row}>
        {started ? (<>
          <Pressable onPress={() => { tap(); router.push({ pathname: '/results', params: { upgrade: '0' } }); }} accessibilityRole="button" style={[s.btn, s.main]}>
            <Text style={[s.btnT, { color: C.onAccent }]}>Your top 3</Text>
          </Pressable>
          <Pressable onPress={fresh} accessibilityRole="button" style={s.btn}><Text style={s.btnT}>New search</Text></Pressable>
        </>) : (
          <Pressable onPress={fresh} accessibilityRole="button" style={[s.btn, s.main]}>
            <Text style={[s.btnT, { color: C.onAccent }]}>Start · 2 minutes</Text>
          </Pressable>
        )}
        <Pressable onPress={upgrade} accessibilityRole="button" style={s.btn}><Text style={s.btnT}>Upgrade my car</Text></Pressable>
      </View>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  card: { marginTop: 12, borderRadius: 20, padding: 14, backgroundColor: C.card, borderWidth: 1.5, borderColor: C.yellow },
  head: { flexDirection: 'row', alignItems: 'center', gap: 12 },
  icon: { width: 42, height: 42, borderRadius: 13, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  title: { fontFamily: F.head, fontSize: 17, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 13, color: C.muted, marginTop: 1, lineHeight: 18 },
  row: { flexDirection: 'row', flexWrap: 'wrap', gap: 8, marginTop: 12 },
  btn: { flexGrow: 1, borderRadius: 14, paddingVertical: 10, paddingHorizontal: 12, alignItems: 'center', borderWidth: 1, borderColor: C.line },
  main: { backgroundColor: C.fill, borderColor: C.fill },
  btnT: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.ink },
}));
