// Car paint colors from dealer listings, sorted into simple groups (picture 75 A + D, Oct 16, 2026).
// Dealers write fancy names ("Lunar Silver Metallic", "Crystal Black Pearl"); shoppers think in
// White, Black, Gray… so we match the plain color word first, then the fancy ones.
export type ColorFamily = 'White' | 'Black' | 'Gray' | 'Silver' | 'Blue' | 'Red' | 'Green' | 'Brown' | 'Gold' | 'Orange' | 'Yellow' | 'Purple' | 'Other';

export const FAMILIES: { name: ColorFamily; hex: string }[] = [
  { name: 'White', hex: '#F1EFEA' },
  { name: 'Black', hex: '#141516' },
  { name: 'Gray', hex: '#5E646B' },
  { name: 'Silver', hex: '#C3C7CC' },
  { name: 'Blue', hex: '#24407A' },
  { name: 'Red', hex: '#9B1C1C' },
  { name: 'Green', hex: '#2F5D3A' },
  { name: 'Brown', hex: '#7A5A3C' },
  { name: 'Gold', hex: '#C2A060' },
  { name: 'Orange', hex: '#D9622B' },
  { name: 'Yellow', hex: '#E3C21B' },
  { name: 'Purple', hex: '#5B3A7A' },
  { name: 'Other', hex: '#9AA0AA' },
];
export const hexOf = (f: ColorFamily) => FAMILIES.find((x) => x.name === f)!.hex;

// Plain color words win over fancy ones ("Midnight Blue" is Blue, "Steel Gray" is Gray).
const PLAIN: [RegExp, ColorFamily][] = [
  [/\bblue\b/, 'Blue'], [/\bred\b/, 'Red'], [/\bgreen\b/, 'Green'], [/\bwhite\b/, 'White'], [/\bblack\b/, 'Black'],
  [/\bsilver\b/, 'Silver'], [/\bgr[ae]y\b/, 'Gray'], [/\bbrown\b|\bbeige\b|\btan\b/, 'Brown'], [/\bgold\b/, 'Gold'],
  [/\borange\b/, 'Orange'], [/\byellow\b/, 'Yellow'], [/\bpurple\b|\bviolet\b/, 'Purple'],
];
const FANCY: [RegExp, ColorFamily][] = [
  [/obsidian|ebony|onyx|jet|panther|raven|midnight|shadow/, 'Black'],
  [/ivory|snow|alabaster|frost|pearl|glacier|arctic|summit/, 'White'],
  [/lunar|sterling|billet|ingot|platinum|quicksilver|moonstone/, 'Silver'],
  [/graphite|gunmetal|charcoal|steel|magnetic|slate|cement|meteor|carbon|granite|titanium|ash|smoke|storm/, 'Gray'],
  [/navy|azure|cobalt|sapphire|aqua|ocean|denim|indigo/, 'Blue'],
  [/ruby|crimson|burgundy|maroon|wine|cherry|garnet|scarlet/, 'Red'],
  [/sage|olive|forest|emerald|army|lime|cactus|jade/, 'Green'],
  [/bronze|sand|copper|mocha|espresso|desert|khaki|caramel|champagne/, 'Brown'],
  [/sunset|amber|tangerine/, 'Orange'],
  [/plum|amethyst/, 'Purple'],
];

export function colorFamily(name?: string | null): ColorFamily {
  const n = (name ?? '').toLowerCase();
  if (!n.trim()) return 'Other';
  for (const [re, f] of PLAIN) if (re.test(n)) return f;
  for (const [re, f] of FANCY) if (re.test(n)) return f;
  return 'Other';
}

/** How many cars of each color, most common first ("Other" last). */
export function colorCounts(colors: (string | null | undefined)[]): { name: ColorFamily; count: number }[] {
  const m = new Map<ColorFamily, number>();
  for (const c of colors) { const f = colorFamily(c); m.set(f, (m.get(f) ?? 0) + 1); }
  return [...m.entries()].map(([name, count]) => ({ name, count }))
    .sort((a, b) => (a.name === 'Other' ? 1 : 0) - (b.name === 'Other' ? 1 : 0) || b.count - a.count);
}
