// Fee check (picture 151 panels 2 + 4, Oct 26, 2026): the dealer's fees next to what most dealers in the shopper's
// state charge, the tax that isn't in a dealer's price, and the out-the-door total. All ESTIMATES. Friendly words only:
// we say "ask about it", never that a fee is a trick. State numbers come from our 50-state table (state-costs.ts).
import { carTax, costsFor, homeState, STATES, TITLE_REG } from '@/data/state-costs';

export type FeeCheck = {
  carPrice: number; // before dealer fees
  fees: number | null; // what the dealer charges; null = not typed yet (we use the state average)
  usual: number; // most dealers in this state, about
  extra: number; // fees above `usual` (0 when at or under)
  high: boolean; // worth a friendly question
  tax: number; taxName: string; rate: number; state: string | null;
  title: number;
  total: number;
};

// Fees this much over the state average are worth a friendly question.
export const ASK_OVER = 150;

/** price = the dealer's price; includesFees = that price already has the fees in it ("all-in"). */
export function feeCheck(price: number, fees: number | null, includesFees = false, st: string | null = homeState()): FeeCheck {
  const c = costsFor(st);
  const f = fees != null && fees >= 0 ? fees : null;
  const carPrice = Math.max(0, includesFees && f != null ? price - f : price);
  const dealerFees = f ?? c.doc;
  const tax = carTax(carPrice, st);
  const extra = f == null ? 0 : Math.max(0, f - c.doc);
  return {
    carPrice, fees: f, usual: c.doc, extra, high: extra >= ASK_OVER,
    tax, taxName: c.taxName, rate: c.tax, state: st && STATES[st] ? c.name : null,
    title: TITLE_REG, total: Math.round(carPrice + dealerFees + tax + TITLE_REG),
  };
}

/** "$400" rounded to the nearest $50, so it reads like an about-number. */
export const aboutDollars = (n: number) => `$${(Math.round(n / 50) * 50).toLocaleString('en-US')}`;
